INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C1','math',6,1,'u4',2,'두 양을 차와 배로 비교하기 — 뺄셈으로 비교하면 차, 나눗셈으로 비교하면 몇 배인지 알 수 있고, 두 양이 같은 배로 늘어나면 차는 변하지만 배로 비교한 관계는 변하지 않음을 알기',ARRAY['6수04-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C2','math',6,1,'u4',2,'비 알기 — 두 양의 변하지 않는 관계를 기호 ：을 써서 2：10처럼 나타내고, 「○에 대한」 쪽이 기준량(후항), 다른 쪽이 비교하는 양(전항)임을 알며, 순서를 바꾸면 다른 비가 됨을 알기',ARRAY['6수04-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C3','math',6,1,'u4',3,'비율 알기 — 기준량에 대한 비교하는 양의 크기를 (비교하는 양) ÷ (기준량)으로 구해 분수나 소수로 나타내고, 비율이 1보다 클 수도 있으며 기준량이 달라도 관계가 같으면 비율이 같음을 알기',ARRAY['6수04-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C4','math',6,1,'u4',4,'비율이 사용되는 경우 — 경기 결과(전체 경기 수에 대한 이긴 경기 수), 걸린 시간에 대한 이동 거리, 넓이에 대한 인구, 지도의 거리처럼 생활 속 비율을 구하고, 기준이 다른 것끼리는 수가 아니라 비율로 비교하기',ARRAY['6수04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C5','math',6,1,'u4',5,'백분율 알기 — 기준량을 100으로 할 때의 비율을 백분율이라 하고 기호 %로 나타내며, 기준량이 100인 비율로 바꾸거나 비율에 100을 곱해 백분율로 나타내고, 백분율을 분수·소수로도 바꾸기',ARRAY['6수04-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C6','math',6,1,'u4',6,'백분율이 사용되는 경우 — 득표율, 이자율, 할인율(원래 가격에 대한 할인 금액), 설탕물의 진하기(설탕물 양에 대한 설탕 양)를 백분율로 구하고, 금액이나 양이 아니라 백분율로 비교하기',ARRAY['6수04-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u4-C7','math',6,1,'u4',7,'백분율로 문제 해결하기 — 이해·계획·해결·검토 네 단계로, 전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해 전체의 몇 %인 양을 구하며, 조건이 바뀌면 기준량이 무엇인지 다시 확인하고 구한 답을 비율로 만들어 검토하기',ARRAY['6수04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X01','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4']::text[],'기준량과 비교하는 양을 바꾸어 비를 쓴다(「바닷물 양에 대한 소금 양의 비」를 150：6으로)','「○에 대한」 쪽이 기준량, 뒤에 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X02','math',6,'u4',ARRAY['M6-1-u4-C2']::text[],'비의 순서를 바꾸어도 같은 비라고 본다(3：4와 4：3을 같다고)','기준량이 바뀌면 다른 비') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X03','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C4']::text[],'몇 배인지 비교해야 할 때 뺄셈으로 차를 구하거나, 몇 배로 늘려야 할 때 같은 수를 더한다','「몇 배」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X04','math',6,'u4',ARRAY['M6-1-u4-C1']::text[],'두 양이 같은 배로 늘 때 차도 그대로라고 보거나, 배 관계가 변한다고 본다','늘어나도 그대로인 것은 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X05','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'비율을 (기준량) ÷ (비교하는 양)으로 거꾸로 나눈다(9：50의 비율을 50 ÷ 9로)','비교하는 양 ÷ 기준량') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X06','math',6,'u4',ARRAY['M6-1-u4-C3']::text[],'비율은 언제나 1보다 작다고 본다(12：5의 비율 2.4를 틀렸다고)','비교하는 양이 더 크면 비율은 1보다 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X07','math',6,'u4',ARRAY['M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C6']::text[],'전체에 대한 비에서 전체 대신 다른 한 부분을 기준량으로 쓰거나, 한 부분 대신 전체를 쓴다(남 10·여 13에서 전체에 대한 여학생 비를 13：10으로)','전체 = 부분 + 부분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X08','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'비율을 백분율로 바꿀 때 100이 아닌 10·1000을 곱하거나 곱하지 않는다(0.07을 70 %·0.7 %로)','비율 × 100에 % 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X09','math',6,'u4',ARRAY['M6-1-u4-C5','M6-1-u4-C6']::text[],'분수를 백분율로 바꿀 때 분자를 그대로 %로 쓰는 등 기준량을 100으로 맞추지 않는다(⟨16/25⟩를 16 %로)','분모를 100으로 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X10','math',6,'u4',ARRAY['M6-1-u4-C6','M6-1-u4-C7']::text[],'할인율을 구할 때 할인 금액 대신 할인된 가격을 쓴다','할인 금액 = 원래 가격 − 할인된 가격') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X11','math',6,'u4',ARRAY['M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'기준량이 다른데 수·금액·양의 크기만으로 비교한다(넣은 횟수·인구·할인 금액이 크면 더 잘했다·빽빽하다·싸다고)','기준이 다르면 비율로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X12','math',6,'u4',ARRAY['M6-1-u4-C6']::text[],'설탕물의 진하기를 구할 때 기준량을 설탕물 대신 물의 양으로 쓴다','설탕물 = 물 + 설탕') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X13','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'전체의 몇 %를 구할 때 %의 수를 그대로 답하거나, 전체를 %의 수로 나누거나, 한 칸(1 %)만 구하고 멈춘다','한 칸 × 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X14','math',6,'u4',ARRAY['M6-1-u4-C7']::text[],'조건이 바뀌어 기준량이 달라졌는데 처음 전체를 그대로 기준량으로 쓴다(신재생 에너지의 48 %를 전체 발전량의 48 %로)','「무엇의」 몇 %인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X15','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'분수·소수 셈(약분·나눗셈·자릿값)을 잘못 계산한다','곱셈으로 거꾸로 확인해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u4-X16','math',6,'u4',ARRAY['M6-1-u4-C1','M6-1-u4-C2','M6-1-u4-C3','M6-1-u4-C4','M6-1-u4-C5','M6-1-u4-C6','M6-1-u4-C7']::text[],'묻는 말을 놓친다 — 이긴 경기↔진 경기, 할인 금액↔할인된 가격, 쓴 양↔남은 양, 가장 큰↔작은','물음의 「무엇을·가장」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#1','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 뺄셈으로 비교하면 물은 매실 원액보다 몇 컵 더 많은가요? 숫자로 쓰세요.","answer":["3"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","4 − 1 = 3이에요.","물은 매실 원액보다 3컵 더 많아요."],"mis":"M6-1-u4-X16","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 뺄셈으로 비교하면 노란 구슬은 파란 구슬보다 몇 개 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","10 − 2 = 8이에요.","노란 구슬은 파란 구슬보다 8개 더 많아요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 뺄셈으로 비교하면 안개꽃은 장미보다 몇 송이 더 많은가요? 숫자로 쓰세요.","answer":["9"],"explanation":["뺄셈으로 비교하면 두 양의 차를 알 수 있어요.","12 − 3 = 9예요.","안개꽃은 장미보다 9송이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#2','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',1,'sa','auto','팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#3','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'sa','auto','비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]},{"stem":"비 3：4에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：4에서 전항은 3, 후항은 4예요.","그래서 전항은 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#4','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',1,'mc','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."],"variant_rule":{"alt":[{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#5','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":5,"concept":"M6-1-u4-C1","difficulty":2,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"물과 매실 원액을 더한 합","mis":"M6-1-u4-X04"},{"t":"매실 주스 수","mis":"M6-1-u4-X04"}],"explanation":["매실 주스 2병이면 물 8컵, 매실 원액 2컵이에요.","차는 3에서 6으로 변하지만 8 ÷ 2 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"노란 구슬과 파란 구슬을 더한 합","mis":"M6-1-u4-X04"},{"t":"팔찌 수","mis":"M6-1-u4-X04"}],"explanation":["팔찌 2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 8에서 16으로 변하지만 20 ÷ 4 = 5배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 수를 늘려도 변하지 않는 비교는 어느 것인가요?","options":[{"t":"나눗셈으로 비교한 배","correct":true},{"t":"뺄셈으로 비교한 차","mis":"M6-1-u4-X04"},{"t":"흰색 물감과 파란색 물감을 더한 합","mis":"M6-1-u4-X04"},{"t":"하늘색 물감 수","mis":"M6-1-u4-X04"}],"explanation":["하늘색 물감 2접시이면 흰색 물감 16방울, 파란색 물감 4방울이에요.","차는 6에서 12로 변하지만 16 ÷ 4 = 4배는 그대로예요.","그래서 변하지 않는 비교는 나눗셈으로 비교한 배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#6','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들려면 물은 모두 몇 컵 필요한가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 병에 물 4컵씩 들어가요.","2병이면 4 × 2 = 8이에요.","물은 모두 8컵 필요해요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들려면 노란 구슬은 모두 몇 개 필요한가요? 숫자로 쓰세요.","answer":["30"],"explanation":["한 개에 노란 구슬 10개씩 들어가요.","3개이면 10 × 3 = 30이에요.","노란 구슬은 모두 30개 필요해요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 4개를 만들려면 안개꽃은 모두 몇 송이 필요한가요? 숫자로 쓰세요.","answer":["48"],"explanation":["한 개에 안개꽃 12송이씩 들어가요.","4개이면 12 × 4 = 48이에요.","안개꽃은 모두 48송이 필요해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#7','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'ox','auto','비 2：10에서 2는 비교하는 양, 10은 기준량이에요.',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":2,"kind":"ox","stem":"비 2：10에서 2는 비교하는 양, 10은 기준량이에요.","answer":"O","reason_options":[{"t":"기호 ：의 뒤에 있는 수가 기준량이기 때문에","correct":true},{"t":"큰 수가 언제나 기준량이기 때문에","mis":"M6-1-u4-X01"}],"mis":"M6-1-u4-X01","explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."],"variant_rule":{"alt":[{"stem":"「6에 대한 5의 비」는 6：5로 써요.","answer":"X","reason_options":[{"t":"「대한」 쪽 6이 기준량이라 5：6으로 쓰기 때문에","correct":true},{"t":"앞에 나온 수를 먼저 쓰기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]},{"stem":"「5 대 2」와 「2에 대한 5의 비」는 같은 비예요.","answer":"O","reason_options":[{"t":"둘 다 기준량이 2인 5：2이기 때문에","correct":true},{"t":"두 말에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X01"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#8','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'sa','auto','치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C2","difficulty":2,"kind":"sa","stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["「치즈 수에 대한」이니 기준량은 치즈 수예요.","비는 3：4예요.","답은 4예요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"동전을 20번 던져 숫자 면이 9번 나왔어요. 동전을 던진 횟수에 대한 숫자 면이 나온 횟수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["「던진 횟수에 대한」이니 기준량은 던진 횟수예요.","비는 9：20이에요.","답은 20이에요."]},{"stem":"꽃밭에 튤립 8송이와 장미 15송이가 있어요. 장미 수에 대한 튤립 수의 비에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["「장미 수에 대한」이니 기준량은 장미 수 15예요.","비교하는 양은 튤립 수라 비는 8：15예요.","답은 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#9','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C2',2,'mc','auto','3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u4-X02']::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"3：4와 4：3에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["3：4의 기준량은 4이고 4：3의 기준량은 3이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."],"variant_rule":{"alt":[{"stem":"2：5와 5：2에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["2：5의 기준량은 5이고 5：2의 기준량은 2예요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]},{"stem":"7：3과 3：7에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"기준량이 달라 서로 다른 비예요","correct":true},{"t":"같은 비예요","mis":"M6-1-u4-X02"},{"t":"두 수의 합이 같으니 같은 비예요","mis":"M6-1-u4-X02"},{"t":"순서만 다를 뿐 뜻이 같아요","mis":"M6-1-u4-X02"}],"explanation":["7：3의 기준량은 3이고 3：7의 기준량은 7이에요.","기준량이 다르면 다른 비예요.","비의 순서를 바꾸면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_basic#10','math',6,1,'u4','L02','g6_1_math_u4_L02_basic','lesson_basic','M6-1-u4-C1',3,'sa','auto','가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#1','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',2,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C1","difficulty":2,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만들 때 물과 매실 원액의 차는 몇 컵인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","8 − 2 = 6이에요.","한 병일 때의 차 3과 달리 차는 6컵으로 변했어요."],"mis":"M6-1-u4-X04","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만들 때 노란 구슬과 파란 구슬의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","30 − 6 = 24예요.","한 개일 때의 차 8과 달리 차는 24개로 변했어요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 하늘색 물감 4접시를 만들 때 흰색 물감과 파란색 물감의 차는 몇 방울인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["4접시이면 흰색 물감 32방울, 파란색 물감 8방울이에요.","32 − 8 = 24예요.","한 접시일 때의 차 6과 달리 차는 24방울로 변했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#2','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',2,'mc','auto','비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X01']::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":2,"kind":"mc","stem":"비 3：5를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"3에 대한 5의 비","correct":true},{"t":"3 대 5","mis":"M6-1-u4-X16"},{"t":"5에 대한 3의 비","mis":"M6-1-u4-X01"},{"t":"3의 5에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["3：5는 「3 대 5」라고 읽어요.","기준량이 5니 「5에 대한 3의 비」, 「3의 5에 대한 비」라고도 읽어요.","「3에 대한 5의 비」는 기준량이 3인 5：3이에요."],"variant_rule":{"alt":[{"stem":"비 4：7을 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"4에 대한 7의 비","correct":true},{"t":"4 대 7","mis":"M6-1-u4-X16"},{"t":"7에 대한 4의 비","mis":"M6-1-u4-X01"},{"t":"4의 7에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["4：7은 「4 대 7」이라고 읽어요.","기준량이 7이니 「7에 대한 4의 비」, 「4의 7에 대한 비」라고도 읽어요.","「4에 대한 7의 비」는 기준량이 4인 7：4예요."]},{"stem":"비 2：9를 읽은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2에 대한 9의 비","correct":true},{"t":"2 대 9","mis":"M6-1-u4-X16"},{"t":"9에 대한 2의 비","mis":"M6-1-u4-X01"},{"t":"2의 9에 대한 비","mis":"M6-1-u4-X01"}],"explanation":["2：9는 「2 대 9」라고 읽어요.","기준량이 9니 「9에 대한 2의 비」, 「2의 9에 대한 비」라고도 읽어요.","「2에 대한 9의 비」는 기준량이 2인 9：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#3','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'error','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X04','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C1","difficulty":3,"kind":"error","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 2병을 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「2병을 만들어도 물은 매실 원액보다 3컵 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"이현 — 「물은 8컵 필요해.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「물은 언제나 매실 원액의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2병이면 물 8컵, 매실 원액 2컵이에요.","차는 8 − 2 = 6으로 변해요.","준희는 차가 그대로라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 3개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「3개를 만들어도 노란 구슬은 파란 구슬보다 8개 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"수아 — 「노란 구슬은 30개 필요해.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「노란 구슬은 언제나 파란 구슬의 5배야.」","mis":"M6-1-u4-X16"}],"explanation":["3개이면 노란 구슬 30개, 파란 구슬 6개예요.","차는 30 − 6 = 24로 변해요.","서호는 차가 그대로라고 잘못 말했어요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 꽃다발 2개를 만드는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2개를 만들어도 안개꽃은 장미보다 9송이 더 많아.」","correct":true,"mis_target":"M6-1-u4-X04"},{"t":"나린 — 「안개꽃은 24송이 필요해.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「안개꽃은 언제나 장미의 4배야.」","mis":"M6-1-u4-X16"}],"explanation":["2개이면 안개꽃 24송이, 장미 6송이예요.","차는 24 − 6 = 18로 변해요.","가온은 차가 그대로라고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#4','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',3,'ox','auto','주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":4,"concept":"M6-1-u4-C1","difficulty":3,"kind":"ox","stem":"주스를 두 병 만들면 물과 원액의 차는 그대로 3컵이에요.","answer":"X","reason_options":[{"t":"두 병이면 물 8컵, 원액 2컵이라 차는 6컵으로 변하기 때문에","correct":true},{"t":"병 수를 늘려도 차는 변하지 않기 때문에","mis":"M6-1-u4-X04"}],"mis":"M6-1-u4-X04","explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."],"variant_rule":{"alt":[{"stem":"팔찌 3개를 만들면 노란 구슬은 파란 구슬보다 24개 더 많아요.","answer":"O","reason_options":[{"t":"노란 구슬 30개, 파란 구슬 6개라 30 − 6 = 24이기 때문에","correct":true},{"t":"팔찌 수를 늘려도 차는 8개 그대로이기 때문에","mis":"M6-1-u4-X04"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]},{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키워 세로가 6 cm가 되면 가로는 9 cm예요.","answer":"X","reason_options":[{"t":"세로가 3배가 되었으니 가로도 3배인 15 cm이기 때문에","correct":true},{"t":"세로가 4 cm 늘었으니 가로도 4 cm 늘기 때문에","mis":"M6-1-u4-X03"}],"explanation":["두 양은 뺄셈(차)과 나눗셈(배)으로 비교할 수 있어요.","두 양이 같은 배로 늘면 차는 변해요.","그래도 나눗셈으로 비교한 배는 변하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#5','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'mc','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X07','M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C2","difficulty":3,"kind":"mc","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 전체 학생 수에 대한 여학생 수의 비는 어느 것인가요?","options":[{"t":"13：23","correct":true},{"t":"13：10","mis":"M6-1-u4-X07"},{"t":"23：13","mis":"M6-1-u4-X01"},{"t":"10：23","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 전체 학생 수 10 + 13 = 23이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 13：23이에요."],"variant_rule":{"alt":[{"stem":"강아지 9마리 가운데 흰 강아지가 4마리예요. 흰색이 아닌 강아지 수에 대한 흰 강아지 수의 비는 어느 것인가요?","options":[{"t":"4：5","correct":true},{"t":"5：4","mis":"M6-1-u4-X01"},{"t":"4：9","mis":"M6-1-u4-X07"},{"t":"9：4","mis":"M6-1-u4-X07"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 흰색이 아닌 강아지 수 9 − 4 = 5예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 4：5예요."]},{"stem":"주스 8컵 가운데 5컵을 마셨어요. 처음 주스 양에 대한 마신 주스 양의 비는 어느 것인가요?","options":[{"t":"5：8","correct":true},{"t":"8：5","mis":"M6-1-u4-X01"},{"t":"5：3","mis":"M6-1-u4-X07"},{"t":"3：8","mis":"M6-1-u4-X16"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 처음 주스 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#6','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'sa','auto','우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C2","difficulty":3,"kind":"sa","stem":"우리 반 남학생은 10명, 여학생은 13명이에요. 여학생 수의 전체 학생 수에 대한 비에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["후항은 기준량인 전체 학생 수예요.","전체 학생은 10 + 13 = 23(명)이라 비는 13：23이에요.","답은 23이에요."],"mis":"M6-1-u4-X07","variant_rule":{"alt":[{"stem":"바구니에 귤 12개와 사과 5개가 있어요. 전체 과일 수에 대한 귤 수의 비에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["기준량은 전체 과일 수예요.","전체 과일은 12 + 5 = 17(개)라 비는 12：17이에요.","답은 17이에요."]},{"stem":"학생 30명 가운데 안경을 쓴 학생은 7명이에요. 안경을 쓰지 않은 학생 수의 전체 학생 수에 대한 비에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["전항은 비교하는 양인 안경을 쓰지 않은 학생 수예요.","30 − 7 = 23(명)이라 비는 23：30이에요.","답은 23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#7','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',3,'error','auto','사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":7,"concept":"M6-1-u4-C2","difficulty":3,"kind":"error","stem":"사과 7개와 배 3개가 있어요. 배 수의 사과 수에 대한 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「7：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 사과 수야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 3：7이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 사과 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：7이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."],"variant_rule":{"alt":[{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「4：3이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"수아 — 「기준량은 치즈 수야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비는 3：4야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례라 3：4예요.","서호는 기준량과 비교하는 양을 바꾸어 썼어요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「2：5야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"나린 — 「기준량은 닭 수야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「비는 5：2야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례라 5：2예요.","가온은 기준량과 비교하는 양을 바꾸어 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#8','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'mc','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?',ARRAY['M6-1-u4-X04']::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":4,"kind":"mc","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 매실 주스 3병을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 9컵, 배는 4배","correct":true},{"t":"차는 3컵, 배는 4배","mis":"M6-1-u4-X04"},{"t":"차는 9컵, 배는 12배","mis":"M6-1-u4-X04"},{"t":"차는 3컵, 배는 12배","mis":"M6-1-u4-X04"}],"explanation":["3병이면 물 12컵, 매실 원액 3컵이에요.","차는 12 − 3 = 9예요.","배는 12 ÷ 3 = 4로 그대로예요."],"variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 팔찌 2개를 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 16개, 배는 5배","correct":true},{"t":"차는 8개, 배는 5배","mis":"M6-1-u4-X04"},{"t":"차는 16개, 배는 10배","mis":"M6-1-u4-X04"},{"t":"차는 8개, 배는 10배","mis":"M6-1-u4-X04"}],"explanation":["2개이면 노란 구슬 20개, 파란 구슬 4개예요.","차는 20 − 4 = 16이에요.","배는 20 ÷ 4 = 5로 그대로예요."]},{"stem":"모닝빵 반죽 한 판에는 밀가루 6컵과 우유 2컵이 들어가요. 모닝빵 반죽 3판을 만들 때의 차와 배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"차는 12컵, 배는 3배","correct":true},{"t":"차는 4컵, 배는 3배","mis":"M6-1-u4-X04"},{"t":"차는 12컵, 배는 9배","mis":"M6-1-u4-X04"},{"t":"차는 4컵, 배는 9배","mis":"M6-1-u4-X04"}],"explanation":["3판이면 밀가루 18컵, 우유 6컵이에요.","차는 18 − 6 = 12예요.","배는 18 ÷ 6 = 3으로 그대로예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#9','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C2',4,'match','auto','말과 비를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C2","difficulty":4,"kind":"match","stem":"말과 비를 알맞게 이으세요.","pairs":[{"l":"4에 대한 3의 비","r":"3：4"},{"l":"3의 7에 대한 비","r":"3：7"},{"l":"7 대 4","r":"7：4"}],"mis":"M6-1-u4-X01","explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","4에 대한 3의 비 → 3：4, 3의 7에 대한 비 → 3：7, 7 대 4 → 7：4예요.","「대」로 읽을 때는 앞의 수부터 써요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"5 대 2","r":"5：2"},{"l":"5에 대한 2의 비","r":"2：5"},{"l":"5의 9에 대한 비","r":"5：9"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","5 대 2 → 5：2, 5에 대한 2의 비 → 2：5, 5의 9에 대한 비 → 5：9예요.","「대」로 읽을 때는 앞의 수부터 써요."]},{"stem":"이번에는 다른 보기예요. 말과 비를 알맞게 이으세요.","pairs":[{"l":"6의 1에 대한 비","r":"6：1"},{"l":"1 대 6","r":"1：6"},{"l":"7에 대한 6의 비","r":"6：7"}],"explanation":["「○에 대한」 쪽이 기준량이고 ：의 뒤에 써요.","6의 1에 대한 비 → 6：1, 1 대 6 → 1：6, 7에 대한 6의 비 → 6：7이에요.","「대」로 읽을 때는 앞의 수부터 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L02_challenge#10','math',6,1,'u4','L02','g6_1_math_u4_L02_challenge','lesson_challenge','M6-1-u4-C1',4,'essay','teacher','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C1","difficulty":4,"kind":"essay","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 주스를 3병 만들 때 물과 원액을 뺄셈과 나눗셈으로 각각 비교하고, 병 수를 늘려도 변하지 않는 비교를 비로 나타내 보세요.","answer_guide":{"answer":"예: 3병이면 물 12컵, 원액 3컵이 필요하다. 뺄셈으로 비교하면 12 − 3 = 9이므로 물이 9컵 더 많다(한 병일 때의 3컵에서 변했다). 나눗셈으로 비교하면 12 ÷ 3 = 4이므로 물은 원액의 4배이다. 병 수를 늘려도 4배는 변하지 않으므로 원액 양에 대한 물 양의 비는 4：1이다.","scoring_points":["3병일 때 물 12컵·원액 3컵을 구했는가","차 9컵과 4배를 각각 구하고 차는 변하지만 배는 그대로임을 밝혔는가","원액 양에 대한 물 양의 비를 4：1로 나타냈는가"]},"explanation":["3병이면 물 12컵, 원액 3컵이에요.","차는 9컵으로 변하지만 배는 4배 그대로예요.","원액 양에 대한 물 양의 비는 4：1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#1','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 9：50에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：50에서 전항은 9, 후항은 50이에요.","그래서 기준량은 50이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 12：5에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","12：5에서 전항은 12, 후항은 5예요.","그래서 비교하는 양은 12예요."]},{"stem":"비 3：10에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","3：10에서 전항은 3, 후항은 10이에요.","그래서 후항은 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#2','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 3：10의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":2,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."],"variant_rule":{"alt":[{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]},{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#3','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'mc','auto','비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 9：50을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨9/50⟩","correct":true},{"t":"⟨50/9⟩","mis":"M6-1-u4-X05"},{"t":"⟨9/59⟩","mis":"M6-1-u4-X07"},{"t":"⟨41/50⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 9, 기준량은 50이에요.","그래서 비율은 ⟨9/50⟩예요."],"variant_rule":{"alt":[{"stem":"비 3：10을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨3/10⟩","correct":true},{"t":"⟨10/3⟩","mis":"M6-1-u4-X05"},{"t":"⟨3/13⟩","mis":"M6-1-u4-X07"},{"t":"⟨7/10⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 3, 기준량은 10이에요.","그래서 비율은 ⟨3/10⟩이에요."]},{"stem":"비 7：20을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨7/20⟩","correct":true},{"t":"⟨20/7⟩","mis":"M6-1-u4-X05"},{"t":"⟨7/27⟩","mis":"M6-1-u4-X07"},{"t":"⟨13/20⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 7, 기준량은 20이에요.","그래서 비율은 ⟨7/20⟩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#4','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',1,'sa','auto','비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C3","difficulty":1,"kind":"sa","stem":"비 6：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","그래서 □는 2예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"비 3：5의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：5의 비율은 3 ÷ 5 = 0.6이에요.","그래서 □는 6이에요."]},{"stem":"비 7：5의 비율을 소수로 나타내면 1.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：5의 비율은 7 ÷ 5 = 1.4예요.","그래서 □는 4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#5','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','비 12：5의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비 12：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"24","mis":"M6-1-u4-X15"},{"t":"0.24","mis":"M6-1-u4-X15"},{"t":"3.4","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","12：5의 비율은 12 ÷ 5 = 2.4예요.","분수로는 ⟨12/5⟩, 소수로는 2.4예요."],"variant_rule":{"alt":[{"stem":"비 9：50의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"},{"t":"0.82","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9：50의 비율은 9 ÷ 50 = 0.18이에요.","분수로는 ⟨9/50⟩, 소수로는 0.18이에요."]},{"stem":"비 7：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.75","correct":true},{"t":"17.5","mis":"M6-1-u4-X15"},{"t":"0.175","mis":"M6-1-u4-X15"},{"t":"2.75","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：4의 비율은 7 ÷ 4 = 1.75예요.","분수로는 ⟨7/4⟩, 소수로는 1.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#6','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#7','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'ox','auto','비율은 언제나 1보다 작아요.',ARRAY['M6-1-u4-X06']::text[],true,'{"seq":7,"concept":"M6-1-u4-C3","difficulty":2,"kind":"ox","stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"mis":"M6-1-u4-X06","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"15：25와 30：50은 비율이 같아요.","answer":"O","reason_options":[{"t":"15 ÷ 25 = 0.6이고 30 ÷ 50 = 0.6이기 때문에","correct":true},{"t":"두 비 모두 전항이 후항보다 작기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"⟨3/10⟩과 0.3은 같은 비율이에요.","answer":"O","reason_options":[{"t":"⟨3/10⟩ = 0.3이기 때문에","correct":true},{"t":"두 수에 모두 3이 들어 있기 때문에","mis":"M6-1-u4-X15"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#8','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'mc','auto','비율이 1보다 큰 비는 어느 것인가요?',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":8,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"12：5","correct":true},{"t":"3：5","mis":"M6-1-u4-X01"},{"t":"9：50","mis":"M6-1-u4-X01"},{"t":"4：7","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","3：5 → 0.6, 12：5 → 2.4, 9：50 → 0.18, 4：7 → ⟨4/7⟩예요.","1보다 큰 것은 12：5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"7：4","correct":true},{"t":"2：9","mis":"M6-1-u4-X01"},{"t":"5：8","mis":"M6-1-u4-X01"},{"t":"1：3","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","7：4 → 1.75, 2：9 → ⟨2/9⟩, 5：8 → 0.625, 1：3 → ⟨1/3⟩이에요.","1보다 큰 것은 7：4예요."]},{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"11：6","correct":true},{"t":"9：10","mis":"M6-1-u4-X01"},{"t":"3：8","mis":"M6-1-u4-X01"},{"t":"6：11","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","9：10 → 0.9, 3：8 → 0.375, 11：6 → ⟨11/6⟩, 6：11 → ⟨6/11⟩이에요.","1보다 큰 것은 11：6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#9','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',2,'match','auto','비와 비율을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"match","stem":"비와 비율을 알맞게 이으세요.","pairs":[{"l":"3：10","r":"0.3"},{"l":"12：5","r":"2.4"},{"l":"9：50","r":"0.18"}],"mis":"M6-1-u4-X05","explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 10 = 0.3, 12 ÷ 5 = 2.4, 9 ÷ 50 = 0.18이에요.","：의 뒤에 있는 수로 나누어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비와 비율을 알맞게 이으세요.","pairs":[{"l":"1：4","r":"0.25"},{"l":"6：5","r":"1.2"},{"l":"7：20","r":"0.35"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1 ÷ 4 = 0.25, 6 ÷ 5 = 1.2, 7 ÷ 20 = 0.35예요.","：의 뒤에 있는 수로 나누어요."]},{"stem":"이번에는 다른 보기예요. 비와 비율을 알맞게 이으세요.","pairs":[{"l":"3：5","r":"0.6"},{"l":"7：4","r":"1.75"},{"l":"9：10","r":"0.9"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 5 = 0.6, 7 ÷ 4 = 1.75, 9 ÷ 10 = 0.9예요.","：의 뒤에 있는 수로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_basic#10','math',6,1,'u4','L03','g6_1_math_u4_L03_basic','lesson_basic','M6-1-u4-C3',3,'mc','auto','가 직사각형은 가로 10 cm, 세로 6 cm이고 나 직사각형은 가로 15 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X11']::text[],true,'{"seq":10,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"가 직사각형은 가로 10 cm, 세로 6 cm이고 나 직사각형은 가로 15 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"두 비율은 같아요","correct":true},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 6 ÷ 10 = 0.6이에요.","나는 9 ÷ 15 = 0.6이에요.","그래서 두 비율은 같아요."],"variant_rule":{"alt":[{"stem":"가 직사각형은 가로 8 cm, 세로 6 cm이고 나 직사각형은 가로 10 cm, 세로 7 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"가의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 6 ÷ 8 = 0.75예요.","나는 7 ÷ 10 = 0.7이에요.","그래서 가의 비율이 더 커요."]},{"stem":"가 직사각형은 가로 20 cm, 세로 12 cm이고 나 직사각형은 가로 25 cm, 세로 16 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"나의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 12 ÷ 20 = 0.6이에요.","나는 16 ÷ 25 = 0.64예요.","그래서 나의 비율이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#1','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',2,'sa','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C3","difficulty":2,"kind":"sa","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","□는 4예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"버스 정원 45명 가운데 36명이 탔어요. 정원에 대한 탄 사람 수의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["기준량은 45, 비교하는 양은 36이에요.","36 ÷ 45 = 0.8이에요.","□는 8이에요."]},{"stem":"높이 150 cm인 나무의 그림자 길이가 90 cm예요. 나무 높이에 대한 그림자 길이의 비율을 소수로 나타내면 0.□예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["기준량은 150, 비교하는 양은 90이에요.","90 ÷ 150 = 0.6이에요.","□는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#2','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',2,'mc','auto','비 21：25의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":2,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"비 21：25의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.84","correct":true},{"t":"8.4","mis":"M6-1-u4-X15"},{"t":"0.084","mis":"M6-1-u4-X15"},{"t":"0.16","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","21：25의 비율은 21 ÷ 25 = 0.84예요.","분수로는 ⟨21/25⟩, 소수로는 0.84예요."],"variant_rule":{"alt":[{"stem":"비 7：8의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.875","correct":true},{"t":"8.75","mis":"M6-1-u4-X15"},{"t":"0.0875","mis":"M6-1-u4-X15"},{"t":"0.125","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：8의 비율은 7 ÷ 8 = 0.875예요.","분수로는 ⟨7/8⟩, 소수로는 0.875예요."]},{"stem":"비 9：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"2.25","correct":true},{"t":"22.5","mis":"M6-1-u4-X15"},{"t":"0.225","mis":"M6-1-u4-X15"},{"t":"3.25","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9：4의 비율은 9 ÷ 4 = 2.25예요.","분수로는 ⟨9/4⟩, 소수로는 2.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#3','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'error','auto','비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":3,"kind":"error","stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"이현 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","준희는 기준량을 비교하는 양으로 나누었어요."],"variant_rule":{"alt":[{"stem":"비 3：4의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「4 ÷ 3 = ⟨4/3⟩야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 4야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.75야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3 ÷ 4 = 0.75예요.","서호는 기준량을 비교하는 양으로 나누었어요."]},{"stem":"비 12：5의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「5 ÷ 12 = ⟨5/12⟩야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"나린 — 「기준량은 5야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「비율은 2.4야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","12 ÷ 5 = 2.4예요.","가온은 기준량을 비교하는 양으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#4','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'ox','auto','비 9：50의 비율은 50 ÷ 9로 구해요.',ARRAY['M6-1-u4-X05']::text[],true,'{"seq":4,"concept":"M6-1-u4-C3","difficulty":3,"kind":"ox","stem":"비 9：50의 비율은 50 ÷ 9로 구해요.","answer":"X","reason_options":[{"t":"비율은 비교하는 양을 기준량으로 나누어 9 ÷ 50으로 구하기 때문에","correct":true},{"t":"큰 수를 작은 수로 나누어야 하기 때문에","mis":"M6-1-u4-X05"}],"mis":"M6-1-u4-X05","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비 12：5의 비율은 2.4예요.","answer":"O","reason_options":[{"t":"12 ÷ 5 = 2.4이기 때문에","correct":true},{"t":"비율은 큰 수를 작은 수로 나눈 것이기 때문에","mis":"M6-1-u4-X05"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"기준량이 다르면 비율은 언제나 달라요.","answer":"X","reason_options":[{"t":"6：10과 30：50처럼 기준량이 달라도 비율이 같을 수 있기 때문에","correct":true},{"t":"기준량이 다르면 관계도 달라지기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#5','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','비율이 15：25와 같은 비는 어느 것인가요?',ARRAY['M6-1-u4-X02','M6-1-u4-X04','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"비율이 15：25와 같은 비는 어느 것인가요?","options":[{"t":"6：10","correct":true},{"t":"25：15","mis":"M6-1-u4-X02"},{"t":"20：30","mis":"M6-1-u4-X04"},{"t":"5：15","mis":"M6-1-u4-X15"}],"explanation":["15：25의 비율은 15 ÷ 25 = 0.6이에요.","6：10의 비율도 6 ÷ 10 = 0.6이에요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비율이 3：4와 같은 비는 어느 것인가요?","options":[{"t":"12：16","correct":true},{"t":"4：3","mis":"M6-1-u4-X02"},{"t":"5：6","mis":"M6-1-u4-X04"},{"t":"6：12","mis":"M6-1-u4-X15"}],"explanation":["3：4의 비율은 3 ÷ 4 = 0.75예요.","12：16의 비율도 12 ÷ 16 = 0.75예요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"비율이 2：5와 같은 비는 어느 것인가요?","options":[{"t":"8：20","correct":true},{"t":"5：2","mis":"M6-1-u4-X02"},{"t":"4：7","mis":"M6-1-u4-X04"},{"t":"8：10","mis":"M6-1-u4-X15"}],"explanation":["2：5의 비율은 2 ÷ 5 = 0.4예요.","8：20의 비율도 8 ÷ 20 = 0.4예요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#6','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."],"variant_rule":{"alt":[{"stem":"높이 150 cm인 나무의 그림자 길이가 90 cm예요. 나무 높이에 대한 그림자 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 150, 비교하는 양은 90이에요.","90 ÷ 150 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"버스 정원 45명 가운데 36명이 탔어요. 정원에 대한 탄 사람 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 45, 비교하는 양은 36이에요.","36 ÷ 45 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#7','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',3,'mc','auto','가 직사각형은 가로 16 cm, 세로 12 cm이고 나 직사각형은 가로 20 cm, 세로 15 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X11']::text[],true,'{"seq":7,"concept":"M6-1-u4-C3","difficulty":3,"kind":"mc","stem":"가 직사각형은 가로 16 cm, 세로 12 cm이고 나 직사각형은 가로 20 cm, 세로 15 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"두 비율은 같아요","correct":true},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 12 ÷ 16 = 0.75예요.","나는 15 ÷ 20 = 0.75예요.","그래서 두 비율은 같아요."],"variant_rule":{"alt":[{"stem":"가 직사각형은 가로 5 cm, 세로 4 cm이고 나 직사각형은 가로 10 cm, 세로 7 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"가의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"나의 비율이 더 커요","mis":"M6-1-u4-X11"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 4 ÷ 5 = 0.8이에요.","나는 7 ÷ 10 = 0.7이에요.","그래서 가의 비율이 더 커요."]},{"stem":"가 직사각형은 가로 25 cm, 세로 10 cm이고 나 직사각형은 가로 20 cm, 세로 9 cm예요. 가로에 대한 세로의 비율을 비교하면 어떤가요?","options":[{"t":"나의 비율이 더 커요","correct":true},{"t":"두 비율은 같아요","mis":"M6-1-u4-X11"},{"t":"가의 비율이 더 커요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["가는 10 ÷ 25 = 0.4예요.","나는 9 ÷ 20 = 0.45예요.","그래서 나의 비율이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#8','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'mc','auto','비율이 1보다 큰 비는 어느 것인가요?',ARRAY['M6-1-u4-X01']::text[],true,'{"seq":8,"concept":"M6-1-u4-C3","difficulty":4,"kind":"mc","stem":"비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"9：8","correct":true},{"t":"15：25","mis":"M6-1-u4-X01"},{"t":"49：50","mis":"M6-1-u4-X01"},{"t":"30：50","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","15：25 → 0.6, 9：8 → 1.125, 49：50 → 0.98, 30：50 → 0.6이에요.","1보다 큰 것은 9：8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"13：12","correct":true},{"t":"99：100","mis":"M6-1-u4-X01"},{"t":"21：25","mis":"M6-1-u4-X01"},{"t":"40：45","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","99：100 → 0.99, 21：25 → 0.84, 13：12 → ⟨13/12⟩, 40：45 → ⟨8/9⟩이에요.","1보다 큰 것은 13：12예요."]},{"stem":"이번에는 다른 보기예요. 비율이 1보다 큰 비는 어느 것인가요?","options":[{"t":"25：24","correct":true},{"t":"7：21","mis":"M6-1-u4-X01"},{"t":"24：25","mis":"M6-1-u4-X01"},{"t":"1：2","mis":"M6-1-u4-X01"}],"explanation":["비교하는 양이 기준량보다 크면 비율은 1보다 커요.","7：21 → ⟨1/3⟩, 25：24 → ⟨25/24⟩, 24：25 → 0.96, 1：2 → 0.5예요.","1보다 큰 것은 25：24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#9','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'mc','auto','비 36：45를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X16']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":4,"kind":"mc","stem":"비 36：45를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨36/45⟩","correct":true},{"t":"⟨45/36⟩","mis":"M6-1-u4-X05"},{"t":"⟨36/81⟩","mis":"M6-1-u4-X07"},{"t":"⟨9/45⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 36, 기준량은 45예요.","그래서 비율은 ⟨36/45⟩이에요."],"variant_rule":{"alt":[{"stem":"비 21：28을 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨21/28⟩","correct":true},{"t":"⟨28/21⟩","mis":"M6-1-u4-X05"},{"t":"⟨21/49⟩","mis":"M6-1-u4-X07"},{"t":"⟨7/28⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 21, 기준량은 28이에요.","그래서 비율은 ⟨21/28⟩이에요."]},{"stem":"비 14：35를 비율로 나타낸 분수로 알맞은 것은 어느 것인가요?","options":[{"t":"⟨14/35⟩","correct":true},{"t":"⟨35/14⟩","mis":"M6-1-u4-X05"},{"t":"⟨14/49⟩","mis":"M6-1-u4-X07"},{"t":"⟨21/35⟩","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","비교하는 양은 14, 기준량은 35예요.","그래서 비율은 ⟨14/35⟩예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L03_challenge#10','math',6,1,'u4','L03','g6_1_math_u4_L03_challenge','lesson_challenge','M6-1-u4-C3',4,'essay','teacher','가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C3","difficulty":4,"kind":"essay","stem":"가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 15 ÷ 25 = 0.6, 30 ÷ 50 = 0.6, 6 ÷ 10 = 0.6이므로 세 비율은 모두 0.6으로 같다. 세 직사각형은 크기는 다르지만 가로에 대한 세로의 관계(세로가 가로의 0.6배)가 같아서, 기준량이 달라도 비율이 같다.","scoring_points":["세 비율을 0.6으로 구했는가","세 비율이 같다고 비교했는가","관계가 같으면 기준량이 달라도 비율이 같다고 설명했는가"]},"explanation":["세 비율은 모두 0.6이에요.","크기는 달라도 모양(관계)이 같아요.","그래서 기준량이 달라도 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#1','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'mc','auto','넓이에 대한 인구의 비율에서 기준량은 무엇인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"넓이에 대한 인구의 비율에서 기준량은 무엇인가요?","options":[{"t":"넓이","correct":true},{"t":"인구","mis":"M6-1-u4-X01"},{"t":"넓이와 인구의 합","mis":"M6-1-u4-X07"},{"t":"인구와 넓이의 차","mis":"M6-1-u4-X03"}],"explanation":["「넓이에 대한」이니 기준량은 넓이예요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."],"variant_rule":{"alt":[{"stem":"이동한 시간에 대한 이동한 거리의 비율에서 기준량은 무엇인가요?","options":[{"t":"이동한 시간","correct":true},{"t":"이동한 거리","mis":"M6-1-u4-X01"},{"t":"시간과 거리의 합","mis":"M6-1-u4-X07"},{"t":"거리와 시간의 차","mis":"M6-1-u4-X03"}],"explanation":["「이동한 시간에 대한」이니 기준량은 이동한 시간이에요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."]},{"stem":"전체 경기 수에 대한 이긴 경기 수의 비율에서 비교하는 양은 무엇인가요?","options":[{"t":"이긴 경기 수","correct":true},{"t":"전체 경기 수","mis":"M6-1-u4-X01"},{"t":"진 경기 수","mis":"M6-1-u4-X16"},{"t":"전체 경기 수와 이긴 경기 수의 차","mis":"M6-1-u4-X03"}],"explanation":["「전체 경기 수에 대한」 쪽이 기준량이고 다른 쪽 이긴 경기 수가 비교하는 양이에요.","비율은 (비교하는 양) ÷ (기준량)으로 구해요.","기준량을 바꾸면 전혀 다른 비율이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#2','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'mc','auto','푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":2,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]},{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#3','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'sa','auto','자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C4","difficulty":1,"kind":"sa","stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]},{"stem":"산책로를 2시간 동안 8 km 걸었어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 8이에요.","8 ÷ 2 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#4','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',1,'ox','auto','2시간 동안 160 km를 갔다면 이동한 시간에 대한 이동한 거리의 비율은 80이에요.',ARRAY['M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"ox","stem":"2시간 동안 160 km를 갔다면 이동한 시간에 대한 이동한 거리의 비율은 80이에요.","answer":"O","reason_options":[{"t":"160 ÷ 2 = 80이기 때문에","correct":true},{"t":"160과 2를 비교하면 차가 80쯤이기 때문에","mis":"M6-1-u4-X03"}],"mis":"M6-1-u4-X03","explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."],"variant_rule":{"alt":[{"stem":"넓이에 대한 인구의 비율이 클수록 사람이 빽빽하게 살아요.","answer":"O","reason_options":[{"t":"1 km²에 사는 사람이 더 많다는 뜻이기 때문에","correct":true},{"t":"넓이가 넓을수록 비율이 크기 때문에","mis":"M6-1-u4-X05"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]},{"stem":"지도에서 1 cm가 실제 300 m이면 지도의 2 cm는 실제 600 m예요.","answer":"O","reason_options":[{"t":"300 × 2 = 600이기 때문에","correct":true},{"t":"300에 2를 더하기 때문에","mis":"M6-1-u4-X03"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#5','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','가 마을은 넓이 2 km²에 6000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"3000","correct":true},{"t":"⟨2/6000⟩","mis":"M6-1-u4-X05"},{"t":"12000","mis":"M6-1-u4-X15"},{"t":"30000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 2, 비교하는 양은 인구 6000이에요.","6000 ÷ 2 = 3000이에요.","1 km²에 3000명꼴로 사는 셈이에요."],"variant_rule":{"alt":[{"stem":"나 마을은 넓이 3 km²에 7500명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"⟨3/7500⟩","mis":"M6-1-u4-X05"},{"t":"22500","mis":"M6-1-u4-X15"},{"t":"25000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 3, 비교하는 양은 인구 7500이에요.","7500 ÷ 3 = 2500이에요.","1 km²에 2500명꼴로 사는 셈이에요."]},{"stem":"다 마을은 넓이 4 km²에 10000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2500","correct":true},{"t":"⟨4/10000⟩","mis":"M6-1-u4-X05"},{"t":"40000","mis":"M6-1-u4-X15"},{"t":"25000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 4, 비교하는 양은 인구 10000이에요.","10000 ÷ 4 = 2500이에요.","1 km²에 2500명꼴로 사는 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#6','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','푸른 팀은 15경기 중 6경기를, 초록 팀은 10경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"푸른 팀은 15경기 중 6경기를, 초록 팀은 10경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"초록 팀","correct":true},{"t":"푸른 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","푸른 팀 6 ÷ 15 = 0.4, 초록 팀 5 ÷ 10 = 0.5예요.","비율이 더 큰 팀은 초록 팀이에요."],"variant_rule":{"alt":[{"stem":"하늘 팀은 20경기 중 12경기를, 바다 팀은 8경기 중 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"바다 팀","correct":true},{"t":"하늘 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","하늘 팀 12 ÷ 20 = 0.6, 바다 팀 5 ÷ 8 = 0.625예요.","비율이 더 큰 팀은 바다 팀이에요."]},{"stem":"빨강 팀은 40경기 중 26경기를, 주황 팀은 20경기 중 14경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"주황 팀","correct":true},{"t":"빨강 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","빨강 팀 26 ÷ 40 = 0.65, 주황 팀 14 ÷ 20 = 0.7이에요.","비율이 더 큰 팀은 주황 팀이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#7','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'sa','auto','어떤 지도에서 1 cm는 실제 거리 25 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"어떤 지도에서 1 cm는 실제 거리 25 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["지도 거리에 대한 실제 거리의 비율은 25예요.","3 cm이면 25 × 3 = 75예요.","실제 거리는 75 m예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 20 m를 나타내요. 지도에서 4 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["지도 거리에 대한 실제 거리의 비율은 20이에요.","4 cm이면 20 × 4 = 80이에요.","실제 거리는 80 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 15 m를 나타내요. 지도에서 6 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["지도 거리에 대한 실제 거리의 비율은 15예요.","6 cm이면 15 × 6 = 90이에요.","실제 거리는 90 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#8','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'mc','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#9','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',2,'ox','auto','인구가 더 많은 마을이 언제나 더 빽빽해요.',ARRAY['M6-1-u4-X11']::text[],true,'{"seq":9,"concept":"M6-1-u4-C4","difficulty":2,"kind":"ox","stem":"인구가 더 많은 마을이 언제나 더 빽빽해요.","answer":"X","reason_options":[{"t":"넓이가 다르면 넓이에 대한 인구의 비율로 비교해야 하기 때문에","correct":true},{"t":"사람이 많으면 땅이 좁아 보이기 때문에","mis":"M6-1-u4-X11"}],"mis":"M6-1-u4-X11","explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."],"variant_rule":{"alt":[{"stem":"이긴 경기 수가 많은 팀이 언제나 이긴 경기의 비율도 높아요.","answer":"X","reason_options":[{"t":"치른 경기 수가 다르면 비율이 달라지기 때문에","correct":true},{"t":"이긴 경기 수가 곧 비율이기 때문에","mis":"M6-1-u4-X11"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]},{"stem":"이동한 시간에 대한 이동한 거리의 비율은 (이동한 시간) ÷ (이동한 거리)로 구해요.","answer":"X","reason_options":[{"t":"기준량인 시간으로 거리를 나누어야 하기 때문에","correct":true},{"t":"앞에 나온 양을 먼저 쓰기 때문에","mis":"M6-1-u4-X05"}],"explanation":["비율은 경기 결과·빠르기·인구·지도처럼 생활 곳곳에 쓰여요.","먼저 「○에 대한」으로 기준량을 찾아요.","기준이 다른 것끼리는 수가 아니라 비율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_basic#10','math',6,1,'u4','L04','g6_1_math_u4_L04_basic','lesson_basic','M6-1-u4-C4',3,'mc','auto','가 자동차는 3시간 동안 240 km, 나 자동차는 2시간 동안 170 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 자동차는 3시간 동안 240 km, 나 자동차는 2시간 동안 170 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"나 자동차","correct":true},{"t":"가 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","가 240 ÷ 3 = 80, 나 170 ÷ 2 = 85예요.","1시간에 더 멀리 가는 것은 나 자동차예요."],"variant_rule":{"alt":[{"stem":"다 자동차는 4시간 동안 200 km, 라 자동차는 3시간 동안 180 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"라 자동차","correct":true},{"t":"다 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","다 200 ÷ 4 = 50, 라 180 ÷ 3 = 60이에요.","1시간에 더 멀리 가는 것은 라 자동차예요."]},{"stem":"마 자동차는 5시간 동안 300 km, 바 자동차는 2시간 동안 130 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"바 자동차","correct":true},{"t":"마 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","마 300 ÷ 5 = 60, 바 130 ÷ 2 = 65예요.","1시간에 더 멀리 가는 것은 바 자동차예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#1','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',2,'sa','auto','기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]},{"stem":"자전거로 5시간 동안 60 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["기준량은 이동한 시간 5, 비교하는 양은 이동한 거리 60이에요.","60 ÷ 5 = 12예요.","1시간에 12 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#2','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',2,'mc','auto','어떤 지도에서 1 cm는 실제 거리 300 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요?',ARRAY['M6-1-u4-X03','M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":2,"concept":"M6-1-u4-C4","difficulty":2,"kind":"mc","stem":"어떤 지도에서 1 cm는 실제 거리 300 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"900 m","correct":true},{"t":"303 m","mis":"M6-1-u4-X03"},{"t":"100 m","mis":"M6-1-u4-X05"},{"t":"9000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 300 m니 몇 cm인지만큼 곱해요.","300 × 3 = 900이에요.","실제 거리는 900 m예요."],"variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 250 m를 나타내요. 지도에서 4 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"1000 m","correct":true},{"t":"254 m","mis":"M6-1-u4-X03"},{"t":"62.5 m","mis":"M6-1-u4-X05"},{"t":"10000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 250 m니 몇 cm인지만큼 곱해요.","250 × 4 = 1000이에요.","실제 거리는 1000 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 150 m를 나타내요. 지도에서 6 cm인 두 곳 사이의 실제 거리는 몇 m인가요?","options":[{"t":"900 m","correct":true},{"t":"156 m","mis":"M6-1-u4-X03"},{"t":"25 m","mis":"M6-1-u4-X05"},{"t":"9000 m","mis":"M6-1-u4-X15"}],"explanation":["1 cm가 150 m니 몇 cm인지만큼 곱해요.","150 × 6 = 900이에요.","실제 거리는 900 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#3','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'error','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C4","difficulty":3,"kind":"error","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「사람이 더 많은 나 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"이현 — 「가 마을의 넓이에 대한 인구의 비율은 3000이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「가 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","가 3000, 나 2500이에요.","준희는 인구 수만 보고 비교했어요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「사람이 더 많은 라 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"수아 — 「다 마을의 넓이에 대한 인구의 비율은 2500이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「다 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","다 2500, 라 2200이에요.","서호는 인구 수만 보고 비교했어요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「사람이 더 많은 마 마을이 더 빽빽해.」","correct":true,"mis_target":"M6-1-u4-X11"},{"t":"나린 — 「바 마을의 넓이에 대한 인구의 비율은 1800이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「바 마을이 더 빽빽해.」","mis":"M6-1-u4-X16"}],"explanation":["넓이가 다르니 비율로 비교해요.","바 1800, 마 1500이에요.","가온은 인구 수만 보고 비교했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#4','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','하늘 팀은 25경기를 치러서 16경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"하늘 팀은 25경기를 치러서 16경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.64","correct":true},{"t":"1.5625","mis":"M6-1-u4-X05"},{"t":"0.36","mis":"M6-1-u4-X16"},{"t":"6.4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 25, 비교하는 양은 이긴 경기 수 16이에요.","⟨16/25⟩ = 0.64예요.","하늘 팀의 비율은 0.64예요."],"variant_rule":{"alt":[{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]},{"stem":"주황 팀은 40경기를 치러서 14경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"0.65","mis":"M6-1-u4-X16"},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 40, 비교하는 양은 이긴 경기 수 14예요.","⟨14/40⟩ = 0.35예요.","주황 팀의 비율은 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#5','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','노란 팀은 20경기 중 6경기를, 파란 팀은 10경기 중 4경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"노란 팀은 20경기 중 6경기를, 파란 팀은 10경기 중 4경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"파란 팀","correct":true},{"t":"노란 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","노란 팀 6 ÷ 20 = 0.3, 파란 팀 4 ÷ 10 = 0.4예요.","비율이 더 큰 팀은 파란 팀이에요."],"variant_rule":{"alt":[{"stem":"보라 팀은 50경기 중 28경기를, 초록 팀은 25경기 중 15경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"초록 팀","correct":true},{"t":"보라 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","보라 팀 28 ÷ 50 = 0.56, 초록 팀 15 ÷ 25 = 0.6이에요.","비율이 더 큰 팀은 초록 팀이에요."]},{"stem":"하얀 팀은 16경기 중 12경기를, 까만 팀은 30경기 중 21경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율이 더 큰 팀은 어느 팀인가요?","options":[{"t":"하얀 팀","correct":true},{"t":"까만 팀","mis":"M6-1-u4-X11"},{"t":"두 팀이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["치른 경기 수가 다르니 이긴 경기 수가 아니라 비율로 비교해요.","하얀 팀 12 ÷ 16 = 0.75, 까만 팀 21 ÷ 30 = 0.7이에요.","비율이 더 큰 팀은 하얀 팀이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#6','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','라 마을은 넓이 5 km²에 11000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"라 마을은 넓이 5 km²에 11000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"2200","correct":true},{"t":"⟨5/11000⟩","mis":"M6-1-u4-X05"},{"t":"55000","mis":"M6-1-u4-X15"},{"t":"22000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 5, 비교하는 양은 인구 11000이에요.","11000 ÷ 5 = 2200이에요.","1 km²에 2200명꼴로 사는 셈이에요."],"variant_rule":{"alt":[{"stem":"마 마을은 넓이 6 km²에 9000명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"1500","correct":true},{"t":"⟨6/9000⟩","mis":"M6-1-u4-X05"},{"t":"54000","mis":"M6-1-u4-X15"},{"t":"15000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 6, 비교하는 양은 인구 9000이에요.","9000 ÷ 6 = 1500이에요.","1 km²에 1500명꼴로 사는 셈이에요."]},{"stem":"바 마을은 넓이 4 km²에 7200명이 살아요. 넓이에 대한 인구의 비율은 얼마인가요?","options":[{"t":"1800","correct":true},{"t":"⟨4/7200⟩","mis":"M6-1-u4-X05"},{"t":"28800","mis":"M6-1-u4-X15"},{"t":"18000","mis":"M6-1-u4-X15"}],"explanation":["기준량은 넓이 4, 비교하는 양은 인구 7200이에요.","7200 ÷ 4 = 1800이에요.","1 km²에 1800명꼴로 사는 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#7','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',3,'mc','auto','가 자동차는 4시간 동안 320 km, 나 자동차는 3시간 동안 255 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":7,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 자동차는 4시간 동안 320 km, 나 자동차는 3시간 동안 255 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"나 자동차","correct":true},{"t":"가 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","가 320 ÷ 4 = 80, 나 255 ÷ 3 = 85예요.","1시간에 더 멀리 가는 것은 나 자동차예요."],"variant_rule":{"alt":[{"stem":"다 자동차는 2시간 동안 150 km, 라 자동차는 5시간 동안 350 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"다 자동차","correct":true},{"t":"라 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","다 150 ÷ 2 = 75, 라 350 ÷ 5 = 70이에요.","1시간에 더 멀리 가는 것은 다 자동차예요."]},{"stem":"마 자동차는 6시간 동안 420 km, 바 자동차는 4시간 동안 300 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율로 비교할 때 더 빠른 자동차는 어느 것인가요?","options":[{"t":"바 자동차","correct":true},{"t":"마 자동차","mis":"M6-1-u4-X11"},{"t":"두 자동차가 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["걸린 시간이 다르니 간 거리가 아니라 비율로 비교해요.","마 420 ÷ 6 = 70, 바 300 ÷ 4 = 75예요.","1시간에 더 멀리 가는 것은 바 자동차예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#8','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'mc','auto','사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C4","difficulty":4,"kind":"mc","stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"자 마을은 넓이 12 km²에 30000명, 차 마을은 넓이 10 km²에 26000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"차 마을","correct":true},{"t":"자 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","자 30000 ÷ 12 = 2500, 차 26000 ÷ 10 = 2600이에요.","비율이 큰 차 마을이 더 빽빽해요."]},{"stem":"카 마을은 넓이 7 km²에 14000명, 타 마을은 넓이 9 km²에 16200명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"카 마을","correct":true},{"t":"타 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","카 14000 ÷ 7 = 2000, 타 16200 ÷ 9 = 1800이에요.","비율이 큰 카 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#9','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'sa','auto','어떤 지도에서 1 cm는 실제 거리 12 m를 나타내요. 지도에서 8 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C4","difficulty":4,"kind":"sa","stem":"어떤 지도에서 1 cm는 실제 거리 12 m를 나타내요. 지도에서 8 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["지도 거리에 대한 실제 거리의 비율은 12예요.","8 cm이면 12 × 8 = 96이에요.","실제 거리는 96 m예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"어떤 지도에서 1 cm는 실제 거리 30 m를 나타내요. 지도에서 3 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["지도 거리에 대한 실제 거리의 비율은 30이에요.","3 cm이면 30 × 3 = 90이에요.","실제 거리는 90 m예요."]},{"stem":"어떤 지도에서 1 cm는 실제 거리 16 m를 나타내요. 지도에서 5 cm인 두 곳 사이의 실제 거리는 몇 m인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["지도 거리에 대한 실제 거리의 비율은 16이에요.","5 cm이면 16 × 5 = 80이에요.","실제 거리는 80 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L04_challenge#10','math',6,1,'u4','L04','g6_1_math_u4_L04_challenge','lesson_challenge','M6-1-u4-C4',4,'essay','teacher','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":4,"kind":"essay","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 마을은 6000 ÷ 2 = 3000, 나 마을은 7500 ÷ 3 = 2500이다. 1 km²에 사는 사람이 가 마을이 더 많으므로 가 마을이 더 빽빽하다. 넓이가 다르면 인구 수가 아니라 넓이에 대한 인구의 비율로 비교해야 한다.","scoring_points":["3000과 2500을 구했는가","가 마을이 더 빽빽하다고 답했는가","기준(넓이)이 다르면 비율로 비교해야 한다고 썼는가"]},"explanation":["가 3000, 나 2500이에요.","가 마을이 더 빽빽해요.","넓이가 다르면 비율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#1','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'mc','auto','비율 0.35를 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":1,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]},{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#2','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'ox','auto','비율 0.35는 35 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":2,"concept":"M6-1-u4-C5","difficulty":1,"kind":"ox","stem":"비율 0.35는 35 %예요.","answer":"O","reason_options":[{"t":"0.35 × 100 = 35이기 때문에","correct":true},{"t":"소수점 뒤의 수가 35이기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"백분율은 기준량을 100으로 할 때의 비율이에요.","answer":"O","reason_options":[{"t":"기준을 100으로 통일하면 분자만 견주면 되기 때문에","correct":true},{"t":"100은 언제나 비교하는 양이기 때문에","mis":"M6-1-u4-X01"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"100 %는 비율 1과 같아요.","answer":"O","reason_options":[{"t":"1 × 100 = 100이기 때문에","correct":true},{"t":"100은 1보다 크기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#3','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'mc','auto','45 %를 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":3,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"45 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.45","correct":true},{"t":"4.5","mis":"M6-1-u4-X08"},{"t":"0.045","mis":"M6-1-u4-X08"},{"t":"45","mis":"M6-1-u4-X08"}],"explanation":["45 %는 기준량이 100일 때 45라는 뜻이에요.","⟨45/100⟩ = 0.45예요.","그래서 소수로 0.45예요."],"variant_rule":{"alt":[{"stem":"8 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.08","correct":true},{"t":"0.8","mis":"M6-1-u4-X08"},{"t":"0.008","mis":"M6-1-u4-X08"},{"t":"8","mis":"M6-1-u4-X08"}],"explanation":["8 %는 기준량이 100일 때 8라는 뜻이에요.","⟨8/100⟩ = 0.08이에요.","그래서 소수로 0.08이에요."]},{"stem":"60 %를 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"6","mis":"M6-1-u4-X08"},{"t":"0.06","mis":"M6-1-u4-X08"},{"t":"60","mis":"M6-1-u4-X08"}],"explanation":["60 %는 기준량이 100일 때 60라는 뜻이에요.","⟨60/100⟩ = 0.6이에요.","그래서 소수로 0.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#4','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',1,'sa','auto','비율 0.83을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C5","difficulty":1,"kind":"sa","stem":"비율 0.83을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["비율에 100을 곱해요.","0.83 × 100 = 83이에요.","0.83은 백분율로 83 %예요."],"mis":"M6-1-u4-X08","variant_rule":{"alt":[{"stem":"비율 0.47을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["47"],"explanation":["비율에 100을 곱해요.","0.47 × 100 = 47이에요.","0.47은 백분율로 47 %예요."]},{"stem":"비율 0.9를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["비율에 100을 곱해요.","0.9 × 100 = 90이에요.","0.9는 백분율로 90 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#5','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'sa','auto','우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]},{"stem":"투호 놀이에서 화살 10개를 던져 7개를 넣었어요. 던진 화살 수에 대한 넣은 화살 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["기준량은 10, 비교하는 양은 7이에요.","7 ÷ 10 × 100 = 70이에요.","그래서 70 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#6','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'sa','auto','비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]},{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#7','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'mc','auto','비율 0.07을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":7,"concept":"M6-1-u4-C5","difficulty":2,"kind":"mc","stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.04를 백분율로 나타내면 얼마인가요?","options":[{"t":"4 %","correct":true},{"t":"0.4 %","mis":"M6-1-u4-X08"},{"t":"0.04 %","mis":"M6-1-u4-X08"},{"t":"40 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.04 × 100 = 4예요.","그래서 4 %예요."]},{"stem":"비율 0.012를 백분율로 나타내면 얼마인가요?","options":[{"t":"1.2 %","correct":true},{"t":"0.12 %","mis":"M6-1-u4-X08"},{"t":"0.012 %","mis":"M6-1-u4-X08"},{"t":"12 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.012 × 100 = 1.2예요.","그래서 1.2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#8','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'match','auto','비율과 백분율을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C5","difficulty":2,"kind":"match","stem":"비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"0.35","r":"35 %"},{"l":"⟨3/4⟩","r":"75 %"},{"l":"0.07","r":"7 %"}],"mis":"M6-1-u4-X08","explanation":["비율에 100을 곱해 %를 붙여요.","0.35 → 35 %, ⟨3/4⟩ → 75 %, 0.07 → 7 %예요.","분수는 분모를 100으로 고쳐도 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"⟨1/2⟩","r":"50 %"},{"l":"0.08","r":"8 %"},{"l":"0.8","r":"80 %"}],"explanation":["비율에 100을 곱해 %를 붙여요.","⟨1/2⟩ → 50 %, 0.08 → 8 %, 0.8 → 80 %예요.","분수는 분모를 100으로 고쳐도 돼요."]},{"stem":"이번에는 다른 보기예요. 비율과 백분율을 알맞게 이으세요.","pairs":[{"l":"⟨9/20⟩","r":"45 %"},{"l":"1","r":"100 %"},{"l":"0.04","r":"4 %"}],"explanation":["비율에 100을 곱해 %를 붙여요.","⟨9/20⟩ → 45 %, 1 → 100 %, 0.04 → 4 %예요.","분수는 분모를 100으로 고쳐도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#9','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',2,'mc','auto','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C5","difficulty":2,"kind":"mc","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]},{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_basic#10','math',6,1,'u4','L05','g6_1_math_u4_L05_basic','lesson_basic','M6-1-u4-C5',3,'sa','auto','나는 공을 25번 차서 12번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C5","difficulty":3,"kind":"sa","stem":"나는 공을 25번 차서 12번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["찬 횟수 25를 100으로 맞추려면 25 × 4 = 100이에요.","넣은 횟수도 12 × 4 = 48이에요.","그래서 48번 넣은 셈 — 48 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 20번 차서 10번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["찬 횟수 20을 100으로 맞추려면 20 × 5 = 100이에요.","넣은 횟수도 10 × 5 = 50이에요.","그래서 50번 넣은 셈 — 50 %예요."]},{"stem":"언니는 공을 50번 차서 31번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["찬 횟수 50을 100으로 맞추려면 50 × 2 = 100이에요.","넣은 횟수도 31 × 2 = 62예요.","그래서 62번 넣은 셈 — 62 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#1','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',2,'sa','auto','수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]},{"stem":"줄넘기 이단 뛰기를 25번 해서 21번 성공했어요. 한 횟수에 대한 성공한 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["기준량은 25, 비교하는 양은 21이에요.","21 ÷ 25 × 100 = 84예요.","그래서 84 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#2','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',2,'sa','auto','35 %를 분모가 20인 분수로 나타내면 ⟨□/20⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"35 %를 분모가 20인 분수로 나타내면 ⟨□/20⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["35 %는 ⟨35/100⟩예요.","분모와 분자를 5로 나누면 ⟨35/100⟩ = ⟨7/20⟩이에요.","□는 7이에요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"60 %를 분모가 5인 분수로 나타내면 ⟨□/5⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["60 %는 ⟨60/100⟩이에요.","분모와 분자를 20으로 나누면 ⟨60/100⟩ = ⟨3/5⟩이에요.","□는 3이에요."]},{"stem":"24 %를 분모가 25인 분수로 나타내면 ⟨□/25⟩예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24 %는 ⟨24/100⟩예요.","분모와 분자를 4로 나누면 ⟨24/100⟩ = ⟨6/25⟩이에요.","□는 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#3','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'error','auto','비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C5","difficulty":3,"kind":"error","stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"이현 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","준희는 분모를 100으로 고치지 않았어요."],"variant_rule":{"alt":[{"stem":"비율 ⟨9/20⟩를 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「분자가 9니 9 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"수아 — 「⟨9/20⟩ = ⟨45/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「9 ÷ 20 × 100 = 45야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨9/20⟩ = ⟨45/100⟩ — 45 %예요.","서호는 분모를 100으로 고치지 않았어요."]},{"stem":"비율 ⟨7/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 7이니 7 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨7/25⟩ = ⟨28/100⟩이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「7 ÷ 25 × 100 = 28이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨7/25⟩ = ⟨28/100⟩ — 28 %예요.","가온은 분모를 100으로 고치지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#4','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'ox','auto','비율 0.07을 백분율로 나타내면 70 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":4,"concept":"M6-1-u4-C5","difficulty":3,"kind":"ox","stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩은 16 %예요.","answer":"X","reason_options":[{"t":"⟨16/25⟩ = ⟨64/100⟩라 64 %이기 때문에","correct":true},{"t":"분자 16이 백분율이기 때문에","mis":"M6-1-u4-X09"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"공을 넣은 횟수가 많은 사람이 언제나 넣은 비율도 높아요.","answer":"X","reason_options":[{"t":"찬 횟수가 다르면 백분율로 비교해야 하기 때문에","correct":true},{"t":"넣은 횟수가 곧 백분율이기 때문에","mis":"M6-1-u4-X11"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#5','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'mc','auto','세 비율 ⟨14/25⟩, 0.62, 59 % 가운데 가장 작은 것은 어느 것인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X15']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"세 비율 ⟨14/25⟩, 0.62, 59 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"⟨14/25⟩","correct":true},{"t":"0.62","mis":"M6-1-u4-X09"},{"t":"59 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨14/25⟩ → 56 %, 0.62 → 62 %, 59 % → 59 %예요.","가장 작은 것은 ⟨14/25⟩예요."],"variant_rule":{"alt":[{"stem":"세 비율 ⟨3/5⟩, 0.55, 58 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"0.55","mis":"M6-1-u4-X09"},{"t":"58 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨3/5⟩ → 60 %, 0.55 → 55 %, 58 % → 58 %예요.","가장 큰 것은 ⟨3/5⟩이에요."]},{"stem":"세 비율 ⟨7/20⟩, 0.4, 38 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"0.4","correct":true},{"t":"⟨7/20⟩","mis":"M6-1-u4-X09"},{"t":"38 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨7/20⟩ → 35 %, 0.4 → 40 %, 38 % → 38 %예요.","가장 큰 것은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#6','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'mc','auto','지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":6,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"하윤은 공을 50번 차서 34번 넣었고, 은호는 25번 차서 18번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"은호","correct":true},{"t":"하윤","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","하윤 34 ÷ 50 × 100 = 68, 은호 18 ÷ 25 × 100 = 72예요.","하윤 68 %, 은호 72 % — 은호가 더 잘 넣었어요."]},{"stem":"나는 공을 20번 차서 17번 넣었고, 동생은 40번 차서 32번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"동생","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 17 ÷ 20 × 100 = 85, 동생 32 ÷ 40 × 100 = 80이에요.","나 85 %, 동생 80 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#7','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',3,'sa','auto','자유투를 40번 던져 26번 넣었어요. 던진 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C5","difficulty":3,"kind":"sa","stem":"자유투를 40번 던져 26번 넣었어요. 던진 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량은 40, 비교하는 양은 26이에요.","26 ÷ 40 × 100 = 65예요.","그래서 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["기준량은 20, 비교하는 양은 10이에요.","10 ÷ 20 × 100 = 50이에요.","그래서 50 %예요."]},{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#8','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'mc','auto','세 비율 ⟨9/25⟩, 0.4, 3.8 % 가운데 가장 작은 것은 어느 것인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C5","difficulty":4,"kind":"mc","stem":"세 비율 ⟨9/25⟩, 0.4, 3.8 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"3.8 %","correct":true},{"t":"⟨9/25⟩","mis":"M6-1-u4-X09"},{"t":"0.4","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨9/25⟩ → 36 %, 0.4 → 40 %, 3.8 % → 3.8 %예요.","가장 작은 것은 3.8 %예요."],"variant_rule":{"alt":[{"stem":"세 비율 ⟨7/8⟩, 0.9, 88 % 가운데 가장 큰 것은 어느 것인가요?","options":[{"t":"0.9","correct":true},{"t":"⟨7/8⟩","mis":"M6-1-u4-X09"},{"t":"88 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨7/8⟩ → 87.5 %, 0.9 → 90 %, 88 % → 88 %예요.","가장 큰 것은 0.9예요."]},{"stem":"세 비율 ⟨2/5⟩, 0.04, 4.5 % 가운데 가장 작은 것은 어느 것인가요?","options":[{"t":"0.04","correct":true},{"t":"⟨2/5⟩","mis":"M6-1-u4-X09"},{"t":"4.5 %","mis":"M6-1-u4-X09"},{"t":"모두 같아요","mis":"M6-1-u4-X15"}],"explanation":["한 가지 표기로 통일해서 비교해요.","⟨2/5⟩ → 40 %, 0.04 → 4 %, 4.5 % → 4.5 %예요.","가장 작은 것은 0.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#9','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'sa','auto','나는 공을 20번 차서 13번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C5","difficulty":4,"kind":"sa","stem":"나는 공을 20번 차서 13번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["찬 횟수 20을 100으로 맞추려면 20 × 5 = 100이에요.","넣은 횟수도 13 × 5 = 65예요.","그래서 65번 넣은 셈 — 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"동생은 공을 25번 차서 14번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["찬 횟수 25를 100으로 맞추려면 25 × 4 = 100이에요.","넣은 횟수도 14 × 4 = 56이에요.","그래서 56번 넣은 셈 — 56 %예요."]},{"stem":"형은 공을 50번 차서 37번 넣었어요. 100번 찼다고 생각하면 몇 번 넣은 셈인가요? 숫자로 쓰세요.","answer":["74"],"explanation":["찬 횟수 50을 100으로 맞추려면 50 × 2 = 100이에요.","넣은 횟수도 37 × 2 = 74예요.","그래서 74번 넣은 셈 — 74 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L05_challenge#10','math',6,1,'u4','L05','g6_1_math_u4_L05_challenge','lesson_challenge','M6-1-u4-C5',4,'essay','teacher','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 찬 횟수를 100으로 맞추면 나는 25 × 4 = 100번 찼다면 12 × 4 = 48번, 동생은 20 × 5 = 100번 찼다면 10 × 5 = 50번 넣은 셈이다. 나는 48 %, 동생은 50 %이므로 동생이 더 잘 넣었다. 넣은 횟수는 내가 많지만 찬 횟수가 다르므로 백분율로 비교해야 한다.","scoring_points":["나 48 %·동생 50 %를 구했는가","동생이 더 잘 넣었다고 답했는가","찬 횟수가 달라 백분율로 비교해야 한다고 썼는가"]},"explanation":["나는 48 %, 동생은 50 %예요.","동생이 더 잘 넣었어요.","찬 횟수가 다르면 백분율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#1','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]},{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#2','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'mc','auto','은행에 120000원을 맡겼더니 이자가 6000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?',ARRAY['M6-1-u4-X08','M6-1-u4-X05']::text[],true,'{"seq":2,"concept":"M6-1-u4-C6","difficulty":1,"kind":"mc","stem":"은행에 120000원을 맡겼더니 이자가 6000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"5 %","correct":true},{"t":"50 %","mis":"M6-1-u4-X08"},{"t":"0.5 %","mis":"M6-1-u4-X08"},{"t":"20 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 120000, 비교하는 양은 이자 6000이에요.","⟨6000/120000⟩ = ⟨5/100⟩예요.","그래서 5 %예요."],"variant_rule":{"alt":[{"stem":"은행에 50000원을 맡겼더니 이자가 1000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"2 %","correct":true},{"t":"20 %","mis":"M6-1-u4-X08"},{"t":"0.2 %","mis":"M6-1-u4-X08"},{"t":"50 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 50000, 비교하는 양은 이자 1000이에요.","⟨1000/50000⟩ = ⟨2/100⟩예요.","그래서 2 %예요."]},{"stem":"은행에 80000원을 맡겼더니 이자가 2400원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"3 %","correct":true},{"t":"30 %","mis":"M6-1-u4-X08"},{"t":"0.3 %","mis":"M6-1-u4-X08"},{"t":"300 %","mis":"M6-1-u4-X08"}],"explanation":["기준량은 맡긴 돈 80000, 비교하는 양은 이자 2400이에요.","⟨2400/80000⟩ = ⟨3/100⟩이에요.","그래서 3 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#3','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'ox','auto','후보가 두 명뿐이고 무효표가 없으면 두 사람의 득표율을 더해 100 %예요.',ARRAY['M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C6","difficulty":1,"kind":"ox","stem":"후보가 두 명뿐이고 무효표가 없으면 두 사람의 득표율을 더해 100 %예요.","answer":"O","reason_options":[{"t":"전체 표가 두 사람에게 모두 나뉘기 때문에","correct":true},{"t":"득표율은 언제나 50 %씩이기 때문에","mis":"M6-1-u4-X16"}],"mis":"M6-1-u4-X16","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"120000원을 맡기고 이자 6000원을 받았다면 이자의 비율은 5 %예요.","answer":"O","reason_options":[{"t":"6000 ÷ 120000 × 100 = 5이기 때문에","correct":true},{"t":"120000 ÷ 6000을 계산하기 때문에","mis":"M6-1-u4-X05"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"진하기가 높은 설탕물이 더 달아요.","answer":"O","reason_options":[{"t":"같은 양의 설탕물에 설탕이 더 많이 들어 있기 때문에","correct":true},{"t":"설탕물의 양이 더 많기 때문에","mis":"M6-1-u4-X11"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#4','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',1,'sa','auto','가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#5','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]},{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#6','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','전체 30표 가운데 건우가 18표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"전체 30표 가운데 건우가 18표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["건우의 득표율은 18 ÷ 30 × 100 = 60이에요.","두 사람의 득표율을 더하면 100 %예요.","100 − 60 = 40 — 다른 후보는 40 %예요."],"mis":"M6-1-u4-X16","variant_rule":{"alt":[{"stem":"전체 40표 가운데 도윤이 22표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["도윤의 득표율은 22 ÷ 40 × 100 = 55예요.","두 사람의 득표율을 더하면 100 %예요.","100 − 55 = 45 — 다른 후보는 45 %예요."]},{"stem":"전체 50표 가운데 서아가 27표를 받았어요. 무효표 없이 후보가 두 명뿐이라면 다른 후보의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["서아의 득표율은 27 ÷ 50 × 100 = 54예요.","두 사람의 득표율을 더하면 100 %예요.","100 − 54 = 46 — 다른 후보는 46 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#7','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'mc','auto','가 치약은 원래 가격 3000원에서 900원을, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":7,"concept":"M6-1-u4-C6","difficulty":2,"kind":"mc","stem":"가 치약은 원래 가격 3000원에서 900원을, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 치약","correct":true},{"t":"나 치약","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 치약 900 ÷ 3000 × 100 = 30, 나 치약 1400 ÷ 5000 × 100 = 28이에요.","할인율이 더 큰 것은 가 치약이에요."],"variant_rule":{"alt":[{"stem":"가 공책은 원래 가격 2000원에서 500원을, 나 공책은 원래 가격 4000원에서 800원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 공책","correct":true},{"t":"나 공책","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 공책 500 ÷ 2000 × 100 = 25, 나 공책 800 ÷ 4000 × 100 = 20이에요.","할인율이 더 큰 것은 가 공책이에요."]},{"stem":"가 필통은 원래 가격 6000원에서 1800원을, 나 필통은 원래 가격 9000원에서 2250원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"가 필통","correct":true},{"t":"나 필통","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 필통 1800 ÷ 6000 × 100 = 30, 나 필통 2250 ÷ 9000 × 100 = 25예요.","할인율이 더 큰 것은 가 필통이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#8','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'sa','auto','아이스크림 가게에서 아이스크림 25개 가운데 19개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"아이스크림 가게에서 아이스크림 25개 가운데 19개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["기준량은 25, 비교하는 양은 19예요.","⟨19/25⟩ = ⟨76/100⟩이에요.","그래서 76 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"빵집에서 빵 40개 가운데 36개를 팔았어요. 전체 수에 대한 판매한 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 40, 비교하는 양은 36이에요.","⟨36/40⟩ = ⟨90/100⟩이에요.","그래서 90 %예요."]},{"stem":"음악회 표 50장 가운데 47장이 팔렸어요. 전체 표 수에 대한 팔린 표 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["기준량은 50, 비교하는 양은 47이에요.","⟨47/50⟩ = ⟨94/100⟩예요.","그래서 94 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#9','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',2,'ox','auto','할인 금액이 큰 물건이 언제나 할인율도 커요.',ARRAY['M6-1-u4-X11']::text[],true,'{"seq":9,"concept":"M6-1-u4-C6","difficulty":2,"kind":"ox","stem":"할인 금액이 큰 물건이 언제나 할인율도 커요.","answer":"X","reason_options":[{"t":"원래 가격이 다르면 할인율로 비교해야 하기 때문에","correct":true},{"t":"할인 금액이 곧 할인율이기 때문에","mis":"M6-1-u4-X11"}],"mis":"M6-1-u4-X11","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"설탕 30 g을 물 120 g에 녹인 설탕물의 진하기는 25 %예요.","answer":"X","reason_options":[{"t":"설탕물은 30 + 120 = 150 (g)이라 30 ÷ 150 × 100 = 20이기 때문에","correct":true},{"t":"30 ÷ 120 × 100을 계산하기 때문에","mis":"M6-1-u4-X12"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_basic#10','math',6,1,'u4','L06','g6_1_math_u4_L06_basic','lesson_basic','M6-1-u4-C6',3,'sa','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#1','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',2,'sa','auto','설탕 30 g을 물 120 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"설탕 30 g을 물 120 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["설탕물은 물과 설탕을 합한 120 + 30 = 150 (g)이에요.","30 ÷ 150 × 100 = 20이에요.","진하기는 20 %예요."],"mis":"M6-1-u4-X12","variant_rule":{"alt":[{"stem":"설탕 60 g을 물 140 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 140 + 60 = 200 (g)이에요.","60 ÷ 200 × 100 = 30이에요.","진하기는 30 %예요."]},{"stem":"설탕 45 g을 물 105 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 105 + 45 = 150 (g)이에요.","45 ÷ 150 × 100 = 30이에요.","진하기는 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#2','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',2,'mc','auto','은행에 200000원을 맡겼더니 이자가 8000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?',ARRAY['M6-1-u4-X08','M6-1-u4-X05']::text[],true,'{"seq":2,"concept":"M6-1-u4-C6","difficulty":2,"kind":"mc","stem":"은행에 200000원을 맡겼더니 이자가 8000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"4 %","correct":true},{"t":"40 %","mis":"M6-1-u4-X08"},{"t":"0.4 %","mis":"M6-1-u4-X08"},{"t":"25 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 200000, 비교하는 양은 이자 8000이에요.","⟨8000/200000⟩ = ⟨4/100⟩예요.","그래서 4 %예요."],"variant_rule":{"alt":[{"stem":"은행에 60000원을 맡겼더니 이자가 1800원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"3 %","correct":true},{"t":"30 %","mis":"M6-1-u4-X08"},{"t":"0.3 %","mis":"M6-1-u4-X08"},{"t":"300 %","mis":"M6-1-u4-X08"}],"explanation":["기준량은 맡긴 돈 60000, 비교하는 양은 이자 1800이에요.","⟨1800/60000⟩ = ⟨3/100⟩이에요.","그래서 3 %예요."]},{"stem":"은행에 250000원을 맡겼더니 이자가 5000원 붙었어요. 맡긴 돈에 대한 이자의 비율은 몇 %인가요?","options":[{"t":"2 %","correct":true},{"t":"20 %","mis":"M6-1-u4-X08"},{"t":"0.2 %","mis":"M6-1-u4-X08"},{"t":"50 %","mis":"M6-1-u4-X05"}],"explanation":["기준량은 맡긴 돈 250000, 비교하는 양은 이자 5000이에요.","⟨5000/250000⟩ = ⟨2/100⟩예요.","그래서 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#3','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'error','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X10','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C6","difficulty":3,"kind":"error","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"이현 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","준희는 할인된 가격으로 계산했어요."],"variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「20000 ÷ 25000 × 100 = 80이니 80 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"수아 — 「할인 금액은 5000원이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「할인율은 20 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","서호는 할인된 가격으로 계산했어요."]},{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「12000 ÷ 15000 × 100 = 80이니 80 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"나린 — 「할인 금액은 3000원이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「할인율은 20 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","가온은 할인된 가격으로 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#4','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'ox','auto','은행에 50000원을 맡기고 이자 1000원을 받았다면 이자의 비율은 2 %예요.',ARRAY['M6-1-u4-X03']::text[],true,'{"seq":4,"concept":"M6-1-u4-C6","difficulty":3,"kind":"ox","stem":"은행에 50000원을 맡기고 이자 1000원을 받았다면 이자의 비율은 2 %예요.","answer":"O","reason_options":[{"t":"1000 ÷ 50000 × 100 = 2이기 때문에","correct":true},{"t":"50000에서 1000을 빼서 구하기 때문에","mis":"M6-1-u4-X03"}],"mis":"M6-1-u4-X03","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"득표율은 (받은 표 수) ÷ (전체 표 수) × 100으로 구해요.","answer":"O","reason_options":[{"t":"전체 표 수에 대한 받은 표 수의 비율이기 때문에","correct":true},{"t":"받은 표 수가 기준량이기 때문에","mis":"M6-1-u4-X01"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"3000원에서 900원 할인한 것보다 5000원에서 1400원 할인한 것이 할인율이 커요.","answer":"X","reason_options":[{"t":"할인율이 30 %와 28 %라 3000원짜리가 더 크기 때문에","correct":true},{"t":"1400원이 900원보다 크기 때문에","mis":"M6-1-u4-X11"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#5','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'mc','auto','석진은 설탕 30 g을 물 70 g에, 민아는 설탕 40 g을 물 160 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X12']::text[],true,'{"seq":5,"concept":"M6-1-u4-C6","difficulty":3,"kind":"mc","stem":"석진은 설탕 30 g을 물 70 g에, 민아는 설탕 40 g을 물 160 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"석진","correct":true},{"t":"민아","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","석진 30 ÷ 100 × 100 = 30, 민아 40 ÷ 200 × 100 = 20이에요.","석진의 설탕물이 더 진해요."],"variant_rule":{"alt":[{"stem":"예은은 설탕 45 g을 물 205 g에, 지후는 설탕 42 g을 물 108 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"지후","correct":true},{"t":"예은","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","예은 45 ÷ 250 × 100 = 18, 지후 42 ÷ 150 × 100 = 28이에요.","지후의 설탕물이 더 진해요."]},{"stem":"하준은 설탕 20 g을 물 80 g에, 소율은 설탕 36 g을 물 114 g에 녹였어요. 더 진한 설탕물은 누구의 것인가요?","options":[{"t":"소율","correct":true},{"t":"하준","mis":"M6-1-u4-X11"},{"t":"두 설탕물이 같아요","mis":"M6-1-u4-X12"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["진하기는 설탕물 양에 대한 설탕 양의 비율이에요 — 설탕물 = 물 + 설탕.","하준 20 ÷ 100 × 100 = 20, 소율 36 ÷ 150 × 100 = 24예요.","소율의 설탕물이 더 진해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#6','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'sa','auto','공연장 자리 120개 가운데 42개가 예매되었어요. 전체 자리 수에 대한 예매된 자리 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"공연장 자리 120개 가운데 42개가 예매되었어요. 전체 자리 수에 대한 예매된 자리 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["기준량은 120, 비교하는 양은 42예요.","⟨42/120⟩ = ⟨35/100⟩예요.","그래서 35 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"상큼 주스 80 g에는 설탕 12 g이 들어 있어요. 주스 무게에 대한 설탕 무게의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 80, 비교하는 양은 12예요.","⟨12/80⟩ = ⟨15/100⟩예요.","그래서 15 %예요."]},{"stem":"지우는 활쏘기에서 화살 20발 가운데 17발을 맞혔어요. 쏜 화살 수에 대한 맞힌 화살 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 20, 비교하는 양은 17이에요.","⟨17/20⟩ = ⟨85/100⟩예요.","그래서 85 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#7','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',3,'sa','auto','우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"색연필은 원래 가격이 6000원인데 4500원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 6000 − 4500 = 1500이에요.","1500 ÷ 6000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"필통은 원래 가격이 8000원인데 6000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 8000 − 6000 = 2000이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#8','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'mc','auto','가 운동화는 원래 가격 50000원에서 12000원을, 나 운동화는 원래 가격 30000원에서 9000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C6","difficulty":4,"kind":"mc","stem":"가 운동화는 원래 가격 50000원에서 12000원을, 나 운동화는 원래 가격 30000원에서 9000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 운동화","correct":true},{"t":"가 운동화","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 운동화 12000 ÷ 50000 × 100 = 24, 나 운동화 9000 ÷ 30000 × 100 = 30이에요.","할인율이 더 큰 것은 나 운동화예요."],"variant_rule":{"alt":[{"stem":"가 책가방은 원래 가격 40000원에서 8000원을, 나 책가방은 원래 가격 25000원에서 6250원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 책가방","correct":true},{"t":"가 책가방","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 책가방 8000 ÷ 40000 × 100 = 20, 나 책가방 6250 ÷ 25000 × 100 = 25예요.","할인율이 더 큰 것은 나 책가방이에요."]},{"stem":"가 자전거는 원래 가격 200000원에서 30000원을, 나 자전거는 원래 가격 120000원에서 24000원을 할인해요. 할인율이 더 큰 것은 어느 것인가요?","options":[{"t":"나 자전거","correct":true},{"t":"가 자전거","mis":"M6-1-u4-X11"},{"t":"두 물건이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["원래 가격이 다르니 할인 금액이 아니라 할인율로 비교해요.","가 자전거 30000 ÷ 200000 × 100 = 15, 나 자전거 24000 ÷ 120000 × 100 = 20이에요.","할인율이 더 큰 것은 나 자전거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#9','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'sa','auto','설탕 25 g을 물 75 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C6","difficulty":4,"kind":"sa","stem":"설탕 25 g을 물 75 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["설탕물은 물과 설탕을 합한 75 + 25 = 100 (g)이에요.","25 ÷ 100 × 100 = 25예요.","진하기는 25 %예요."],"mis":"M6-1-u4-X12","variant_rule":{"alt":[{"stem":"설탕 36 g을 물 84 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["설탕물은 물과 설탕을 합한 84 + 36 = 120 (g)이에요.","36 ÷ 120 × 100 = 30이에요.","진하기는 30 %예요."]},{"stem":"설탕 18 g을 물 102 g에 녹였어요. 설탕물 양에 대한 설탕 양의 비율(진하기)은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["설탕물은 물과 설탕을 합한 102 + 18 = 120 (g)이에요.","18 ÷ 120 × 100 = 15예요.","진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L06_challenge#10','math',6,1,'u4','L06','g6_1_math_u4_L06_challenge','lesson_challenge','M6-1-u4-C6',4,'essay','teacher','가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 가 치약은 900 ÷ 3000 × 100 = 30이므로 30 %, 나 치약은 1400 ÷ 5000 × 100 = 28이므로 28 %이다. 할인율은 가 치약이 더 크다. 원래 가격(기준량)이 다르므로 할인 금액이 커도 원래 가격에 대한 비율은 작을 수 있다.","scoring_points":["30 %와 28 %를 구했는가","가 치약의 할인율이 더 크다고 비교했는가","원래 가격(기준량)이 달라서라는 까닭을 썼는가"]},"explanation":["가 30 %, 나 28 %예요.","가 치약의 할인율이 더 커요.","원래 가격이 달라 금액으로는 비교할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#1','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'mc','auto','「구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것」은 네 단계 가운데 어느 단계인가요?',ARRAY['M6-1-u4-X16']::text[],true,'{"seq":1,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"「구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것」은 네 단계 가운데 어느 단계인가요?","options":[{"t":"검토","correct":true},{"t":"이해","mis":"M6-1-u4-X16"},{"t":"계획","mis":"M6-1-u4-X16"},{"t":"해결","mis":"M6-1-u4-X16"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."],"variant_rule":{"alt":[{"stem":"백분율 문제를 풀 때 맨 먼저 하는 단계는 어느 것인가요?","options":[{"t":"무엇을 구하는지 이해하기","correct":true},{"t":"답이 맞는지 검토하기","mis":"M6-1-u4-X16"},{"t":"식을 세워 계산하기","mis":"M6-1-u4-X16"},{"t":"답을 어림해 쓰기","mis":"M6-1-u4-X16"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."]},{"stem":"전체를 100칸으로 볼 때 15 %는 무엇을 뜻하나요?","options":[{"t":"100칸 가운데 15칸","correct":true},{"t":"15칸 가운데 1칸","mis":"M6-1-u4-X13"},{"t":"한 칸의 크기가 15","mis":"M6-1-u4-X13"},{"t":"100칸 모두","mis":"M6-1-u4-X13"}],"explanation":["백분율 문제는 이해 → 계획 → 해결 → 검토로 풀어요.","전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","구한 답은 다시 비율로 만들어 조건과 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#2','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'mc','auto','전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":2,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]},{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#3','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'sa','auto','검토해요. 신재생 에너지 510000 kWh를 다시 비율로 만들면 전체 3400000 kWh의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u4-C7","difficulty":1,"kind":"sa","stem":"검토해요. 신재생 에너지 510000 kWh를 다시 비율로 만들면 전체 3400000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","510000 ÷ 3400000 × 100 = 15예요.","15 %라 조건과 맞아요."],"mis":"M6-1-u4-X08","variant_rule":{"alt":[{"stem":"검토해요. 태양광 에너지 244800 kWh를 다시 비율로 만들면 전체 510000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","244800 ÷ 510000 × 100 = 48이에요.","48 %라 조건과 맞아요."]},{"stem":"검토해요. 풍력 에너지 153000 kWh를 다시 비율로 만들면 전체 510000 kWh의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["구한 답을 다시 비율로 만들어 조건과 견주어요.","153000 ÷ 510000 × 100 = 30이에요.","30 %라 조건과 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#4','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',1,'ox','auto','전체를 100칸으로 보면 15 %는 그중 15칸이에요.',ARRAY['M6-1-u4-X13']::text[],true,'{"seq":4,"concept":"M6-1-u4-C7","difficulty":1,"kind":"ox","stem":"전체를 100칸으로 보면 15 %는 그중 15칸이에요.","answer":"O","reason_options":[{"t":"백분율은 기준량을 100으로 할 때의 비율이기 때문에","correct":true},{"t":"15칸이 한 칸의 크기이기 때문에","mis":"M6-1-u4-X13"}],"mis":"M6-1-u4-X13","explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."],"variant_rule":{"alt":[{"stem":"구한 답을 다시 비율로 만들어 조건과 맞는지 보는 것이 검토예요.","answer":"O","reason_options":[{"t":"조건과 맞으면 답이 맞다고 확인할 수 있기 때문에","correct":true},{"t":"검토는 처음 문제를 읽는 단계이기 때문에","mis":"M6-1-u4-X16"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]},{"stem":"어떤 양의 100 %는 그 양 전체예요.","answer":"O","reason_options":[{"t":"100칸 가운데 100칸이기 때문에","correct":true},{"t":"100 %는 100이라는 수이기 때문에","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#5','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]},{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#6','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'sa','auto','우리 학교 6학년 학생 150명 가운데 18 %가 안경을 써요. 안경을 쓴 6학년 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C7","difficulty":2,"kind":"sa","stem":"우리 학교 6학년 학생 150명 가운데 18 %가 안경을 써요. 안경을 쓴 6학년 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["1 %인 한 칸은 150 ÷ 100 = 1.5예요.","18 %는 1.5 × 18 = 27이에요.","답은 27명이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"도서관 책 400권 가운데 12 %가 과학책이에요. 과학책은 몇 권인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["1 %인 한 칸은 400 ÷ 100 = 4예요.","12 %는 4 × 12 = 48이에요.","답은 48권이에요."]},{"stem":"텃밭 300 m² 가운데 25 %에 상추를 심었어요. 상추를 심은 넓이는 몇 m²인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["1 %인 한 칸은 300 ÷ 100 = 3이에요.","25 %는 3 × 25 = 75예요.","답은 75 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#7','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구할 때 기준량은 무엇인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구할 때 기준량은 무엇인가요?","options":[{"t":"신재생 발전량 510000","correct":true},{"t":"전체 발전량 3400000","mis":"M6-1-u4-X14"},{"t":"태양광의 백분율 48","mis":"M6-1-u4-X13"},{"t":"한 칸의 크기 34000","mis":"M6-1-u4-X13"}],"explanation":["「신재생 에너지 가운데 48 %」니 기준량은 신재생 발전량이에요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."],"variant_rule":{"alt":[{"stem":"전교생 600명 가운데 25 %가 6학년이고, 6학년의 40 %가 안경을 써요. 안경을 쓴 6학년 수를 구할 때 기준량은 무엇인가요?","options":[{"t":"6학년 학생 수 150","correct":true},{"t":"전교생 수 600","mis":"M6-1-u4-X14"},{"t":"안경 쓴 학생의 백분율 40","mis":"M6-1-u4-X13"},{"t":"6학년의 백분율 25","mis":"M6-1-u4-X13"}],"explanation":["「6학년의 40 %」니 기준량은 6학년 학생 수예요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."]},{"stem":"용돈 20000원 가운데 30 %를 책값으로 쓰고, 책값의 50 %가 만화책이에요. 만화책 값을 구할 때 기준량은 무엇인가요?","options":[{"t":"책값 6000원","correct":true},{"t":"용돈 20000원","mis":"M6-1-u4-X14"},{"t":"만화책의 백분율 50","mis":"M6-1-u4-X13"},{"t":"책값의 백분율 30","mis":"M6-1-u4-X13"}],"explanation":["「책값의 50 %」니 기준량은 책값이에요.","조건이 바뀌면 기준량이 무엇인지 다시 확인해요.","처음 전체를 그대로 쓰면 다른 답이 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#8','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'ox','auto','전체 3400000 kWh의 15 %는 3400000 ÷ 15로 구해요.',ARRAY['M6-1-u4-X13']::text[],true,'{"seq":8,"concept":"M6-1-u4-C7","difficulty":2,"kind":"ox","stem":"전체 3400000 kWh의 15 %는 3400000 ÷ 15로 구해요.","answer":"X","reason_options":[{"t":"한 칸 3400000 ÷ 100 = 34000에 15를 곱해야 하기 때문에","correct":true},{"t":"15 %니 15로 나누면 되기 때문에","mis":"M6-1-u4-X13"}],"mis":"M6-1-u4-X13","explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."],"variant_rule":{"alt":[{"stem":"신재생 에너지의 48 %가 태양광이라면 기준량은 신재생 에너지 발전량이에요.","answer":"O","reason_options":[{"t":"「신재생 에너지의 48 %」이기 때문에","correct":true},{"t":"태양광이 48 %이기 때문에","mis":"M6-1-u4-X14"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]},{"stem":"어떤 양의 20 %는 그 양의 15 %보다 작아요.","answer":"X","reason_options":[{"t":"기준량이 같으면 20칸이 15칸보다 많기 때문에","correct":true},{"t":"20 %는 ⟨1/20⟩이기 때문에","mis":"M6-1-u4-X15"}],"explanation":["전체를 100칸으로 보고 한 칸(1 %)의 크기부터 구해요.","몇 %는 몇 칸 — 한 칸 × 칸 수예요.","기준량이 무엇인지 늘 확인하고, 답은 다시 비율로 검토해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#9','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',2,'mc','auto','행복 지역의 신재생 에너지 비율이 15 %가 아니라 20 %라면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)',ARRAY['M6-1-u4-X16','M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":9,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 신재생 에너지 비율이 15 %가 아니라 20 %라면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"680000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"68000 kWh","mis":"M6-1-u4-X15"},{"t":"170000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","20 %는 34000 × 20 = 680000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."],"variant_rule":{"alt":[{"stem":"행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"850000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"85000 kWh","mis":"M6-1-u4-X15"},{"t":"340000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","25 %는 34000 × 25 = 850000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]},{"stem":"푸른 지역의 신재생 에너지 비율이 20 %에서 30 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 2500000 kWh)","options":[{"t":"750000 kWh","correct":true},{"t":"500000 kWh","mis":"M6-1-u4-X16"},{"t":"75000 kWh","mis":"M6-1-u4-X15"},{"t":"250000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","30 %는 25000 × 30 = 750000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_basic#10','math',6,1,'u4','L07','g6_1_math_u4_L07_basic','lesson_basic','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":10,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#1','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',2,'sa','auto','주스 250 mL 가운데 20 %가 과일 원액이에요. 과일 원액은 몇 mL인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u4-C7","difficulty":2,"kind":"sa","stem":"주스 250 mL 가운데 20 %가 과일 원액이에요. 과일 원액은 몇 mL인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["1 %인 한 칸은 250 ÷ 100 = 2.5예요.","20 %는 2.5 × 20 = 50이에요.","답은 50 mL예요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"학생 80명 가운데 45 %가 걸어서 학교에 와요. 걸어서 오는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1 %인 한 칸은 80 ÷ 100 = 0.8이에요.","45 %는 0.8 × 45 = 36이에요.","답은 36명이에요."]},{"stem":"씨앗 200개 가운데 35 %가 싹을 틔웠어요. 싹 튼 씨앗은 몇 개인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["1 %인 한 칸은 200 ÷ 100 = 2예요.","35 %는 2 × 35 = 70이에요.","답은 70개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#2','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',2,'mc','auto','용돈 5000원 가운데 30 %를 저금했어요. 남은 돈은 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X13']::text[],true,'{"seq":2,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"용돈 5000원 가운데 30 %를 저금했어요. 남은 돈은 얼마인가요?","options":[{"t":"3500원","correct":true},{"t":"1500원","mis":"M6-1-u4-X16"},{"t":"4970원","mis":"M6-1-u4-X13"},{"t":"6500원","mis":"M6-1-u4-X16"}],"explanation":["30 %는 5000 × 30 ÷ 100 = 1500 (원)이에요.","남은 돈은 5000 − 1500 = 3500 (원)이에요.","남은 돈은 3500원이에요."],"variant_rule":{"alt":[{"stem":"용돈 20000원 가운데 15 %를 책을 사는 데 썼어요. 남은 돈은 얼마인가요?","options":[{"t":"17000원","correct":true},{"t":"3000원","mis":"M6-1-u4-X16"},{"t":"19985원","mis":"M6-1-u4-X13"},{"t":"23000원","mis":"M6-1-u4-X16"}],"explanation":["15 %는 20000 × 15 ÷ 100 = 3000 (원)이에요.","남은 돈은 20000 − 3000 = 17000 (원)이에요.","남은 돈은 17000원이에요."]},{"stem":"받은 상금 8000원 가운데 25 %를 기부했어요. 남은 돈은 얼마인가요?","options":[{"t":"6000원","correct":true},{"t":"2000원","mis":"M6-1-u4-X16"},{"t":"7975원","mis":"M6-1-u4-X13"},{"t":"10000원","mis":"M6-1-u4-X16"}],"explanation":["25 %는 8000 × 25 ÷ 100 = 2000 (원)이에요.","남은 돈은 8000 − 2000 = 6000 (원)이에요.","남은 돈은 6000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#3','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'error','auto','전체 발전량 3400000 kWh의 15 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X13','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C7","difficulty":3,"kind":"error","stem":"전체 발전량 3400000 kWh의 15 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「3400000 ÷ 15를 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"이현 — 「한 칸은 3400000 ÷ 100 = 34000이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「답은 510000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 34000 × 15 = 510000이에요.","준희는 전체를 15로 나누었어요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh의 20 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「2500000 ÷ 20을 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"수아 — 「한 칸은 2500000 ÷ 100 = 25000이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「답은 500000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 25000 × 20 = 500000이에요.","서호는 전체를 20으로 나누었어요."]},{"stem":"신재생 발전량 510000 kWh의 30 %를 구하는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「510000 ÷ 30을 계산하면 돼.」","correct":true,"mis_target":"M6-1-u4-X13"},{"t":"나린 — 「한 칸은 510000 ÷ 100 = 5100이야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「답은 153000 kWh야.」","mis":"M6-1-u4-X16"}],"explanation":["1 %인 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 5100 × 30 = 153000이에요.","가온은 전체를 30으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#4','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":4,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"24480 kWh","mis":"M6-1-u4-X15"},{"t":"10625 kWh","mis":"M6-1-u4-X13"},{"t":"2448000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","48 %는 48칸이라 5100 × 48 = 244800이에요.","답은 244800 kWh예요."]},{"stem":"한 공장의 전체 사용 전력은 800000 kWh이고 그중 35 %를 태양광으로 만들어요. 태양광으로 만든 전력은 몇 kWh인가요?","options":[{"t":"280000 kWh","correct":true},{"t":"28000 kWh","mis":"M6-1-u4-X15"},{"t":"2800000 kWh","mis":"M6-1-u4-X15"},{"t":"520000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 800000을 100칸으로 보면 한 칸은 800000 ÷ 100 = 8000이에요.","35 %는 35칸이라 8000 × 35 = 280000이에요.","답은 280000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#5','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":5,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#6','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'sa','auto','어떤 수의 25 %가 20이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C7","difficulty":3,"kind":"sa","stem":"어떤 수의 25 %가 20이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["어떤 수를 100칸으로 보면 25칸이 20이에요.","한 칸은 20 ÷ 25 = 0.8이에요.","100칸은 0.8 × 100 = 80이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"어떤 수의 50 %가 36이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["어떤 수를 100칸으로 보면 50칸이 36이에요.","한 칸은 36 ÷ 50 = 0.72예요.","100칸은 0.72 × 100 = 72예요."]},{"stem":"어떤 수의 20 %가 9예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["어떤 수를 100칸으로 보면 20칸이 9예요.","한 칸은 9 ÷ 20 = 0.45예요.","100칸은 0.45 × 100 = 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#7','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',3,'mc','auto','행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)',ARRAY['M6-1-u4-X16','M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"행복 지역의 신재생 에너지 비율이 15 %에서 25 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 3400000 kWh)","options":[{"t":"850000 kWh","correct":true},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"85000 kWh","mis":"M6-1-u4-X15"},{"t":"340000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 3400000 ÷ 100 = 34000이에요.","25 %는 34000 × 25 = 850000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 신재생 에너지 비율이 20 %에서 30 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 2500000 kWh)","options":[{"t":"750000 kWh","correct":true},{"t":"500000 kWh","mis":"M6-1-u4-X16"},{"t":"75000 kWh","mis":"M6-1-u4-X15"},{"t":"250000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 2500000 ÷ 100 = 25000이에요.","30 %는 25000 × 30 = 750000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]},{"stem":"맑은 지역의 신재생 에너지 비율이 10 %에서 15 %로 늘면 신재생 발전량은 몇 kWh가 되나요? (전체 4200000 kWh)","options":[{"t":"630000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X16"},{"t":"63000 kWh","mis":"M6-1-u4-X15"},{"t":"210000 kWh","mis":"M6-1-u4-X13"}],"explanation":["1 %인 한 칸은 4200000 ÷ 100 = 42000이에요.","15 %는 42000 × 15 = 630000이에요.","조건이 바뀌면 칸 수부터 다시 세어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#8','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'mc','auto','가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":8,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."],"variant_rule":{"alt":[{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]},{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#9','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'sa','auto','어떤 수의 40 %가 24예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u4-C7","difficulty":4,"kind":"sa","stem":"어떤 수의 40 %가 24예요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["어떤 수를 100칸으로 보면 40칸이 24예요.","한 칸은 24 ÷ 40 = 0.6이에요.","100칸은 0.6 × 100 = 60이에요."],"mis":"M6-1-u4-X13","variant_rule":{"alt":[{"stem":"어떤 수의 60 %가 33이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["어떤 수를 100칸으로 보면 60칸이 33이에요.","한 칸은 33 ÷ 60 = 0.55예요.","100칸은 0.55 × 100 = 55예요."]},{"stem":"어떤 수의 75 %가 60이에요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["어떤 수를 100칸으로 보면 75칸이 60이에요.","한 칸은 60 ÷ 75 = 0.8이에요.","100칸은 0.8 × 100 = 80이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_L07_challenge#10','math',6,1,'u4','L07','g6_1_math_u4_L07_challenge','lesson_challenge','M6-1-u4-C7',4,'essay','teacher','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 전체를 100칸으로 보는 방법으로 신재생 에너지 발전량을 구하고, 구한 답이 맞는지 검토하는 방법도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u4-C7","difficulty":4,"kind":"essay","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 전체를 100칸으로 보는 방법으로 신재생 에너지 발전량을 구하고, 구한 답이 맞는지 검토하는 방법도 써 보세요.","answer_guide":{"answer":"예: 전체를 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000 (kWh)이다. 15 %는 15칸이므로 34000 × 15 = 510000 (kWh)이다. 검토: 510000 ÷ 3400000 × 100 = 15이므로 조건 15 %와 맞는다.","scoring_points":["한 칸 34000을 구했는가","510000 kWh를 구했는가","다시 비율로 만들어 15 %와 맞는지 검토했는가"]},"explanation":["한 칸은 34000 kWh예요.","15칸은 510000 kWh예요.","510000 ÷ 3400000 × 100 = 15로 검토해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#1','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',1,'mc','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."],"variant_rule":{"alt":[{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]},{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#2','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',1,'sa','auto','비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]},{"stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#3','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C3',1,'mc','auto','비 3：10의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."],"variant_rule":{"alt":[{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]},{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#4','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',1,'mc','auto','푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]},{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#5','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.35를 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]},{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#6','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]},{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#7','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]},{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#8','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C1',1,'sa','auto','매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."]},{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#9','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C3',2,'mc','auto','집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."],"variant_rule":{"alt":[{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]},{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#10','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',2,'sa','auto','자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]},{"stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#11','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',2,'sa','auto','우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]},{"stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#12','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]},{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#13','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',2,'sa','auto','가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#14','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',2,'sa','auto','지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]},{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#15','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',2,'ox','auto','3：4와 4：3은 같은 비예요.',ARRAY['M6-1-u4-X02']::text[],true,'{"seq":15,"concept":"M6-1-u4-C2","difficulty":2,"kind":"ox","stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"mis":"M6-1-u4-X02","explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."],"variant_rule":{"alt":[{"stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]},{"stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#16','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',2,'mc','auto','행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."],"variant_rule":{"alt":[{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]},{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#17','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C4',3,'mc','auto','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]},{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#18','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',3,'mc','auto','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]},{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#19','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C6',3,'sa','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#20','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C1',3,'sa','auto','가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]},{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#21','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',3,'error','auto','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C2","difficulty":3,"kind":"error","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."],"variant_rule":{"alt":[{"stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."]},{"stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#22','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#23','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C7',4,'mc','auto','가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."],"variant_rule":{"alt":[{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]},{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#24','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C2',4,'essay','teacher','바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 친구는 「바닷물 양에 대한 소금 양의 비」를 150：6이라고 썼어요. 바른 비와 비율을 구하고, 친구가 무엇을 잘못했는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C2","difficulty":4,"kind":"essay","stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 친구는 「바닷물 양에 대한 소금 양의 비」를 150：6이라고 썼어요. 바른 비와 비율을 구하고, 친구가 무엇을 잘못했는지 설명해 보세요.","answer_guide":{"answer":"예: 「바닷물 양에 대한」이므로 기준량은 바닷물 양 150이고 비교하는 양은 소금 양 6이다. 바른 비는 6：150이고 비율은 6 ÷ 150 = 0.04이다. 친구는 기준량과 비교하는 양의 자리를 바꾸어 썼다.","scoring_points":["기준량 150·비교하는 양 6을 찾았는가","6：150과 비율 0.04를 구했는가","기준량과 비교하는 양을 바꾸었다고 설명했는가"]},"explanation":["기준량은 바닷물 양 150이에요.","비는 6：150, 비율은 0.04예요.","친구는 두 양의 자리를 바꾸었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_a#25','math',6,1,'u4','','g6_1_math_u4_review_a','unit_review','M6-1-u4-C5',4,'essay','teacher','세 비율 ⟨14/25⟩, 0.62, 59 %의 크기를 비교하는 방법을 쓰고, 가장 작은 것을 찾아 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"세 비율 ⟨14/25⟩, 0.62, 59 %의 크기를 비교하는 방법을 쓰고, 가장 작은 것을 찾아 보세요.","answer_guide":{"answer":"예: 세 비율을 모두 백분율로 바꾸어 비교한다. ⟨14/25⟩ = ⟨56/100⟩이므로 56 %, 0.62 × 100 = 62이므로 62 %, 그리고 59 %이다. 56 % < 59 % < 62 %이므로 가장 작은 것은 ⟨14/25⟩이다.","scoring_points":["한 가지 표기(백분율 등)로 통일했는가","56 %·62 %·59 %로 바꾸었는가","⟨14/25⟩가 가장 작다고 답했는가"]},"explanation":["모두 백분율로 바꾸어요.","56 %, 62 %, 59 %예요.","가장 작은 것은 ⟨14/25⟩예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#1','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C2',1,'mc','auto','팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."],"variant_rule":{"alt":[{"stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."]},{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#2','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C2',1,'sa','auto','비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."]},{"stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#3','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',1,'mc','auto','비 1：4의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X15']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."],"variant_rule":{"alt":[{"stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."]},{"stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#4','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',1,'mc','auto','노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."],"variant_rule":{"alt":[{"stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."]},{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#5','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.83을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."]},{"stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#6','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."]},{"stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#7','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."]},{"stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#8','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C1',1,'sa','auto','팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."]},{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#9','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',2,'mc','auto','가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."],"variant_rule":{"alt":[{"stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."]},{"stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#10','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',2,'sa','auto','자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."]},{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#11','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',2,'sa','auto','전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."]},{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#12','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."]},{"stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#13','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',2,'sa','auto','공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#14','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',2,'sa','auto','예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."]},{"stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#15','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',2,'ox','auto','비율은 언제나 1보다 작아요.',ARRAY['M6-1-u4-X06']::text[],true,'{"seq":15,"concept":"M6-1-u4-C3","difficulty":2,"kind":"ox","stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"mis":"M6-1-u4-X06","explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."],"variant_rule":{"alt":[{"stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."]},{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#16','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',2,'mc','auto','푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."],"variant_rule":{"alt":[{"stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."]},{"stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#17','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C4',3,'mc','auto','다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."]},{"stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#18','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C5',3,'mc','auto','나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."]},{"stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#19','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C6',3,'sa','auto','가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."]},{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#20','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C1',3,'sa','auto','가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."]},{"stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#21','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',3,'error','auto','비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C3","difficulty":3,"kind":"error","stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."],"variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."]},{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#22','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."]},{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#23','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',4,'mc','auto','다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."],"variant_rule":{"alt":[{"stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."]},{"stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#24','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C3',4,'essay','teacher','가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C3","difficulty":4,"kind":"essay","stem":"가로에 대한 세로의 비가 15：25, 30：50, 6：10인 세 직사각형이 있어요. 세 비율을 소수로 구해 비교하고, 기준량이 다른데도 비율이 같은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 15 ÷ 25 = 0.6, 30 ÷ 50 = 0.6, 6 ÷ 10 = 0.6이므로 세 비율은 모두 0.6으로 같다. 세 직사각형은 크기는 다르지만 가로에 대한 세로의 관계(세로가 가로의 0.6배)가 같아서, 기준량이 달라도 비율이 같다.","scoring_points":["세 비율을 0.6으로 구했는가","세 비율이 같다고 비교했는가","관계가 같으면 기준량이 달라도 비율이 같다고 설명했는가"]},"explanation":["세 비율은 모두 0.6이에요.","크기는 달라도 모양(관계)이 같아요.","그래서 기준량이 달라도 비율이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_b#25','math',6,1,'u4','','g6_1_math_u4_review_b','unit_review','M6-1-u4-C7',4,'essay','teacher','신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구하고, 친구가 전체 발전량 3400000 kWh의 48 %를 구한 것이 왜 틀렸는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C7","difficulty":4,"kind":"essay","stem":"신재생 에너지 510000 kWh 가운데 48 %가 태양광 에너지예요. 태양광 발전량을 구하고, 친구가 전체 발전량 3400000 kWh의 48 %를 구한 것이 왜 틀렸는지 설명해 보세요.","answer_guide":{"answer":"예: 기준량은 신재생 에너지 발전량 510000이다. 한 칸은 510000 ÷ 100 = 5100이고 48칸은 5100 × 48 = 244800이므로 태양광 발전량은 244800 kWh이다. 친구는 「신재생 에너지의 48 %」인데 기준량을 전체 발전량으로 잘못 잡았다.","scoring_points":["기준량을 510000으로 잡았는가","244800 kWh를 구했는가","기준량이 바뀐 것을 놓쳤다고 설명했는가"]},"explanation":["기준량은 510000이에요.","5100 × 48 = 244800 — 244800 kWh예요.","친구는 기준량을 바꾸지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#1','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C2',1,'mc','auto','닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"닭 2마리와 병아리 5마리가 있어요. 닭 수에 대한 병아리 수의 비는 어느 것인가요?","options":[{"t":"5：2","correct":true},{"t":"2：5","mis":"M6-1-u4-X01"},{"t":"5：7","mis":"M6-1-u4-X07"},{"t":"3：5","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 닭 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 5：2예요."],"variant_rule":{"alt":[{"stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."]},{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#2','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C2',1,'sa','auto','비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 13：23에서 전항은 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","13：23에서 전항은 13, 후항은 23이에요.","그래서 전항은 13이에요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."]},{"stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#3','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C3',1,'mc','auto','비 6：5의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 6：5의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"1.2","correct":true},{"t":"12","mis":"M6-1-u4-X15"},{"t":"0.12","mis":"M6-1-u4-X15"},{"t":"2.2","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","6：5의 비율은 6 ÷ 5 = 1.2예요.","분수로는 ⟨6/5⟩, 소수로는 1.2예요."],"variant_rule":{"alt":[{"stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."]},{"stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#4','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',1,'mc','auto','초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X07','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"초록 팀은 10경기를 치러서 5경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.5","correct":true},{"t":"2","mis":"M6-1-u4-X05"},{"t":"1","mis":"M6-1-u4-X07"},{"t":"5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 10, 비교하는 양은 이긴 경기 수 5예요.","⟨5/10⟩ = 0.5예요.","초록 팀의 비율은 0.5예요."],"variant_rule":{"alt":[{"stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."]},{"stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#5','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.6을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.6을 백분율로 나타내면 얼마인가요?","options":[{"t":"60 %","correct":true},{"t":"6 %","mis":"M6-1-u4-X08"},{"t":"0.6 %","mis":"M6-1-u4-X08"},{"t":"600 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.6 × 100 = 60이에요.","그래서 60 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."]},{"stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#6','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 25표 가운데 하늘이 9표를 받았어요. 하늘의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","9 ÷ 25 × 100 = 36이에요.","하늘의 득표율은 36 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."]},{"stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#7','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',1,'mc','auto','신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"신재생 발전량 510000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"5100 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"510 kWh","mis":"M6-1-u4-X15"},{"t":"51000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","510000 ÷ 100 = 5100이에요.","한 칸은 5100 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."]},{"stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#8','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C1',1,'sa','auto','꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"꽃다발 한 개에는 안개꽃 12송이와 장미 3송이가 들어가요. 나눗셈으로 비교하면 안개꽃은 장미의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","12 ÷ 3 = 4예요.","안개꽃은 장미의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."]},{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#9','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C3',2,'mc','auto','마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X05','M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"마을 자전거 도로 15 km 가운데 12 km가 완성되었어요. 전체 길이에 대한 완성된 길이의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.8","correct":true},{"t":"1.25","mis":"M6-1-u4-X05"},{"t":"0.2","mis":"M6-1-u4-X16"},{"t":"8","mis":"M6-1-u4-X15"}],"explanation":["기준량은 15, 비교하는 양은 12예요.","12 ÷ 15 = 0.8이에요.","그래서 비율은 0.8이에요."],"variant_rule":{"alt":[{"stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."]},{"stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#10','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',2,'sa','auto','기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"기차가 2시간 동안 180 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 180이에요.","180 ÷ 2 = 90이에요.","1시간에 90 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."]},{"stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#11','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'sa','auto','수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"수학 문제 40개 가운데 34개를 맞혔어요. 전체 문제 수에 대한 맞힌 문제 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["기준량은 40, 비교하는 양은 34예요.","34 ÷ 40 × 100 = 85예요.","그래서 85 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."]},{"stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#12','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨9/20⟩를 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨9/20⟩ = ⟨45/100⟩예요.","그래서 ⟨9/20⟩는 45 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."]},{"stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#13','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',2,'sa','auto','필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"필통은 원래 가격 8000원에서 2000원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","2000 ÷ 8000 × 100 = 25예요.","할인율은 25 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."]},{"stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#14','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',2,'sa','auto','민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"민서는 설탕 45 g을 녹여 설탕물 300 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["기준량은 설탕물 300 g, 비교하는 양은 설탕 45 g이에요.","45 ÷ 300 × 100 = 15예요.","설탕물의 진하기는 15 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."]},{"stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#15','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',2,'ox','auto','비율 0.07을 백분율로 나타내면 70 %예요.',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":15,"concept":"M6-1-u4-C5","difficulty":2,"kind":"ox","stem":"비율 0.07을 백분율로 나타내면 70 %예요.","answer":"X","reason_options":[{"t":"0.07 × 100 = 7이라 7 %이기 때문에","correct":true},{"t":"0.07의 7 뒤에 0을 붙이면 되기 때문에","mis":"M6-1-u4-X08"}],"mis":"M6-1-u4-X08","explanation":["기준량을 100으로 할 때의 비율을 백분율이라 하고 %를 써요.","비율에 100을 곱해서 나온 값에 %를 붙여요.","기준량이 100인 분수로 바꾸어도 돼요."],"variant_rule":{"alt":[{"stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."]},{"stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#16','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',2,'mc','auto','맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"맑은 지역의 전체 발전량은 4200000 kWh이고 그중 10 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"420000 kWh","correct":true},{"t":"42000 kWh","mis":"M6-1-u4-X15"},{"t":"4200000 kWh","mis":"M6-1-u4-X15"},{"t":"3780000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 4200000을 100칸으로 보면 한 칸은 4200000 ÷ 100 = 42000이에요.","10 %는 10칸이라 42000 × 10 = 420000이에요.","답은 420000 kWh예요."],"variant_rule":{"alt":[{"stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."]},{"stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#17','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C4',3,'mc','auto','바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"바 마을은 넓이 4 km²에 7200명, 마 마을은 넓이 6 km²에 9000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"바 마을","correct":true},{"t":"마 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","바 7200 ÷ 4 = 1800, 마 9000 ÷ 6 = 1500이에요.","비율이 큰 바 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."]},{"stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#18','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',3,'mc','auto','형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"형은 공을 50번 차서 30번 넣었고, 나는 20번 차서 13번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"나","correct":true},{"t":"형","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","형 30 ÷ 50 × 100 = 60, 나 13 ÷ 20 × 100 = 65예요.","형 60 %, 나 65 % — 나가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."]},{"stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#19','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',3,'sa','auto','모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"모자는 원래 가격이 20000원인데 17000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 20000 − 17000 = 3000이에요.","3000 ÷ 20000 × 100 = 15예요.","할인율은 15 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."]},{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#20','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C1',3,'sa','auto','가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 6 cm, 세로 4 cm인 직사각형을 모양 그대로 키웠더니 세로가 10 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 10 ÷ 4 = 2.5배가 되었어요.","가로도 6 × 2.5 = 15 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."]},{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#21','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C5',3,'error','auto','비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X09','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C5","difficulty":3,"kind":"error","stem":"비율 ⟨16/25⟩을 백분율로 나타내는 것을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「분자가 16이니 16 %야.」","correct":true,"mis_target":"M6-1-u4-X09"},{"t":"나린 — 「⟨16/25⟩ = ⟨64/100⟩야.」","mis":"M6-1-u4-X16"},{"t":"유진 — 「16 ÷ 25 × 100 = 64야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량을 100으로 맞추어야 해요.","⟨16/25⟩ = ⟨64/100⟩ — 64 %예요.","가온은 분모를 100으로 고치지 않았어요."],"variant_rule":{"alt":[{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."]},{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#22','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 2000000 kWh의 20 %가 신재생 에너지이고, 신재생 에너지의 40 %가 수력이에요. 수력 발전량은 몇 kWh인가요?","options":[{"t":"160000 kWh","correct":true},{"t":"800000 kWh","mis":"M6-1-u4-X14"},{"t":"400000 kWh","mis":"M6-1-u4-X16"},{"t":"1200000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 2000000 × 20 ÷ 100 = 400000이에요.","기준량이 400000으로 바뀌어요 — 400000 × 40 ÷ 100 = 160000이에요.","답은 160000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."]},{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#23','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C7',4,'mc','auto','마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"마 지역은 전체 발전량 1500000 kWh 가운데 30 %, 바 지역은 전체 발전량 2500000 kWh 가운데 20 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"바 지역","correct":true},{"t":"마 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","마 1500000 × 30 ÷ 100 = 450000, 바 2500000 × 20 ÷ 100 = 500000이에요.","발전량이 더 많은 곳은 바 지역이에요."],"variant_rule":{"alt":[{"stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."]},{"stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#24','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',4,'essay','teacher','설탕 30 g을 물 120 g에 녹였어요. 친구는 이 설탕물의 진하기를 25 %라고 했어요. 바른 진하기를 구하고, 친구가 잘못한 점을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"설탕 30 g을 물 120 g에 녹였어요. 친구는 이 설탕물의 진하기를 25 %라고 했어요. 바른 진하기를 구하고, 친구가 잘못한 점을 설명해 보세요.","answer_guide":{"answer":"예: 설탕물은 물과 설탕을 합한 120 + 30 = 150 (g)이다. 진하기는 설탕물 양에 대한 설탕 양의 비율이므로 30 ÷ 150 × 100 = 20, 20 %이다. 친구는 기준량을 설탕물 150 g이 아니라 물 120 g으로 잘못 잡았다.","scoring_points":["설탕물 150 g을 구했는가","20 %를 구했는가","기준량을 물의 양으로 잘못 잡았다고 설명했는가"]},"explanation":["설탕물은 150 g이에요.","30 ÷ 150 × 100 = 20 — 20 %예요.","친구는 물의 양을 기준량으로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_c#25','math',6,1,'u4','','g6_1_math_u4_review_c','unit_review','M6-1-u4-C6',4,'essay','teacher','가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C6","difficulty":4,"kind":"essay","stem":"가 치약은 원래 가격 3000원에서 900원, 나 치약은 원래 가격 5000원에서 1400원을 할인해요. 두 치약의 할인율을 구해 비교하고, 할인 금액이 더 큰 나 치약의 할인율이 더 작은 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 가 치약은 900 ÷ 3000 × 100 = 30이므로 30 %, 나 치약은 1400 ÷ 5000 × 100 = 28이므로 28 %이다. 할인율은 가 치약이 더 크다. 원래 가격(기준량)이 다르므로 할인 금액이 커도 원래 가격에 대한 비율은 작을 수 있다.","scoring_points":["30 %와 28 %를 구했는가","가 치약의 할인율이 더 크다고 비교했는가","원래 가격(기준량)이 달라서라는 까닭을 썼는가"]},"explanation":["가 30 %, 나 28 %예요.","가 치약의 할인율이 더 커요.","원래 가격이 달라 금액으로는 비교할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#1','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C2',1,'mc','auto','치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?',ARRAY['M6-1-u4-X01','M6-1-u4-X07','M6-1-u4-X03']::text[],true,'{"seq":1,"concept":"M6-1-u4-C2","difficulty":1,"kind":"mc","stem":"치즈 4장과 달걀부침 3개로 샌드위치를 만들었어요. 치즈 수에 대한 달걀부침 수의 비는 어느 것인가요?","options":[{"t":"3：4","correct":true},{"t":"4：3","mis":"M6-1-u4-X01"},{"t":"3：7","mis":"M6-1-u4-X07"},{"t":"1：4","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 치즈 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 3：4예요."],"variant_rule":{"alt":[{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 어느 것인가요?","options":[{"t":"6：150","correct":true},{"t":"150：6","mis":"M6-1-u4-X01"},{"t":"6：144","mis":"M6-1-u4-X03"},{"t":"25：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 6：150이에요."]},{"stem":"팔찌 하나에 파란 구슬 2개와 노란 구슬 10개를 꿰어요. 파란 구슬 수와 노란 구슬 수의 비는 어느 것인가요?","options":[{"t":"2：10","correct":true},{"t":"10：2","mis":"M6-1-u4-X01"},{"t":"2：8","mis":"M6-1-u4-X03"},{"t":"5：1","mis":"M6-1-u4-X03"}],"explanation":["「○에 대한」 쪽이 기준량이에요 — 여기서 기준량은 노란 구슬 수예요.","비는 (비교하는 양)：(기준량) 차례로 써요.","그래서 2：10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#2','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C2',1,'sa','auto','비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u4-C2","difficulty":1,"kind":"sa","stem":"비 5：8에서 비교하는 양은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","5：8에서 전항은 5, 후항은 8이에요.","그래서 비교하는 양은 5예요."],"mis":"M6-1-u4-X01","variant_rule":{"alt":[{"stem":"비 2：10에서 기준량은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","2：10에서 전항은 2, 후항은 10이에요.","그래서 기준량은 10이에요."]},{"stem":"비 9：20에서 후항은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["기호 ：의 앞에 있는 수가 비교하는 양(전항), 뒤에 있는 수가 기준량(후항)이에요.","9：20에서 전항은 9, 후항은 20이에요.","그래서 후항은 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#3','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C3',1,'mc','auto','비 7：20의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X16']::text[],true,'{"seq":3,"concept":"M6-1-u4-C3","difficulty":1,"kind":"mc","stem":"비 7：20의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.35","correct":true},{"t":"3.5","mis":"M6-1-u4-X15"},{"t":"0.035","mis":"M6-1-u4-X15"},{"t":"0.65","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","7：20의 비율은 7 ÷ 20 = 0.35예요.","분수로는 ⟨7/20⟩, 소수로는 0.35예요."],"variant_rule":{"alt":[{"stem":"비 3：10의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"},{"t":"0.7","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","3：10의 비율은 3 ÷ 10 = 0.3이에요.","분수로는 ⟨3/10⟩, 소수로는 0.3이에요."]},{"stem":"비 1：4의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.25","correct":true},{"t":"4","mis":"M6-1-u4-X05"},{"t":"2.5","mis":"M6-1-u4-X15"},{"t":"0.025","mis":"M6-1-u4-X15"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","1：4의 비율은 1 ÷ 4 = 0.25예요.","분수로는 ⟨1/4⟩, 소수로는 0.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#4','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',1,'mc','auto','빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X07','M6-1-u4-X15']::text[],true,'{"seq":4,"concept":"M6-1-u4-C4","difficulty":1,"kind":"mc","stem":"빨강 팀은 8경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.75","correct":true},{"t":"0.25","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X07"},{"t":"7.5","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 8, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/8⟩ = 0.75예요.","빨강 팀의 비율은 0.75예요."],"variant_rule":{"alt":[{"stem":"푸른 팀은 15경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 15, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/15⟩ = 0.4예요.","푸른 팀의 비율은 0.4예요."]},{"stem":"노란 팀은 20경기를 치러서 6경기를 이겼어요. 전체 경기 수에 대한 이긴 경기 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.3","correct":true},{"t":"0.7","mis":"M6-1-u4-X16"},{"t":"3","mis":"M6-1-u4-X15"},{"t":"0.03","mis":"M6-1-u4-X15"}],"explanation":["기준량은 전체 경기 수 20, 비교하는 양은 이긴 경기 수 6이에요.","⟨6/20⟩ = 0.3이에요.","노란 팀의 비율은 0.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#5','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',1,'mc','auto','비율 0.07을 백분율로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X08']::text[],true,'{"seq":5,"concept":"M6-1-u4-C5","difficulty":1,"kind":"mc","stem":"비율 0.07을 백분율로 나타내면 얼마인가요?","options":[{"t":"7 %","correct":true},{"t":"0.7 %","mis":"M6-1-u4-X08"},{"t":"0.07 %","mis":"M6-1-u4-X08"},{"t":"70 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.07 × 100 = 7이에요.","그래서 7 %예요."],"variant_rule":{"alt":[{"stem":"비율 0.35를 백분율로 나타내면 얼마인가요?","options":[{"t":"35 %","correct":true},{"t":"3.5 %","mis":"M6-1-u4-X08"},{"t":"0.35 %","mis":"M6-1-u4-X08"},{"t":"350 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.35 × 100 = 35예요.","그래서 35 %예요."]},{"stem":"비율 0.83을 백분율로 나타내면 얼마인가요?","options":[{"t":"83 %","correct":true},{"t":"8.3 %","mis":"M6-1-u4-X08"},{"t":"0.83 %","mis":"M6-1-u4-X08"},{"t":"830 %","mis":"M6-1-u4-X08"}],"explanation":["비율에 100을 곱해서 나온 값에 %를 붙여요.","0.83 × 100 = 83이에요.","그래서 83 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#6','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',1,'sa','auto','학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u4-C6","difficulty":1,"kind":"sa","stem":"학급 회장 선거에서 전체 40표 가운데 도윤이 22표를 받았어요. 도윤의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","22 ÷ 40 × 100 = 55예요.","도윤의 득표율은 55 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"학급 회장 선거에서 전체 30표 가운데 건우가 18표를 받았어요. 건우의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","18 ÷ 30 × 100 = 60이에요.","건우의 득표율은 60 %예요."]},{"stem":"학급 회장 선거에서 전체 30표 가운데 수빈이가 12표를 받았어요. 수빈이의 득표율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["득표율은 전체 표 수에 대한 받은 표 수의 비율이에요.","12 ÷ 30 × 100 = 40이에요.","수빈이의 득표율은 40 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#7','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',1,'mc','auto','전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":7,"concept":"M6-1-u4-C7","difficulty":1,"kind":"mc","stem":"전체 발전량 4200000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"42000 kWh","correct":true},{"t":"420000 kWh","mis":"M6-1-u4-X15"},{"t":"4200 kWh","mis":"M6-1-u4-X15"},{"t":"420000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","4200000 ÷ 100 = 42000이에요.","한 칸은 42000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"34000 kWh","correct":true},{"t":"340000 kWh","mis":"M6-1-u4-X15"},{"t":"3400 kWh","mis":"M6-1-u4-X15"},{"t":"340000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","3400000 ÷ 100 = 34000이에요.","한 칸은 34000 kWh예요."]},{"stem":"전체 발전량 2500000 kWh를 100칸으로 나누면 한 칸은 몇 kWh인가요?","options":[{"t":"25000 kWh","correct":true},{"t":"250000 kWh","mis":"M6-1-u4-X15"},{"t":"2500 kWh","mis":"M6-1-u4-X15"},{"t":"250000000 kWh","mis":"M6-1-u4-X13"}],"explanation":["전체를 100칸으로 나누면 한 칸은 전체의 1 %예요.","2500000 ÷ 100 = 25000이에요.","한 칸은 25000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#8','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C1',1,'sa','auto','하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u4-C1","difficulty":1,"kind":"sa","stem":"하늘색 물감 한 접시에는 흰색 물감 8방울과 파란색 물감 2방울이 들어가요. 나눗셈으로 비교하면 흰색 물감은 파란색 물감의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","8 ÷ 2 = 4예요.","흰색 물감은 파란색 물감의 4배예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"매실 주스 한 병에는 물 4컵과 매실 원액 1컵이 들어가요. 나눗셈으로 비교하면 물은 매실 원액의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","4 ÷ 1 = 4예요.","물은 매실 원액의 4배예요."]},{"stem":"팔찌 한 개에는 노란 구슬 10개와 파란 구슬 2개가 들어가요. 나눗셈으로 비교하면 노란 구슬은 파란 구슬의 몇 배인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["나눗셈으로 비교하면 몇 배인지 알 수 있어요.","10 ÷ 2 = 5예요.","노란 구슬은 파란 구슬의 5배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#9','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C3',2,'mc','auto','세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?',ARRAY['M6-1-u4-X16','M6-1-u4-X15']::text[],true,'{"seq":9,"concept":"M6-1-u4-C3","difficulty":2,"kind":"mc","stem":"세계 환경의 날 기념 행사에 어린이 50명이 지원해서 9명이 당첨되었어요. 지원한 어린이 수에 대한 당첨된 어린이 수의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.18","correct":true},{"t":"0.82","mis":"M6-1-u4-X16"},{"t":"1.8","mis":"M6-1-u4-X15"},{"t":"0.018","mis":"M6-1-u4-X15"}],"explanation":["기준량은 50, 비교하는 양은 9예요.","9 ÷ 50 = 0.18이에요.","그래서 비율은 0.18이에요."],"variant_rule":{"alt":[{"stem":"집에서 할머니 댁까지는 20 km, 집에서 주유소까지는 8 km예요. 집과 할머니 댁 사이 거리에 대한 집과 주유소 사이 거리의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.4","correct":true},{"t":"2.5","mis":"M6-1-u4-X05"},{"t":"0.6","mis":"M6-1-u4-X16"},{"t":"4","mis":"M6-1-u4-X15"}],"explanation":["기준량은 20, 비교하는 양은 8이에요.","8 ÷ 20 = 0.4예요.","그래서 비율은 0.4예요."]},{"stem":"가로 40 cm, 세로 24 cm인 태극기 액자가 있어요. 가로에 대한 세로의 비율을 소수로 나타내면 얼마인가요?","options":[{"t":"0.6","correct":true},{"t":"0.4","mis":"M6-1-u4-X16"},{"t":"6","mis":"M6-1-u4-X15"},{"t":"0.06","mis":"M6-1-u4-X15"}],"explanation":["기준량은 40, 비교하는 양은 24예요.","24 ÷ 40 = 0.6이에요.","그래서 비율은 0.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#10','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',2,'sa','auto','유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u4-C4","difficulty":2,"kind":"sa","stem":"유람선이 4시간 동안 36 km를 갔어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["기준량은 이동한 시간 4, 비교하는 양은 이동한 거리 36이에요.","36 ÷ 4 = 9예요.","1시간에 9 km만큼 이동한 셈이에요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"자율 주행 자동차가 2시간 동안 160 km를 이동했어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["기준량은 이동한 시간 2, 비교하는 양은 이동한 거리 160이에요.","160 ÷ 2 = 80이에요.","1시간에 80 km만큼 이동한 셈이에요."]},{"stem":"자전거로 3시간 동안 12 km를 달렸어요. 이동한 시간에 대한 이동한 거리의 비율은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["기준량은 이동한 시간 3, 비교하는 양은 이동한 거리 12예요.","12 ÷ 3 = 4예요.","1시간에 4 km만큼 이동한 셈이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#11','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',2,'sa','auto','씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"씨앗 50개를 심었더니 43개가 싹을 틔웠어요. 심은 씨앗 수에 대한 싹 튼 씨앗 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["86"],"explanation":["기준량은 50, 비교하는 양은 43이에요.","43 ÷ 50 × 100 = 86이에요.","그래서 86 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"우리 반 20명 가운데 15명이 이번 주에 도서관을 이용했어요. 전체 학생 수에 대한 이용한 학생 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량은 20, 비교하는 양은 15예요.","15 ÷ 20 × 100 = 75예요.","그래서 75 %예요."]},{"stem":"전체 25칸인 모눈에서 16칸을 색칠했어요. 전체 모눈 수에 대한 색칠한 모눈 수의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량은 25, 비교하는 양은 16이에요.","16 ÷ 25 × 100 = 64예요.","그래서 64 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#12','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',2,'sa','auto','비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u4-C5","difficulty":2,"kind":"sa","stem":"비율 ⟨13/20⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 5를 곱해요.","⟨13/20⟩ = ⟨65/100⟩예요.","그래서 ⟨13/20⟩은 65 %예요."],"mis":"M6-1-u4-X09","variant_rule":{"alt":[{"stem":"비율 ⟨16/25⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 4를 곱해요.","⟨16/25⟩ = ⟨64/100⟩예요.","그래서 ⟨16/25⟩은 64 %예요."]},{"stem":"비율 ⟨3/4⟩을 백분율로 나타내면 몇 %인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["기준량이 100인 비율로 바꾸어요 — 분모와 분자에 25를 곱해요.","⟨3/4⟩ = ⟨75/100⟩예요.","그래서 ⟨3/4⟩은 75 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#13','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'sa','auto','나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"나 치약은 원래 가격 5000원에서 1400원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","1400 ÷ 5000 × 100 = 28이에요.","할인율은 28 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"가 치약은 원래 가격 3000원에서 900원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","900 ÷ 3000 × 100 = 30이에요.","할인율은 30 %예요."]},{"stem":"공책은 원래 가격 2000원에서 300원을 할인해요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["할인율은 원래 가격에 대한 할인 금액의 비율이에요.","300 ÷ 2000 × 100 = 15예요.","할인율은 15 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#14','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'sa','auto','하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u4-C6","difficulty":2,"kind":"sa","stem":"하준은 설탕 24 g을 녹여 설탕물 150 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["기준량은 설탕물 150 g, 비교하는 양은 설탕 24 g이에요.","24 ÷ 150 × 100 = 16이에요.","설탕물의 진하기는 16 %예요."],"mis":"M6-1-u4-X05","variant_rule":{"alt":[{"stem":"지후는 설탕 210 g을 녹여 설탕물 750 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["기준량은 설탕물 750 g, 비교하는 양은 설탕 210 g이에요.","210 ÷ 750 × 100 = 28이에요.","설탕물의 진하기는 28 %예요."]},{"stem":"예은은 설탕 36 g을 녹여 설탕물 200 g을 만들었어요. 설탕물 양에 대한 설탕 양의 비율은 몇 %인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["기준량은 설탕물 200 g, 비교하는 양은 설탕 36 g이에요.","36 ÷ 200 × 100 = 18이에요.","설탕물의 진하기는 18 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#15','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',2,'ox','auto','할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.',ARRAY['M6-1-u4-X10']::text[],true,'{"seq":15,"concept":"M6-1-u4-C6","difficulty":2,"kind":"ox","stem":"할인율은 (할인된 가격) ÷ (원래 가격)으로 구해요.","answer":"X","reason_options":[{"t":"할인율은 원래 가격에 대한 할인 금액의 비율이기 때문에","correct":true},{"t":"할인된 가격이 비교하는 양이기 때문에","mis":"M6-1-u4-X10"}],"mis":"M6-1-u4-X10","explanation":["득표율·이자율·할인율·진하기는 모두 백분율로 나타내요.","먼저 기준량을 찾아요 — 전체 표, 맡긴 돈, 원래 가격, 설탕물 양.","금액이나 양이 아니라 백분율로 비교해요."],"variant_rule":{"alt":[{"stem":"3：4와 4：3은 같은 비예요.","answer":"X","reason_options":[{"t":"기준량이 4와 3으로 달라 서로 다른 비이기 때문에","correct":true},{"t":"두 비에 같은 수가 들어 있기 때문에","mis":"M6-1-u4-X02"}],"explanation":["두 양의 변하지 않는 관계를 기호 ：로 나타낸 것이 비예요.","：의 앞은 비교하는 양(전항), 뒤는 기준량(후항)이에요.","「○에 대한」 쪽이 기준량이에요."]},{"stem":"비율은 언제나 1보다 작아요.","answer":"X","reason_options":[{"t":"12：5의 비율 2.4처럼 비교하는 양이 더 크면 1보다 크기 때문에","correct":true},{"t":"비율은 전체의 일부만 나타내기 때문에","mis":"M6-1-u4-X06"}],"explanation":["기준량에 대한 비교하는 양의 크기를 비율이라고 해요.","비율 = (비교하는 양) ÷ (기준량) — 분수로도 소수로도 나타내요.","기준량이 달라도 관계가 같으면 비율이 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#16','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',2,'mc','auto','신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X15','M6-1-u4-X13']::text[],true,'{"seq":16,"concept":"M6-1-u4-C7","difficulty":2,"kind":"mc","stem":"신재생 에너지 510000 kWh 가운데 30 %가 풍력 에너지예요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"15300 kWh","mis":"M6-1-u4-X15"},{"t":"17000 kWh","mis":"M6-1-u4-X13"},{"t":"1530000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 510000을 100칸으로 보면 한 칸은 510000 ÷ 100 = 5100이에요.","30 %는 30칸이라 5100 × 30 = 153000이에요.","답은 153000 kWh예요."],"variant_rule":{"alt":[{"stem":"행복 지역의 전체 발전량은 3400000 kWh이고 그중 15 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"510000 kWh","correct":true},{"t":"51000 kWh","mis":"M6-1-u4-X15"},{"t":"5100000 kWh","mis":"M6-1-u4-X15"},{"t":"2890000 kWh","mis":"M6-1-u4-X16"}],"explanation":["전체 3400000을 100칸으로 보면 한 칸은 3400000 ÷ 100 = 34000이에요.","15 %는 15칸이라 34000 × 15 = 510000이에요.","답은 510000 kWh예요."]},{"stem":"푸른 지역의 전체 발전량은 2500000 kWh이고 그중 20 %가 신재생 에너지예요. 신재생 에너지 발전량은 몇 kWh인가요?","options":[{"t":"500000 kWh","correct":true},{"t":"50000 kWh","mis":"M6-1-u4-X15"},{"t":"125000 kWh","mis":"M6-1-u4-X13"},{"t":"5000000 kWh","mis":"M6-1-u4-X15"}],"explanation":["전체 2500000을 100칸으로 보면 한 칸은 2500000 ÷ 100 = 25000이에요.","20 %는 20칸이라 25000 × 20 = 500000이에요.","답은 500000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#17','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',3,'mc','auto','사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":17,"concept":"M6-1-u4-C4","difficulty":3,"kind":"mc","stem":"사 마을은 넓이 8 km²에 12000명, 아 마을은 넓이 5 km²에 8000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"아 마을","correct":true},{"t":"사 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","사 12000 ÷ 8 = 1500, 아 8000 ÷ 5 = 1600이에요.","비율이 큰 아 마을이 더 빽빽해요."],"variant_rule":{"alt":[{"stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"가 마을","correct":true},{"t":"나 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","가 6000 ÷ 2 = 3000, 나 7500 ÷ 3 = 2500이에요.","비율이 큰 가 마을이 더 빽빽해요."]},{"stem":"다 마을은 넓이 4 km²에 10000명, 라 마을은 넓이 5 km²에 11000명이 살아요. 사람이 더 빽빽하게 사는 곳은 어느 마을인가요?","options":[{"t":"다 마을","correct":true},{"t":"라 마을","mis":"M6-1-u4-X11"},{"t":"두 마을이 같아요","mis":"M6-1-u4-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["넓이가 다르니 인구가 아니라 넓이에 대한 인구의 비율로 비교해요.","다 10000 ÷ 4 = 2500, 라 11000 ÷ 5 = 2200이에요.","비율이 큰 다 마을이 더 빽빽해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#18','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',3,'mc','auto','지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":18,"concept":"M6-1-u4-C5","difficulty":3,"kind":"mc","stem":"지민은 공을 40번 차서 30번 넣었고, 태오는 25번 차서 20번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"지민","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","지민 30 ÷ 40 × 100 = 75, 태오 20 ÷ 25 × 100 = 80이에요.","지민 75 %, 태오 80 % — 태오가 더 잘 넣었어요."],"variant_rule":{"alt":[{"stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 12 ÷ 25 × 100 = 48, 동생 10 ÷ 20 × 100 = 50이에요.","나 48 %, 동생 50 % — 동생이 더 잘 넣었어요."]},{"stem":"나는 공을 40번 차서 26번 넣었고, 동생은 20번 차서 14번 넣었어요. 찬 횟수에 대한 넣은 횟수의 비율이 더 큰 사람은 누구인가요?","options":[{"t":"동생","correct":true},{"t":"나","mis":"M6-1-u4-X11"},{"t":"두 사람이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["찬 횟수가 다르니 넣은 횟수가 아니라 백분율로 비교해요.","나 26 ÷ 40 × 100 = 65, 동생 14 ÷ 20 × 100 = 70이에요.","나 65 %, 동생 70 % — 동생이 더 잘 넣었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#19','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',3,'sa','auto','우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u4-C6","difficulty":3,"kind":"sa","stem":"우산은 원래 가격이 15000원인데 12000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 15000 − 12000 = 3000이에요.","3000 ÷ 15000 × 100 = 20이에요.","할인율은 20 %예요."],"mis":"M6-1-u4-X10","variant_rule":{"alt":[{"stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","할인율은 25 %예요."]},{"stem":"가방은 원래 가격이 25000원인데 20000원에 팔아요. 할인율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["할인 금액은 원래 가격에서 할인된 가격을 뺀 25000 − 20000 = 5000이에요.","5000 ÷ 25000 × 100 = 20이에요.","할인율은 20 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#20','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C1',3,'sa','auto','가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M6-1-u4-C1","difficulty":3,"kind":"sa","stem":"가로 8 cm, 세로 6 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 6 = 1.5배가 되었어요.","가로도 8 × 1.5 = 12 (cm)예요."],"mis":"M6-1-u4-X03","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 2 cm인 직사각형을 모양 그대로 키웠더니 세로가 6 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 6 ÷ 2 = 3배가 되었어요.","가로도 5 × 3 = 15 (cm)예요."]},{"stem":"가로 4 cm, 세로 3 cm인 직사각형을 모양 그대로 키웠더니 세로가 9 cm가 되었어요. 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["모양이 그대로이려면 가로와 세로가 같은 배로 늘어야 해요.","세로는 9 ÷ 3 = 3배가 되었어요.","가로도 4 × 3 = 12 (cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#21','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C6',3,'error','auto','운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u4-X10','M6-1-u4-X16']::text[],true,'{"seq":21,"concept":"M6-1-u4-C6","difficulty":3,"kind":"error","stem":"운동화는 원래 가격이 40000원인데 30000원에 팔아요. 할인율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「30000 ÷ 40000 × 100 = 75니 75 %야.」","correct":true,"mis_target":"M6-1-u4-X10"},{"t":"라온 — 「할인 금액은 10000원이야.」","mis":"M6-1-u4-X16"},{"t":"예준 — 「할인율은 25 %야.」","mis":"M6-1-u4-X16"}],"explanation":["할인 금액은 40000 − 30000 = 10000이에요.","10000 ÷ 40000 × 100 = 25예요.","여울은 할인된 가격으로 계산했어요."],"variant_rule":{"alt":[{"stem":"바닷물 150 g을 증발시켜 소금 6 g을 얻었어요. 바닷물 양에 대한 소금 양의 비는 무엇일까요? 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「150：6이야.」","correct":true,"mis_target":"M6-1-u4-X01"},{"t":"이현 — 「기준량은 바닷물 양이야.」","mis":"M6-1-u4-X16"},{"t":"서아 — 「비는 6：150이야.」","mis":"M6-1-u4-X16"}],"explanation":["기준량은 바닷물 양이에요.","비는 (비교하는 양)：(기준량) 차례라 6：150이에요.","준희는 기준량과 비교하는 양을 바꾸어 썼어요."]},{"stem":"비 9：50의 비율을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「50 ÷ 9 = ⟨50/9⟩이야.」","correct":true,"mis_target":"M6-1-u4-X05"},{"t":"수아 — 「기준량은 50이야.」","mis":"M6-1-u4-X16"},{"t":"도윤 — 「비율은 0.18이야.」","mis":"M6-1-u4-X16"}],"explanation":["비율 = (비교하는 양) ÷ (기준량)이에요.","9 ÷ 50 = 0.18이에요.","서호는 기준량을 비교하는 양으로 나누었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#22','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',3,'mc','auto','전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?',ARRAY['M6-1-u4-X14','M6-1-u4-X16']::text[],true,'{"seq":22,"concept":"M6-1-u4-C7","difficulty":3,"kind":"mc","stem":"전체 발전량 5000000 kWh의 12 %가 신재생 에너지이고, 신재생 에너지의 25 %가 지열이에요. 지열 발전량은 몇 kWh인가요?","options":[{"t":"150000 kWh","correct":true},{"t":"1250000 kWh","mis":"M6-1-u4-X14"},{"t":"600000 kWh","mis":"M6-1-u4-X16"},{"t":"1850000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 5000000 × 12 ÷ 100 = 600000이에요.","기준량이 600000으로 바뀌어요 — 600000 × 25 ÷ 100 = 150000이에요.","답은 150000 kWh예요."],"variant_rule":{"alt":[{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 48 %가 태양광이에요. 태양광 발전량은 몇 kWh인가요?","options":[{"t":"244800 kWh","correct":true},{"t":"1632000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"2142000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 48 ÷ 100 = 244800이에요.","답은 244800 kWh예요."]},{"stem":"전체 발전량 3400000 kWh의 15 %가 신재생 에너지이고, 신재생 에너지의 30 %가 풍력이에요. 풍력 발전량은 몇 kWh인가요?","options":[{"t":"153000 kWh","correct":true},{"t":"1020000 kWh","mis":"M6-1-u4-X14"},{"t":"510000 kWh","mis":"M6-1-u4-X16"},{"t":"1530000 kWh","mis":"M6-1-u4-X14"}],"explanation":["먼저 3400000 × 15 ÷ 100 = 510000이에요.","기준량이 510000으로 바뀌어요 — 510000 × 30 ÷ 100 = 153000이에요.","답은 153000 kWh예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#23','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C7',4,'mc','auto','사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?',ARRAY['M6-1-u4-X11','M6-1-u4-X15']::text[],true,'{"seq":23,"concept":"M6-1-u4-C7","difficulty":4,"kind":"mc","stem":"사 지역은 전체 발전량 6000000 kWh 가운데 10 %, 아 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"사 지역","correct":true},{"t":"아 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","사 6000000 × 10 ÷ 100 = 600000, 아 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 사 지역이에요."],"variant_rule":{"alt":[{"stem":"가 지역은 전체 발전량 2000000 kWh 가운데 20 %, 나 지역은 전체 발전량 3000000 kWh 가운데 15 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"나 지역","correct":true},{"t":"가 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","가 2000000 × 20 ÷ 100 = 400000, 나 3000000 × 15 ÷ 100 = 450000이에요.","발전량이 더 많은 곳은 나 지역이에요."]},{"stem":"다 지역은 전체 발전량 5000000 kWh 가운데 12 %, 라 지역은 전체 발전량 4000000 kWh 가운데 14 %가 신재생 에너지예요. 신재생 에너지 발전량이 더 많은 지역은 어느 곳인가요?","options":[{"t":"다 지역","correct":true},{"t":"라 지역","mis":"M6-1-u4-X11"},{"t":"두 지역이 같아요","mis":"M6-1-u4-X15"},{"t":"알 수 없어요","mis":"M6-1-u4-X11"}],"explanation":["기준량(전체 발전량)이 다르니 백분율만으로는 양을 비교할 수 없어요.","다 5000000 × 12 ÷ 100 = 600000, 라 4000000 × 14 ÷ 100 = 560000이에요.","발전량이 더 많은 곳은 다 지역이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#24','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C5',4,'essay','teacher','나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u4-C5","difficulty":4,"kind":"essay","stem":"나는 공을 25번 차서 12번 넣었고, 동생은 20번 차서 10번 넣었어요. 넣은 비율을 백분율로 구하고, 누가 더 잘 넣었는지 까닭과 함께 설명해 보세요.","answer_guide":{"answer":"예: 찬 횟수를 100으로 맞추면 나는 25 × 4 = 100번 찼다면 12 × 4 = 48번, 동생은 20 × 5 = 100번 찼다면 10 × 5 = 50번 넣은 셈이다. 나는 48 %, 동생은 50 %이므로 동생이 더 잘 넣었다. 넣은 횟수는 내가 많지만 찬 횟수가 다르므로 백분율로 비교해야 한다.","scoring_points":["나 48 %·동생 50 %를 구했는가","동생이 더 잘 넣었다고 답했는가","찬 횟수가 달라 백분율로 비교해야 한다고 썼는가"]},"explanation":["나는 48 %, 동생은 50 %예요.","동생이 더 잘 넣었어요.","찬 횟수가 다르면 백분율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u4_review_d#25','math',6,1,'u4','','g6_1_math_u4_review_d','unit_review','M6-1-u4-C4',4,'essay','teacher','가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u4-C4","difficulty":4,"kind":"essay","stem":"가 마을은 넓이 2 km²에 6000명, 나 마을은 넓이 3 km²에 7500명이 살아요. 「나 마을이 사람이 더 많으니 더 빽빽하다」는 말이 맞는지 넓이에 대한 인구의 비율을 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 마을은 6000 ÷ 2 = 3000, 나 마을은 7500 ÷ 3 = 2500이다. 1 km²에 사는 사람이 가 마을이 더 많으므로 가 마을이 더 빽빽하다. 넓이가 다르면 인구 수가 아니라 넓이에 대한 인구의 비율로 비교해야 한다.","scoring_points":["3000과 2500을 구했는가","가 마을이 더 빽빽하다고 답했는가","기준(넓이)이 다르면 비율로 비교해야 한다고 썼는가"]},"explanation":["가 3000, 나 2500이에요.","가 마을이 더 빽빽해요.","넓이가 다르면 비율로 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C1','math',6,1,'u5',2,'비율그래프 알기 — 띠그래프와 원그래프는 전체를 100 %로 보고 각 부분의 비율을 띠의 길이·원의 넓이로 나타내며, 같은 %라도 전체가 다르면 실제 수가 다르다는 것을 알기',ARRAY['6수05-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C2','math',6,1,'u5',2,'띠그래프와 원그래프 읽기 — 가장 큰·작은 항목, 한 항목의 백분율, 두 항목의 합, 몇 배인지, 모르는 칸(100 − 나머지), 눈금 한 칸의 크기를 읽고, 전체 수 × 백분율로 항목의 수를 구하기',ARRAY['6수05-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C3','math',6,1,'u5',3,'띠그래프로 나타내기 — 각 항목의 백분율(항목의 수 ÷ 전체 × 100)을 구하고, 합이 100 %인지 확인한 뒤 백분율만큼 띠의 길이를 나누어 내용·백분율·제목을 쓰기',ARRAY['6수05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C4','math',6,1,'u5',4,'원그래프로 나타내기 — 눈금이 20칸(한 칸 5 %)인 원에 원의 중심에서 눈금까지 선을 그어 백분율만큼 나누고, 반올림해 합이 99 %나 101 %가 되면 가장 큰 항목을 고쳐 100 %로 맞추기',ARRAY['6수05-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C5','math',6,1,'u5',5,'자료를 모아 나타내고 해석하기 — 모은 자료를 표로 정리해 백분율을 구하고 띠그래프·원그래프로 나타낸 뒤, 그래프를 보고 가장 많은 것·몇 배·두 항목의 합 같은 사실을 찾아 해석하기',ARRAY['6수05-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C6','math',6,1,'u5',6,'여러 가지 그래프 비교하기 — 수는 막대그래프, 시간에 따른 변화는 꺾은선그래프, 전체에 대한 비율은 띠·원그래프가 잘 보여 주므로 목적을 먼저 정해 고르고, 비율그래프만으로는 실제 수를 알 수 없음을 알기',ARRAY['6수05-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C7','math',6,1,'u5',7,'그래프로 문제 해결하기 — 문제 제기 → 자료 수집 → 자료 분석(표·그래프) → 결과 해석의 네 단계로 탐구 문제의 답을 찾고, 해석한 결과를 실천으로 잇기',ARRAY['6수05-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u5-C8','math',6,1,'u5',8,'그래프를 검토하고 고치기 — 백분율의 합이 100 %인지, 길이·넓이가 백분율과 맞는지, 내용·백분율·제목이 있는지 확인해 잘못된 값을 찾아 바르게 고쳐 다시 나타내기',ARRAY['6수05-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X01','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C5','M6-1-u5-C6']::text[],'같은 %이면 실제 수도 같다고 본다(전체 30일의 30 %와 60일의 30 %를 같은 날수로)','전체가 다르면 수도 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X02','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C5','M6-1-u5-C6']::text[],'비율그래프만 보고 실제 수를 알 수 있다고 보거나, 비율이 늘었으니 수도 늘었다고 단정한다','수를 알려면 전체를 알아야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X03','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C8']::text[],'백분율의 합이 100 %가 아니어도 된다고 보거나, 모르는 칸을 구할 때 100에서 빼지 않는다','부분을 모두 더하면 100 %') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X04','math',6,'u5',ARRAY['M6-1-u5-C3','M6-1-u5-C5']::text[],'백분율을 구할 때 100을 곱하지 않거나 10을 곱하고, 전체 ÷ 항목의 수로 거꾸로 나눈다','항목의 수 ÷ 전체 × 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X05','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C4']::text[],'눈금 한 칸의 크기를 칸 수로 나누지 않고 1 %·10 %로 본다(20칸 원의 한 칸을 1 %로)','100 ÷ 칸 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X06','math',6,'u5',ARRAY['M6-1-u5-C4']::text[],'원그래프의 경계선을 원의 중심이 아닌 곳(둘레·아무 곳)에서 긋는다','중심에서 눈금까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X07','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2']::text[],'칸의 길이·넓이 대신 놓인 차례·위치로 크기를 판단한다(맨 앞 칸이 가장 크다고)','길이·넓이가 곧 비율') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X08','math',6,'u5',ARRAY['M6-1-u5-C4','M6-1-u5-C5']::text[],'반올림해 합이 99 %·101 %가 되었을 때 그대로 두거나, 모든 항목·가장 작은 항목을 고친다','가장 큰 항목을 고쳐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X09','math',6,'u5',ARRAY['M6-1-u5-C2','M6-1-u5-C5']::text[],'몇 배인지 물었는데 백분율의 차를 구한다','「몇 배」는 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X10','math',6,'u5',ARRAY['M6-1-u5-C6']::text[],'목적에 맞지 않는 그래프를 고른다(시간에 따른 변화를 원그래프로, 전체에 대한 비율을 꺾은선그래프로)','변화는 꺾은선, 비율은 띠·원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X11','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C6']::text[],'막대그래프·그림그래프로도 전체에 대한 비율이 한눈에 보인다고 보거나, 띠·원그래프로 각 항목의 정확한 수를 비교하려 한다','수는 막대, 비율은 띠·원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X12','math',6,'u5',ARRAY['M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5']::text[],'그래프로 나타내는 차례를 바꾼다(백분율을 구하기 전에 띠를 나누거나 제목·색칠부터)','백분율 → 합 100 → 나누기 → 쓰기 → 제목') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X13','math',6,'u5',ARRAY['M6-1-u5-C7']::text[],'통계적 문제 해결 단계를 바꾸거나 섞는다(문제를 정하기 전에 자료부터 모으기, 표로 정리하기를 결과 해석으로)','제기 → 수집 → 분석 → 해석') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X14','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C5']::text[],'항목의 수를 그대로 %로 읽거나, 백분율을 그대로 사람 수로 답한다(전체 20명 중 6명을 6 %로)','전체가 100이 아니면 바꾸어야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X15','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5','M6-1-u5-C6','M6-1-u5-C7','M6-1-u5-C8']::text[],'백분율·곱셈·나눗셈 셈을 잘못 한다','거꾸로 셈으로 검산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u5-X16','math',6,'u5',ARRAY['M6-1-u5-C1','M6-1-u5-C2','M6-1-u5-C3','M6-1-u5-C4','M6-1-u5-C5','M6-1-u5-C6','M6-1-u5-C7','M6-1-u5-C8']::text[],'묻는 말을 놓친다 — 가장 큰↔작은, 나머지, 알 수 있는↔알 수 없는, 옳은↔옳지 않은','물음에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#1','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'mc','auto','띠그래프에서 한 칸의 길이가 나타내는 것은 무엇인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X02','M6-1-u5-X16']::text[],true,'{"seq":1,"concept":"M6-1-u5-C1","difficulty":1,"kind":"mc","stem":"띠그래프에서 한 칸의 길이가 나타내는 것은 무엇인가요?","options":[{"t":"그 항목이 전체에서 차지하는 비율","correct":true},{"t":"그 항목의 실제 수","mis":"M6-1-u5-X14"},{"t":"조사한 전체 수","mis":"M6-1-u5-X02"},{"t":"조사한 항목의 개수","mis":"M6-1-u5-X16"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."],"variant_rule":{"alt":[{"stem":"원그래프에서 한 조각의 넓이가 나타내는 것은 무엇인가요?","options":[{"t":"그 항목이 전체에서 차지하는 비율","correct":true},{"t":"그 항목의 실제 수","mis":"M6-1-u5-X14"},{"t":"조사한 전체 수","mis":"M6-1-u5-X02"},{"t":"원을 그린 차례","mis":"M6-1-u5-X07"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."]},{"stem":"띠그래프에서 다른 칸보다 더 긴 칸은 무엇을 뜻하나요?","options":[{"t":"전체에서 차지하는 비율이 더 큰 항목","correct":true},{"t":"맨 앞에 놓인 항목","mis":"M6-1-u5-X07"},{"t":"조사를 먼저 한 항목","mis":"M6-1-u5-X16"},{"t":"실제 수가 언제나 100보다 큰 항목","mis":"M6-1-u5-X14"}],"explanation":["띠그래프와 원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 각 부분의 비율을 보여 줘요.","실제 수가 아니라 비율을 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#2','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'mc','auto','전체에 대한 부분의 비율을 한눈에 알아보기에 알맞은 그래프는 어느 것인가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C1","difficulty":1,"kind":"mc","stem":"전체에 대한 부분의 비율을 한눈에 알아보기에 알맞은 그래프는 어느 것인가요?","options":[{"t":"띠그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."],"variant_rule":{"alt":[{"stem":"각 항목이 전체에서 차지하는 비율을 원 모양으로 나타낸 그래프는 어느 것인가요?","options":[{"t":"원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."]},{"stem":"좋아하는 과일별 사람 수를 막대그래프로 나타냈어요. 막대그래프에서 한눈에 잘 보이지 않는 것은 어느 것인가요?","options":[{"t":"각 과일이 전체에서 차지하는 비율","correct":true},{"t":"과일별 사람 수","mis":"M6-1-u5-X11"},{"t":"가장 많은 사람이 좋아하는 과일","mis":"M6-1-u5-X11"},{"t":"두 과일의 사람 수 차","mis":"M6-1-u5-X11"}],"explanation":["막대그래프는 각 항목의 수를 잘 보여 줘요.","띠그래프·원그래프는 전체를 100 %로 보고 부분의 비율을 보여 줘요.","비율을 한눈에 보려면 띠그래프나 원그래프가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#3','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',1,'mc','auto','좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#4','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',1,'ox','auto','띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"원그래프만 보고는 각 항목의 실제 수를 알 수 없어요.","answer":"O","reason_options":[{"t":"전체 수를 알아야 실제 수를 구할 수 있기 때문에","correct":true},{"t":"원그래프에는 수가 적혀 있지 않아 비율도 모르기 때문에","mis":"M6-1-u5-X02"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#5','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 사과는 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 사과는 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","사과는 30 %예요.","답은 30이에요."],"mis":"M6-1-u5-X16","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 나쁨은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["띠그래프의 칸마다 항목과 백분율이 적혀 있어요.","나쁨은 30 %예요.","답은 30이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 로봇은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","로봇은 30 %예요.","답은 30이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#6','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#7','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C2',2,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#8','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',2,'sa','auto','전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 30일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","30 × 30 % = 9예요.","나쁨은 9일이에요."]},{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#9','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',2,'ox','auto','두 반 모두 30 %가 축구를 좋아하면 축구를 좋아하는 학생 수도 같아요.',ARRAY['M6-1-u5-X01']::text[],true,'{"seq":9,"concept":"M6-1-u5-C1","difficulty":2,"kind":"ox","stem":"두 반 모두 30 %가 축구를 좋아하면 축구를 좋아하는 학생 수도 같아요.","answer":"X","reason_options":[{"t":"두 반의 전체 학생 수가 다르면 수도 다르기 때문에","correct":true},{"t":"같은 %이면 언제나 같은 수이기 때문에","mis":"M6-1-u5-X01"}],"mis":"M6-1-u5-X01","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"막대그래프에서도 전체에 대한 비율이 한눈에 잘 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 각 항목의 수를 보여 주는 그래프이기 때문에","correct":true},{"t":"막대가 길수록 비율도 바로 읽히기 때문에","mis":"M6-1-u5-X11"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"띠그래프에서 맨 앞에 놓인 칸이 언제나 가장 큰 항목이에요.","answer":"X","reason_options":[{"t":"크기는 놓인 차례가 아니라 칸의 길이로 알기 때문에","correct":true},{"t":"가장 중요한 항목을 맨 앞에 두기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_basic#10','math',6,1,'u5','L02','g6_1_math_u5_L02_basic','lesson_basic','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":10,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#1','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈는데 좋음의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 30 + 10 = 75예요.","100 − 75 = 25예요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태","hide":[0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#2','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',2,'mc','auto','「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":2,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]},{"stem":"「이번 달 미세 먼지가 나쁨인 날이 40 %였다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"이번 달 날수가 30일인지 31일인지","correct":true},{"t":"나쁨인 날의 비율","mis":"M6-1-u5-X16"},{"t":"나쁨이 아닌 날의 비율","mis":"M6-1-u5-X16"},{"t":"나쁨인 날이 절반보다 적었다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「이번 달 날수가 30일인지 31일인지」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#3','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#4','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#5','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',3,'error','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C1","difficulty":3,"kind":"error","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"도윤 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","하린은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"예준 — 「가 도시의 나쁨인 날은 5일이야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「나 도시의 나쁨인 날은 10일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 20 × 25 % = 5(일)이에요.","나 도시는 40 × 25 % = 10(일)이에요.","수아는 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"유진 — 「가 도시의 나쁨인 날은 6일이야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 20 % = 6(일)이에요.","나 도시는 90 × 20 % = 18(일)이에요.","가온은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#6','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'mc','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#7','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',3,'error','auto','미세 먼지 상태 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16']::text[],true,'{"seq":7,"concept":"M6-1-u5-C2","difficulty":3,"kind":"error","stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「좋음이 맨 앞에 있으니까 가장 커.」","correct":true,"mis_target":"M6-1-u5-X07"},{"t":"예준 — 「가장 큰 항목은 보통이야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「보통과 나쁨 합하면 65 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 보통 35 %이고 가장 작은 항목은 매우 나쁨 10 %예요.","35 % + 30 % = 65 %예요.","수아가 잘못 말했어요 — 크기는 칸의 길이로 견주어요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「가장 작은 항목은 복숭아야.」","correct":true,"mis_target":"M6-1-u5-X16"},{"t":"유진 — 「가장 큰 항목은 복숭아야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「복숭아와 사과 합하면 70 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 복숭아 40 %이고 가장 작은 항목은 배 10 %예요.","40 % + 30 % = 70 %예요.","가온이 잘못 말했어요 — 크기는 칸의 넓이로 견주어요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"좋아하는 계절 조사를 띠그래프로 나타냈어요. 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「가장 작은 항목은 봄이야.」","correct":true,"mis_target":"M6-1-u5-X16"},{"t":"시우 — 「가장 큰 항목은 봄이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「봄과 가을 합하면 60 %야.」","mis":"M6-1-u5-X16"}],"explanation":["가장 큰 항목은 봄 32 %이고 가장 작은 항목은 겨울 16 %예요.","32 % + 28 % = 60 %예요.","여울이 잘못 말했어요 — 크기는 칸의 길이로 견주어요."],"asset":{"type":"pgr","kind":"band","items":[["봄",32],["가을",28],["여름",24],["겨울",16]],"title":"좋아하는 계절"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#8','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',4,'sa','auto','나쁨인 날은 18일이고, 이것은 전체의 30 %예요. 전체는 몇 일인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C1","difficulty":4,"kind":"sa","stem":"나쁨인 날은 18일이고, 이것은 전체의 30 %예요. 전체는 몇 일인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["전체 × 30 % = 18이에요.","1 %는 18 ÷ 30 = 0.6이고 전체 100 %는 그 100배예요.","0.6 × 100 = 60 — 전체는 60일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"축구를 좋아하는 학생은 9명이고, 이것은 전체의 45 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["전체 × 45 % = 9예요.","1 %는 9 ÷ 45 = 0.2이고 전체 100 %는 그 100배예요.","0.2 × 100 = 20 — 전체는 20명이에요."]},{"stem":"가상 현실을 고른 학생은 12명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["전체 × 40 % = 12예요.","1 %는 12 ÷ 40 = 0.3이고 전체 100 %는 그 100배예요.","0.3 × 100 = 30 — 전체는 30명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#9','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C2',4,'sa','auto','소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. 종묘는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":4,"kind":"sa","stem":"소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. 종묘는 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["종묘의 백분율은 100 − (30 + 25 + 20 + 10) = 15예요.","20 × 15 % = 3이에요.","종묘는 3명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도의 백분율은 100 − (40 + 30 + 10) = 20이에요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"기르고 싶은 동물 조사(전체 25명)를 띠그래프로 나타냈는데 물고기의 백분율이 지워졌어요. 물고기는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["물고기의 백분율은 100 − (40 + 28 + 12) = 20이에요.","25 × 20 % = 5예요.","물고기는 5명이에요."],"asset":{"type":"pgr","kind":"band","items":[["강아지",40],["고양이",28],["물고기",20],["기타",12]],"title":"기르고 싶은 동물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L02_challenge#10','math',6,1,'u5','L02','g6_1_math_u5_L02_challenge','lesson_challenge','M6-1-u5-C1',4,'essay','teacher','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C1","difficulty":4,"kind":"essay","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 도시는 30 × 30 % = 9이므로 9일, 나 도시는 60 × 30 % = 18이므로 18일이다. 비율은 같아도 전체 날수가 다르므로 나쁨인 날수는 나 도시가 더 많다.","scoring_points":["9일과 18일을 구했는가","나 도시가 더 많다고 답했는가","전체가 다르면 같은 %라도 수가 다르다고 설명했는가"]},"explanation":["가 도시 9일, 나 도시 18일이에요.","나 도시가 더 많아요.","전체가 다르면 같은 %라도 수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#1','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'mc','auto','띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 가장 마지막에 할 일은 무엇인가요?","options":[{"t":"제목 쓰기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율의 합이 100 %인지 확인하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「제목 쓰기」는 ⑤ 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"띠그래프로 나타낼 때 각 항목의 백분율을 구한 바로 다음에 할 일은 무엇인가요?","options":[{"t":"백분율의 합이 100 %인지 확인하기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「백분율의 합이 100 %인지 확인하기」는 ② 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#2','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 첨성대는 5명, 전체는 20명이에요. 첨성대의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","5 ÷ 20 × 100 = 25예요.","첨성대는 25 %예요."]},{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#3','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'mc','auto','완성한 띠그래프에 빠뜨리면 안 되는 것은 어느 것인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"완성한 띠그래프에 빠뜨리면 안 되는 것은 어느 것인가요?","options":[{"t":"항목의 내용과 백분율, 제목","correct":true},{"t":"조사한 날짜와 요일","mis":"M6-1-u5-X12"},{"t":"그린 사람의 이름","mis":"M6-1-u5-X12"},{"t":"칠한 색의 이름","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「항목의 내용과 백분율, 제목」이에요."],"variant_rule":{"alt":[{"stem":"띠그래프에서 각 칸의 길이를 정하는 것은 무엇인가요?","options":[{"t":"그 항목의 백분율","correct":true},{"t":"그 항목을 조사한 차례","mis":"M6-1-u5-X07"},{"t":"그 항목 이름의 글자 수","mis":"M6-1-u5-X07"},{"t":"그 항목의 실제 수 그대로","mis":"M6-1-u5-X14"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「그 항목의 백분율」이에요."]},{"stem":"띠그래프의 백분율 합이 100 %인지 확인하는 까닭은 무엇인가요?","options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많아 보이게 하려고","mis":"M6-1-u5-X16"},{"t":"띠를 예쁘게 칠하려고","mis":"M6-1-u5-X12"},{"t":"제목을 정하려고","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 띠 전체를 100 %로 보고 백분율만큼 길이를 나눠요.","나눈 칸에는 내용과 백분율을 쓰고, 마지막에 제목을 써요.","그래서 답은 「띠 전체가 전체(100 %)를 나타내기 때문에」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#4','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',1,'ox','auto','띠그래프를 그릴 때는 각 항목의 백분율부터 구해요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":4,"concept":"M6-1-u5-C3","difficulty":1,"kind":"ox","stem":"띠그래프를 그릴 때는 각 항목의 백분율부터 구해요.","answer":"O","reason_options":[{"t":"백분율을 알아야 띠를 얼마만큼 나눌지 알기 때문에","correct":true},{"t":"제목을 먼저 써야 하기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"띠그래프 각 칸의 백분율을 모두 더하면 100 %가 되어야 해요.","answer":"O","reason_options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"칸의 개수가 언제나 100개이기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프에는 제목을 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"무엇을 조사한 그래프인지 알 수 있게 제목을 써야 하기 때문에","correct":true},{"t":"칸에 내용이 있으면 제목은 필요 없기 때문에","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#5','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#6','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'mc','auto','소개하고 싶은 문화유산 조사에서 수원 화성은 4명, 전체는 20명이에요. 수원 화성의 백분율로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X04','M6-1-u5-X16']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":2,"kind":"mc","stem":"소개하고 싶은 문화유산 조사에서 수원 화성은 4명, 전체는 20명이에요. 수원 화성의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"20 %","correct":true},{"t":"4 %","mis":"M6-1-u5-X14"},{"t":"2 %","mis":"M6-1-u5-X04"},{"t":"80 %","mis":"M6-1-u5-X16"}],"explanation":["전체 20명 가운데 4명이에요.","4 ÷ 20 × 100 = 20이에요.","그래서 20 %예요."],"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 피구는 6명, 전체는 20명이에요. 피구의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"30 %","correct":true},{"t":"6 %","mis":"M6-1-u5-X14"},{"t":"3 %","mis":"M6-1-u5-X04"},{"t":"70 %","mis":"M6-1-u5-X16"}],"explanation":["전체 20명 가운데 6명이에요.","6 ÷ 20 × 100 = 30이에요.","그래서 30 %예요."]},{"stem":"기르고 싶은 동물 조사에서 고양이는 7명, 전체는 25명이에요. 고양이의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"28 %","correct":true},{"t":"7 %","mis":"M6-1-u5-X14"},{"t":"72 %","mis":"M6-1-u5-X16"},{"t":"38 %","mis":"M6-1-u5-X15"}],"explanation":["전체 25명 가운데 7명이에요.","7 ÷ 25 × 100 = 28이에요.","그래서 28 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#7','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','소개하고 싶은 문화유산 조사(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 종묘의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 종묘의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘는 3명이에요.","3 ÷ 20 × 100 = 15예요.","?는 15예요."],"mis":"M6-1-u5-X04","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사(축구 9명, 피구 6명, 야구 3명, 배구 2명, 전체 20명)를 띠그래프로 나타내고 있어요. ?에 알맞은 야구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["야구는 3명이에요.","3 ÷ 20 × 100 = 15예요.","?는 15예요."],"asset":{"type":"pgr","kind":"band","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동","hide":[2]}},{"stem":"기르고 싶은 동물 조사(강아지 10명, 고양이 7명, 물고기 5명, 기타 3명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 물고기의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["물고기는 5명이에요.","5 ÷ 25 × 100 = 20이에요.","?는 20이에요."],"asset":{"type":"pgr","kind":"band","items":[["강아지",40],["고양이",28],["물고기",20],["기타",12]],"title":"기르고 싶은 동물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#8','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'sa','auto','길이가 20 cm인 띠를 전체로 하여 띠그래프를 그려요. 30 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"길이가 20 cm인 띠를 전체로 하여 띠그래프를 그려요. 30 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["띠 전체 20 cm가 100 %예요.","20 × 30 % = 6이에요.","6 cm로 나누어요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"길이가 10 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["띠 전체 10 cm가 100 %예요.","10 × 40 % = 4예요.","4 cm로 나누어요."]},{"stem":"길이가 40 cm인 띠를 전체로 하여 띠그래프를 그려요. 25 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠 전체 40 cm가 100 %예요.","40 × 25 % = 10이에요.","10 cm로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#9','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',2,'ox','auto','전체 20명 가운데 6명이면 백분율은 6 %예요.',ARRAY['M6-1-u5-X14']::text[],true,'{"seq":9,"concept":"M6-1-u5-C3","difficulty":2,"kind":"ox","stem":"전체 20명 가운데 6명이면 백분율은 6 %예요.","answer":"X","reason_options":[{"t":"6 ÷ 20 × 100 = 30이라 30 %이기 때문에","correct":true},{"t":"항목의 수가 곧 백분율이기 때문에","mis":"M6-1-u5-X14"}],"mis":"M6-1-u5-X14","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"길이 10 cm인 띠에서 30 %는 3 cm예요.","answer":"O","reason_options":[{"t":"10 × 30 % = 3이기 때문에","correct":true},{"t":"30을 10으로 나누기 때문에","mis":"M6-1-u5-X15"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프에서 백분율이 큰 항목일수록 칸이 짧아요.","answer":"X","reason_options":[{"t":"백분율이 클수록 칸이 길기 때문에","correct":true},{"t":"큰 항목은 뒤에 두기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_basic#10','math',6,1,'u5','L03','g6_1_math_u5_L03_basic','lesson_basic','M6-1-u5-C3',3,'error','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C3","difficulty":3,"kind":"error","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 피구는 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「피구는 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"예준 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","수아는 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「강아지는 10명이니까 10 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"유진 — 「10 ÷ 25 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","10 ÷ 25 × 100 = 40이에요.","가온은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#1','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',2,'mc','auto','띠그래프로 나타낼 때 띠를 백분율만큼 나눈 바로 다음에 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C3","difficulty":2,"kind":"mc","stem":"띠그래프로 나타낼 때 띠를 백분율만큼 나눈 바로 다음에 할 일은 무엇인가요?","options":[{"t":"나눈 칸에 내용과 백분율 쓰기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율의 합이 100 %인지 확인하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「나눈 칸에 내용과 백분율 쓰기」는 ④ 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 각 항목의 백분율을 구한 바로 다음에 할 일은 무엇인가요?","options":[{"t":"백분율의 합이 100 %인지 확인하기","correct":true},{"t":"각 항목의 백분율 구하기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「백분율의 합이 100 %인지 확인하기」는 ② 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#2','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 40 %, 25 %, 20 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","40 + 25 + 20 = 85예요.","100 − 85 = 15예요."]},{"stem":"띠그래프 네 항목의 백분율이 32 %, 28 %, 24 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","32 + 28 + 24 = 84예요.","100 − 84 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#3','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','좋아하는 계절 조사(봄 8명, 가을 7명, 여름 6명, 겨울 4명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 겨울의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"좋아하는 계절 조사(봄 8명, 가을 7명, 여름 6명, 겨울 4명, 전체 25명)를 띠그래프로 나타내고 있어요. ?에 알맞은 겨울의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["겨울은 4명이에요.","4 ÷ 25 × 100 = 16이에요.","?는 16이에요."],"mis":"M6-1-u5-X04","asset":{"type":"pgr","kind":"band","items":[["봄",32],["가을",28],["여름",24],["겨울",16]],"title":"좋아하는 계절","hide":[3]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(합창 18명, 미술 14명, 과학 11명, 독서 7명, 전체 50명)를 띠그래프로 나타내고 있어요. ?에 알맞은 과학의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["과학은 11명이에요.","11 ÷ 50 × 100 = 22예요.","?는 22예요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[2]}},{"stem":"먹고 싶은 간식 조사(떡볶이 14명, 과일 12명, 빵 8명, 과자 6명, 전체 40명)를 띠그래프로 나타내고 있어요. ?에 알맞은 과자의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["과자는 6명이에요.","6 ÷ 40 × 100 = 15예요.","?는 15예요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#4','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','길이가 15 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"길이가 15 cm인 띠를 전체로 하여 띠그래프를 그려요. 40 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["띠 전체 15 cm가 100 %예요.","15 × 40 % = 6이에요.","6 cm로 나누어요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"길이가 25 cm인 띠를 전체로 하여 띠그래프를 그려요. 36 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["띠 전체 25 cm가 100 %예요.","25 × 36 % = 9예요.","9 cm로 나누어요."]},{"stem":"길이가 30 cm인 띠를 전체로 하여 띠그래프를 그려요. 70 %인 항목은 몇 cm로 나누어야 하나요? 숫자로 쓰세요.","answer":["21"],"explanation":["띠 전체 30 cm가 100 %예요.","30 × 70 % = 21이에요.","21 cm로 나누어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#5','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'mc','auto','빌린 책의 종류 조사에서 역사는 40권, 전체는 200권이에요. 역사의 백분율로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X04','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C3","difficulty":3,"kind":"mc","stem":"빌린 책의 종류 조사에서 역사는 40권, 전체는 200권이에요. 역사의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"20 %","correct":true},{"t":"40 %","mis":"M6-1-u5-X14"},{"t":"2 %","mis":"M6-1-u5-X04"},{"t":"80 %","mis":"M6-1-u5-X16"}],"explanation":["전체 200권 가운데 40권이에요.","40 ÷ 200 × 100 = 20이에요.","그래서 20 %예요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사에서 미술은 14명, 전체는 50명이에요. 미술의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"28 %","correct":true},{"t":"14 %","mis":"M6-1-u5-X14"},{"t":"72 %","mis":"M6-1-u5-X16"},{"t":"38 %","mis":"M6-1-u5-X15"}],"explanation":["전체 50명 가운데 14명이에요.","14 ÷ 50 × 100 = 28이에요.","그래서 28 %예요."]},{"stem":"학교에 오는 방법 조사에서 버스는 12명, 전체는 50명이에요. 버스의 백분율로 알맞은 것은 어느 것인가요?","options":[{"t":"24 %","correct":true},{"t":"12 %","mis":"M6-1-u5-X14"},{"t":"76 %","mis":"M6-1-u5-X16"},{"t":"34 %","mis":"M6-1-u5-X15"}],"explanation":["전체 50명 가운데 12명이에요.","12 ÷ 50 × 100 = 24예요.","그래서 24 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#6','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'ox','auto','띠그래프에는 제목을 쓰지 않아도 돼요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":3,"kind":"ox","stem":"띠그래프에는 제목을 쓰지 않아도 돼요.","answer":"X","reason_options":[{"t":"무엇을 조사한 그래프인지 알 수 있게 제목을 써야 하기 때문에","correct":true},{"t":"칸에 내용이 있으면 제목은 필요 없기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."],"variant_rule":{"alt":[{"stem":"전체 20명 가운데 6명이면 백분율은 6 %예요.","answer":"X","reason_options":[{"t":"6 ÷ 20 × 100 = 30이라 30 %이기 때문에","correct":true},{"t":"항목의 수가 곧 백분율이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]},{"stem":"띠그래프 각 칸의 백분율을 모두 더하면 100 %가 되어야 해요.","answer":"O","reason_options":[{"t":"띠 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"칸의 개수가 언제나 100개이기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프는 백분율 → 합 100 확인 → 띠 나누기 → 내용·백분율 → 제목 차례로 그려요.","백분율은 항목의 수 ÷ 전체 × 100이에요.","길이가 곧 비율이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#7','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',3,'sa','auto','김밥의 3대 영양소 조사를 띠그래프로 나타냈는데 단백질의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C3","difficulty":3,"kind":"sa","stem":"김밥의 3대 영양소 조사를 띠그래프로 나타냈는데 단백질의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 68 + 16 = 84예요.","100 − 84 = 16이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["탄수화물",68],["단백질",16],["지방",16]],"title":"김밥의 3대 영양소","hide":[1]},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 띠그래프로 나타냈는데 선물의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 25 + 20 + 5 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임","hide":[3]}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 밭의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 20 + 15 = 75예요.","100 − 75 = 25예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[1]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#8','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'error','auto','빌린 책의 종류 조사에서 과학은 50권, 전체는 200권이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":8,"concept":"M6-1-u5-C3","difficulty":4,"kind":"error","stem":"빌린 책의 종류 조사에서 과학은 50권, 전체는 200권이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「과학은 50권이니까 50 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"예준 — 「50 ÷ 200 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","50 ÷ 200 × 100 = 25예요.","수아는 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사에서 합창은 18명, 전체는 50명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합창은 18명이니까 18 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"유진 — 「18 ÷ 50 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","18 ÷ 50 × 100 = 36이에요.","가온은 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"학교에 오는 방법 조사에서 자전거는 10명, 전체는 50명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「자전거는 10명이니까 10 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"시우 — 「10 ÷ 50 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","10 ÷ 50 × 100 = 20이에요.","여울은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#9','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 길이가 10 cm인 띠를 전체로 하여 띠그래프를 그리면 경복궁 칸은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C3","difficulty":4,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 길이가 10 cm인 띠를 전체로 하여 띠그래프를 그리면 경복궁 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["경복궁의 백분율은 6 ÷ 20 × 100 = 30이에요.","띠 10 cm가 100 %니 10 × 30 % = 3이에요.","경복궁 칸은 3 cm예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 길이가 20 cm인 띠를 전체로 하여 띠그래프를 그리면 축구 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["축구의 백분율은 9 ÷ 20 × 100 = 45예요.","띠 20 cm가 100 %니 20 × 45 % = 9예요.","축구 칸은 9 cm예요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 길이가 15 cm인 띠를 전체로 하여 띠그래프를 그리면 강아지 칸은 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["강아지의 백분율은 10 ÷ 25 × 100 = 40이에요.","띠 15 cm가 100 %니 15 × 40 % = 6이에요.","강아지 칸은 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L03_challenge#10','math',6,1,'u5','L03','g6_1_math_u5_L03_challenge','lesson_challenge','M6-1-u5-C3',4,'essay','teacher','외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C3","difficulty":4,"kind":"essay","stem":"외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 각 항목의 백분율을 구한다 — 경복궁 6 ÷ 20 × 100 = 30, 첨성대 25, 수원 화성 20, 종묘 15, 기타 10. ② 30 + 25 + 20 + 15 + 10 = 100이므로 합이 100 %인지 확인한다. ③ 백분율만큼 띠의 길이를 나눈다. ④ 나눈 칸에 내용과 백분율을 쓴다. ⑤ 제목을 쓴다.","scoring_points":["다섯 항목의 백분율을 바르게 구했는가","합이 100인지 확인했는가","띠 나누기 → 내용·백분율 → 제목 차례를 썼는가"]},"explanation":["백분율은 30, 25, 20, 15, 10 %예요.","30 + 25 + 20 + 15 + 10 = 100이에요.","띠 나누기 → 내용·백분율 → 제목 차례로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#1','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'mc','auto','원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?',ARRAY['M6-1-u5-X06']::text[],true,'{"seq":1,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"원그래프를 그리는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"백분율 구하기 → 합 100 % 확인 → 중심에서 선 긋기 → 내용·백분율 쓰기 → 제목 쓰기","correct":true},{"t":"제목 쓰기 → 백분율 구하기 → 중심에서 선 긋기 → 내용·백분율 쓰기","mis":"M6-1-u5-X12"},{"t":"중심에서 선 긋기 → 백분율 구하기 → 합 100 % 확인 → 제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율 구하기 → 둘레에서 선 긋기 → 내용·백분율 쓰기 → 제목 쓰기","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#2','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C4","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#3','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'mc','auto','원그래프와 띠그래프의 같은 점으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X10','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프와 띠그래프의 같은 점으로 옳은 것은 어느 것인가요?","options":[{"t":"둘 다 백분율의 합이 100 %예요","correct":true},{"t":"둘 다 원 모양이에요","mis":"M6-1-u5-X07"},{"t":"둘 다 시간에 따른 변화를 보여 줘요","mis":"M6-1-u5-X10"},{"t":"둘 다 각 항목의 실제 수를 보여 줘요","mis":"M6-1-u5-X02"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「둘 다 백분율의 합이 100 %예요」예요."],"variant_rule":{"alt":[{"stem":"원그래프와 띠그래프의 다른 점으로 옳은 것은 어느 것인가요?","options":[{"t":"원그래프는 넓이로, 띠그래프는 길이로 비율을 나타내요","correct":true},{"t":"원그래프만 전체를 100 %로 봐요","mis":"M6-1-u5-X03"},{"t":"띠그래프만 비율을 나타내요","mis":"M6-1-u5-X11"},{"t":"원그래프는 실제 수를, 띠그래프는 비율을 나타내요","mis":"M6-1-u5-X02"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「원그래프는 넓이로, 띠그래프는 길이로 비율을 나타내요」예요."]},{"stem":"원그래프로 나타내기에 알맞은 자료는 어느 것인가요?","options":[{"t":"전체에서 각 항목이 차지하는 비율","correct":true},{"t":"하루 동안의 기온 변화","mis":"M6-1-u5-X10"},{"t":"달마다 저금한 금액의 변화","mis":"M6-1-u5-X10"},{"t":"학년별 학생 수의 크기","mis":"M6-1-u5-X11"}],"explanation":["원그래프와 띠그래프는 둘 다 전체를 100 %로 보는 비율그래프예요.","띠는 길이로, 원은 넓이로 비율을 나타내요.","그래서 답은 「전체에서 각 항목이 차지하는 비율」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#4','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',1,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":1,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"원그래프는 원의 둘레 아무 곳에서나 선을 그어 나눠도 돼요.","answer":"X","reason_options":[{"t":"원의 중심에서 선을 그어야 넓이가 비율을 나타내기 때문에","correct":true},{"t":"조각의 개수만 맞으면 되기 때문에","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"눈금 20칸인 원그래프에서 35 %는 7칸이에요.","answer":"O","reason_options":[{"t":"35 ÷ 5 = 7이기 때문에","correct":true},{"t":"35를 20칸으로 나누기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#5','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#6','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#7','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈어요. 건설은 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈어요. 건설은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","건설은 38 %예요.","답은 38이에요."],"mis":"M6-1-u5-X16","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개는 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","3개는 37 %예요.","답은 37이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"용돈 쓰임 조사를 원그래프로 나타냈어요. 저금은 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["원그래프의 칸마다 항목과 백분율이 적혀 있어요.","저금은 35 %예요.","답은 35예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#8','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈어요. 사업장과 건설을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈어요. 사업장과 건설을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["87"],"explanation":["사업장은 49 %, 건설은 38 %예요.","49 % + 38 % = 87 %예요.","답은 87이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물"},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 원그래프로 나타냈어요. 간식과 학용품을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["간식은 25 %, 학용품은 20 %예요.","25 % + 20 % = 45 %예요.","답은 45예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}},{"stem":"마을 땅 쓰임 조사를 원그래프로 나타냈어요. 밭과 과수원을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["밭은 25 %, 과수원은 20 %예요.","25 % + 20 % = 45 %예요.","답은 45예요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#9','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',2,'ox','auto','반올림한 백분율의 합이 101 %이면 가장 큰 항목을 1 % 줄여요.',ARRAY['M6-1-u5-X08']::text[],true,'{"seq":9,"concept":"M6-1-u5-C4","difficulty":2,"kind":"ox","stem":"반올림한 백분율의 합이 101 %이면 가장 큰 항목을 1 % 줄여요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 100보다 커도 그대로 그리면 되기 때문에","mis":"M6-1-u5-X08"}],"mis":"M6-1-u5-X08","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"반올림한 백분율의 합이 99 %이면 가장 작은 항목을 1 % 늘려요.","answer":"X","reason_options":[{"t":"가장 큰 항목을 늘려 100 %로 맞추기 때문에","correct":true},{"t":"작은 항목이 더 정확하지 않기 때문에","mis":"M6-1-u5-X08"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"원그래프에서 25 %는 원의 넓이의 4분의 1이에요.","answer":"O","reason_options":[{"t":"100 %의 4분의 1이 25 %이기 때문에","correct":true},{"t":"원을 4개 그려야 하기 때문에","mis":"M6-1-u5-X07"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_basic#10','math',6,1,'u5','L04','g6_1_math_u5_L04_basic','lesson_basic','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#1','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 80 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["16"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","80 ÷ 5 = 16이에요.","16칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 25 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","25 ÷ 5 = 5예요.","5칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#2','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 원그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}},{"stem":"김밥의 3대 영양소 조사를 원그래프로 나타냈는데 지방의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 68 + 16 = 84예요.","100 − 84 = 16이에요."],"asset":{"type":"pgr","kind":"pie","items":[["탄수화물",68],["단백질",16],["지방",16]],"title":"김밥의 3대 영양소","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#3','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'sa','auto','전체 30명 가운데 버스를 타는 학생이 7명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"전체 30명 가운데 버스를 타는 학생이 7명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["7 ÷ 30 × 100을 계산하면 23.3…예요.","소수 첫째 자리에서 반올림해요.","그래서 23 %예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"전체 12명 가운데 안경을 쓴 학생이 5명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["5 ÷ 12 × 100을 계산하면 41.6…예요.","소수 첫째 자리에서 반올림해요.","그래서 42 %예요."]},{"stem":"전체 24명 가운데 피아노를 배우는 학생이 11명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["11 ÷ 24 × 100을 계산하면 45.8…예요.","소수 첫째 자리에서 반올림해요.","그래서 46 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#4','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 36 %, 35 %, 30 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["35"],"explanation":["36 + 35 + 30 = 101이에요.","가장 큰 항목 36을 1 줄여 고쳐요.","36 − 1 = 35예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 61 %, 22 %, 16 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["62"],"explanation":["61 + 22 + 16 = 99예요.","가장 큰 항목 61을 1 늘려 고쳐요.","61 + 1 = 62예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#5','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'error','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X08','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C4","difficulty":3,"kind":"error","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「가장 작은 21 %를 20 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"도윤 — 「더하면 101 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「가장 큰 47 %를 46 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목을 47에서 46으로 고쳐 100 %로 맞춰요.","하린은 가장 작은 항목을 고친다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「가장 작은 27 %를 28 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"예준 — 「더하면 99 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가장 큰 38 %를 39 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목을 38에서 39로 고쳐 100 %로 맞춰요.","수아는 가장 작은 항목을 고친다고 잘못 말했어요."]},{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 원그래프로 나타내려고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「가장 작은 24 %를 25 %로 고치면 돼.」","correct":true,"mis_target":"M6-1-u5-X08"},{"t":"유진 — 「더하면 99 %라 100 %가 아니야.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「가장 큰 44 %를 45 %로 고치면 돼.」","mis":"M6-1-u5-X16"}],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목을 44에서 45로 고쳐 100 %로 맞춰요.","가온은 가장 작은 항목을 고친다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#6','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'mc','auto','탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":3,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"3개","correct":true},{"t":"1개 이하","mis":"M6-1-u5-X16"},{"t":"2개","mis":"M6-1-u5-X07"},{"t":"4개","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","3개가 37 %로 가장 커요.","그래서 답은 3개예요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"논","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"밭","mis":"M6-1-u5-X07"},{"t":"과수원","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","논이 40 %로 가장 커요.","그래서 답은 논이에요."],"asset":{"type":"pgr","kind":"pie","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}},{"stem":"용돈 쓰임 조사를 원그래프 로 나타냈어요. 비율이 가장 작은 항목은 무엇인가요?","options":[{"t":"기타","correct":true},{"t":"저금","mis":"M6-1-u5-X16"},{"t":"간식","mis":"M6-1-u5-X07"},{"t":"학용품","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","기타가 5 %로 가장 작아요.","그래서 답은 기타예요."],"asset":{"type":"pgr","kind":"pie","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#7','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',3,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":7,"concept":"M6-1-u5-C4","difficulty":3,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"눈금 20칸인 원그래프에서 35 %는 7칸이에요.","answer":"O","reason_options":[{"t":"35 ÷ 5 = 7이기 때문에","correct":true},{"t":"35를 20칸으로 나누기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"원그래프에서 25 %는 원의 넓이의 4분의 1이에요.","answer":"O","reason_options":[{"t":"100 %의 4분의 1이 25 %이기 때문에","correct":true},{"t":"원을 4개 그려야 하기 때문에","mis":"M6-1-u5-X07"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#8','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'sa','auto','눈금이 20칸인 원그래프에 35 %인 항목과 25 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C4","difficulty":4,"kind":"sa","stem":"눈금이 20칸인 원그래프에 35 %인 항목과 25 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목을 합하면 35 % + 25 % = 60 %예요.","눈금 한 칸은 5 %예요.","60 ÷ 5 = 12 — 12칸이에요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에 40 %인 항목과 15 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["두 항목을 합하면 40 % + 15 % = 55 %예요.","눈금 한 칸은 5 %예요.","55 ÷ 5 = 11 — 11칸이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에 18 %인 항목과 22 %인 항목을 이어서 그렸어요. 두 항목을 합한 부분은 눈금 몇 칸인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 항목을 합하면 18 % + 22 % = 40 %예요.","눈금 한 칸은 5 %예요.","40 ÷ 5 = 8 — 8칸이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#9','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'sa','auto','전체 60명 가운데 걸어서 오는 학생이 17명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C4","difficulty":4,"kind":"sa","stem":"전체 60명 가운데 걸어서 오는 학생이 17명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["17 ÷ 60 × 100을 계산하면 28.3…예요.","소수 첫째 자리에서 반올림해요.","그래서 28 %예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"전체 70명 가운데 줄넘기를 잘하는 학생이 19명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["19 ÷ 70 × 100을 계산하면 27.1…예요.","소수 첫째 자리에서 반올림해요.","그래서 27 %예요."]},{"stem":"전체 80명 가운데 아침밥을 먹고 온 학생이 23명이에요. 백분율을 소수 첫째 자리에서 반올림하면 몇 %인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["23 ÷ 80 × 100을 계산하면 28.7…예요.","소수 첫째 자리에서 반올림해요.","그래서 29 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L04_challenge#10','math',6,1,'u5','L04','g6_1_math_u5_L04_challenge','lesson_challenge','M6-1-u5-C4',4,'essay','teacher','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 이대로 원그래프를 그려도 되는지 판단하고, 어떻게 고쳐 그리면 되는지 눈금 칸 수와 함께 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C4","difficulty":4,"kind":"essay","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 이대로 원그래프를 그려도 되는지 판단하고, 어떻게 고쳐 그리면 되는지 눈금 칸 수와 함께 설명해 보세요.","answer_guide":{"answer":"예: 47 + 33 + 21 = 101이라 100 %가 아니므로 그대로 그리면 안 된다. 가장 큰 항목 47 %를 1 % 줄여 46 %로 고치면 46 + 33 + 21 = 100이 된다. 눈금 한 칸이 5 %인 원에 원의 중심에서 선을 그어 백분율만큼 나누고, 내용·백분율·제목을 쓴다.","scoring_points":["합이 101이라 고쳐야 한다고 판단했는가","가장 큰 항목을 46 %로 고쳤는가","원의 중심에서 선을 그어 나눈다고 썼는가"]},"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목을 46 %로 고쳐요.","중심에서 선을 그어 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#1','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'mc','auto','모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12','M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."],"variant_rule":{"alt":[{"stem":"그래프를 「해석한다」는 것은 무엇을 하는 것인가요?","options":[{"t":"그래프를 보고 알 수 있는 사실을 찾는 것","correct":true},{"t":"그래프를 예쁘게 색칠하는 것","mis":"M6-1-u5-X16"},{"t":"그래프를 다시 그리는 것","mis":"M6-1-u5-X12"},{"t":"그래프의 제목을 바꾸는 것","mis":"M6-1-u5-X16"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「그래프를 보고 알 수 있는 사실을 찾는 것」이에요."]},{"stem":"자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 모으기 → 표 → 백분율 → 그래프 → 해석","correct":true},{"t":"그래프 → 표 → 자료 모으기 → 해석","mis":"M6-1-u5-X12"},{"t":"자료 모으기 → 그래프 → 백분율 → 표","mis":"M6-1-u5-X12"},{"t":"백분율 → 자료 모으기 → 해석 → 표","mis":"M6-1-u5-X12"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「자료 모으기 → 표 → 백분율 → 그래프 → 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#2','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'sa','auto','해 보고 싶은 체험 활동 조사에서 가상 현실은 16명, 전체는 40명이에요. 가상 현실의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C5","difficulty":1,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사에서 가상 현실은 16명, 전체는 40명이에요. 가상 현실의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","16 ÷ 40 × 100 = 40이에요.","가상 현실은 40 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사에서 요리는 8명, 전체는 40명이에요. 요리의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","8 ÷ 40 × 100 = 20이에요.","요리는 20 %예요."]},{"stem":"들고 싶은 동아리 조사에서 합창은 18명, 전체는 50명이에요. 합창의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","18 ÷ 50 × 100 = 36이에요.","합창은 36 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#3','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'mc','auto','해 보고 싶은 체험 활동 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"합창","correct":true},{"t":"독서","mis":"M6-1-u5-X16"},{"t":"미술","mis":"M6-1-u5-X07"},{"t":"과학","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","합창이 36 %로 가장 커요.","그래서 답은 합창이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}},{"stem":"먹고 싶은 간식 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"떡볶이","correct":true},{"t":"과자","mis":"M6-1-u5-X16"},{"t":"과일","mis":"M6-1-u5-X07"},{"t":"빵","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","떡볶이가 35 %로 가장 커요.","그래서 답은 떡볶이예요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#4','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',1,'ox','auto','자료를 모으면 표로 정리하고 백분율을 구한 뒤 그래프로 나타내요.',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":4,"concept":"M6-1-u5-C5","difficulty":1,"kind":"ox","stem":"자료를 모으면 표로 정리하고 백분율을 구한 뒤 그래프로 나타내요.","answer":"O","reason_options":[{"t":"백분율을 알아야 비율그래프를 그릴 수 있기 때문에","correct":true},{"t":"그래프를 먼저 그리고 표를 만들기 때문에","mis":"M6-1-u5-X12"}],"mis":"M6-1-u5-X12","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"그래프를 그린 뒤에는 그래프를 보고 알 수 있는 사실을 찾아요.","answer":"O","reason_options":[{"t":"그래프는 해석해야 쓸모가 있기 때문에","correct":true},{"t":"그래프를 그리면 할 일이 끝나기 때문에","mis":"M6-1-u5-X13"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"같은 자료를 띠그래프와 원그래프로 나타내면 두 그래프의 백분율은 서로 달라요.","answer":"X","reason_options":[{"t":"같은 자료이면 백분율이 같고 모양만 다르기 때문에","correct":true},{"t":"원은 넓이를 써서 백분율이 커지기 때문에","mis":"M6-1-u5-X07"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#5','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'match','auto','해 보고 싶은 체험 활동 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명)','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C5","difficulty":2,"kind":"match","stem":"해 보고 싶은 체험 활동 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명)","pairs":[{"l":"가상 현실","r":"40 %"},{"l":"로봇","r":"30 %"},{"l":"요리","r":"20 %"},{"l":"목공","r":"10 %"}],"mis":"M6-1-u5-X04","explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","16 ÷ 40 × 100 = 40, 12 ÷ 40 × 100 = 30이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."],"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)에서 항목과 백분율을 알맞게 이으세요. (합창 18명, 미술 14명, 과학 11명, 독서 7명)","pairs":[{"l":"합창","r":"36 %"},{"l":"미술","r":"28 %"},{"l":"과학","r":"22 %"},{"l":"독서","r":"14 %"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","18 ÷ 50 × 100 = 36, 14 ÷ 50 × 100 = 28이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."]},{"stem":"먹고 싶은 간식 조사(전체 40명)에서 항목과 백분율을 알맞게 이으세요. (떡볶이 14명, 과일 12명, 빵 8명, 과자 6명)","pairs":[{"l":"떡볶이","r":"35 %"},{"l":"과일","r":"30 %"},{"l":"빵","r":"20 %"},{"l":"과자","r":"15 %"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","14 ÷ 40 × 100 = 35, 12 ÷ 40 × 100 = 30이에요.","나머지도 같은 방법으로 구하고 합이 100인지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#6','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 과일의 비율은 과자의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["과일은 30 %, 과자는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"좋아하는 운동 조사를 띠그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"band","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#7','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 빵은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["빵은 20 %예요.","40 × 20 % = 8이에요.","빵은 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 피구는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["피구는 30 %예요.","20 × 30 % = 6이에요.","피구는 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#8','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 빵과 과자를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["빵은 20 %, 과자는 15 %예요.","20 % + 15 % = 35 %예요.","답은 35예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}},{"stem":"들고 싶은 동아리 조사를 띠그래프로 나타냈어요. 미술과 과학을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["미술은 28 %, 과학은 22 %예요.","28 % + 22 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#9','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',2,'ox','auto','가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.',ARRAY['M6-1-u5-X09']::text[],true,'{"seq":9,"concept":"M6-1-u5-C5","difficulty":2,"kind":"ox","stem":"가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.","answer":"X","reason_options":[{"t":"40 ÷ 10 = 4라 4배이기 때문에","correct":true},{"t":"40 − 10 = 30이기 때문에","mis":"M6-1-u5-X09"}],"mis":"M6-1-u5-X09","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"전체 40명 가운데 요리가 20 %이면 요리를 고른 학생은 8명이에요.","answer":"O","reason_options":[{"t":"40 × 20 % = 8이기 때문에","correct":true},{"t":"40 − 20 = 20이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"반올림해 합이 99 %가 되면 가장 큰 항목을 1 % 늘려 그려요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 99 %여도 그대로 그리기 때문에","mis":"M6-1-u5-X08"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_basic#10','math',6,1,'u5','L05','g6_1_math_u5_L05_basic','lesson_basic','M6-1-u5-C5',3,'error','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"하린 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"도윤 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","하린은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사(전체 20명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「경복궁은 기타보다 20배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「경복궁이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「경복궁은 6명이야.」","mis":"M6-1-u5-X16"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이니 3배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사(전체 50명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"가온 — 「복숭아는 배보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"유진 — 「복숭아가 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「복숭아는 20명이야.」","mis":"M6-1-u5-X16"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4니 4배예요.","가온은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#1','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',2,'mc','auto','자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":1,"concept":"M6-1-u5-C5","difficulty":2,"kind":"mc","stem":"자료를 모아 비율그래프로 나타내는 흐름으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료 모으기 → 표 → 백분율 → 그래프 → 해석","correct":true},{"t":"그래프 → 표 → 자료 모으기 → 해석","mis":"M6-1-u5-X12"},{"t":"자료 모으기 → 그래프 → 백분율 → 표","mis":"M6-1-u5-X12"},{"t":"백분율 → 자료 모으기 → 해석 → 표","mis":"M6-1-u5-X12"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「자료 모으기 → 표 → 백분율 → 그래프 → 해석」이에요."],"variant_rule":{"alt":[{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]},{"stem":"그래프를 「해석한다」는 것은 무엇을 하는 것인가요?","options":[{"t":"그래프를 보고 알 수 있는 사실을 찾는 것","correct":true},{"t":"그래프를 예쁘게 색칠하는 것","mis":"M6-1-u5-X16"},{"t":"그래프를 다시 그리는 것","mis":"M6-1-u5-X12"},{"t":"그래프의 제목을 바꾸는 것","mis":"M6-1-u5-X16"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「그래프를 보고 알 수 있는 사실을 찾는 것」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#2','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈는데 요리의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C5","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈는데 요리의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동","hide":[2]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사를 띠그래프로 나타냈는데 과학의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 36 + 28 + 14 = 78이에요.","100 − 78 = 22예요."],"asset":{"type":"pgr","kind":"band","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[2]}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈는데 빵의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 35 + 30 + 15 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#3','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'mc','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C5","difficulty":3,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#4','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'sa','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈는데 목공의 백분율이 지워졌어요. 목공은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u5-C5","difficulty":3,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈는데 목공의 백분율이 지워졌어요. 목공은 몇 명인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["목공의 백분율은 100 − (40 + 30 + 20) = 10이에요.","40 × 10 % = 4예요.","목공은 4명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동","hide":[3]},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈는데 독서의 백분율이 지워졌어요. 독서는 몇 명인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["독서의 백분율은 100 − (36 + 28 + 22) = 14예요.","50 × 14 % = 7이에요.","독서는 7명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리","hide":[3]}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 띠그래프로 나타냈는데 과자의 백분율이 지워졌어요. 과자는 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["과자의 백분율은 100 − (35 + 30 + 20) = 15예요.","40 × 15 % = 6이에요.","과자는 6명이에요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#5','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'error','auto','좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"좋아하는 과일 조사(전체 50명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「복숭아는 배보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「복숭아가 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「복숭아는 20명이야.」","mis":"M6-1-u5-X16"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 원그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"가온 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"유진 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","가온은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사(전체 20명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"여울 — 「경복궁은 기타보다 20배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"시우 — 「경복궁이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「경복궁은 6명이야.」","mis":"M6-1-u5-X16"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이니 3배예요.","여울은 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#6','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'sa','auto','반올림해 구한 세 항목의 백분율이 41 %, 35 %, 25 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 41 %, 35 %, 25 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["40"],"explanation":["41 + 35 + 25 = 101이에요.","가장 큰 항목 41을 1 줄여 고쳐요.","41 − 1 = 40이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 46 %, 29 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["47"],"explanation":["46 + 29 + 24 = 99예요.","가장 큰 항목 46을 1 늘려 고쳐요.","46 + 1 = 47이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 39 %, 32 %, 30 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["38"],"explanation":["39 + 32 + 30 = 101이에요.","가장 큰 항목 39를 1 줄여 고쳐요.","39 − 1 = 38이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#7','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',3,'ox','auto','가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.',ARRAY['M6-1-u5-X09']::text[],true,'{"seq":7,"concept":"M6-1-u5-C5","difficulty":3,"kind":"ox","stem":"가상 현실 40 %, 목공 10 %이면 가상 현실은 목공의 30배예요.","answer":"X","reason_options":[{"t":"40 ÷ 10 = 4라 4배이기 때문에","correct":true},{"t":"40 − 10 = 30이기 때문에","mis":"M6-1-u5-X09"}],"mis":"M6-1-u5-X09","explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."],"variant_rule":{"alt":[{"stem":"전체 40명 가운데 요리가 20 %이면 요리를 고른 학생은 8명이에요.","answer":"O","reason_options":[{"t":"40 × 20 % = 8이기 때문에","correct":true},{"t":"40 − 20 = 20이기 때문에","mis":"M6-1-u5-X14"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]},{"stem":"반올림해 합이 99 %가 되면 가장 큰 항목을 1 % 늘려 그려요.","answer":"O","reason_options":[{"t":"가장 큰 항목을 고쳐야 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"합이 99 %여도 그대로 그리기 때문에","mis":"M6-1-u5-X08"}],"explanation":["자료 → 표 → 백분율 → 그래프 → 해석의 흐름으로 나타내요.","「몇 배」는 나눗셈, 실제 수는 전체 × 백분율이에요.","해석은 그래프를 보고 사실을 찾는 일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#8','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'sa','auto','가상 현실을 고른 학생은 16명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C5","difficulty":4,"kind":"sa","stem":"가상 현실을 고른 학생은 16명이고, 이것은 전체의 40 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 40 % = 16이에요.","1 %는 16 ÷ 40 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"축구를 고른 학생은 9명이고, 이것은 전체의 45 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["전체 × 45 % = 9예요.","1 %는 9 ÷ 45 = 0.2이고 전체 100 %는 그 100배예요.","0.2 × 100 = 20 — 전체는 20명이에요."]},{"stem":"독서 동아리를 고른 학생은 7명이고, 이것은 전체의 14 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["전체 × 14 % = 7이에요.","1 %는 7 ÷ 14 = 0.5이고 전체 100 %는 그 100배예요.","0.5 × 100 = 50 — 전체는 50명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#9','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'sa','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 가상 현실은 목공보다 몇 명 더 많은가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C5","difficulty":4,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 가상 현실은 목공보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 항목의 백분율 차는 40 % − 10 % = 30 %예요.","40 × 30 % = 12예요.","가상 현실이 12명 더 많아요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈어요. 합창은 독서보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["11"],"explanation":["두 항목의 백분율 차는 36 % − 14 % = 22 %예요.","50 × 22 % = 11이에요.","합창이 11명 더 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 띠그래프로 나타냈어요. 떡볶이는 과자보다 몇 명 더 많은가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 항목의 백분율 차는 35 % − 15 % = 20 %예요.","40 × 20 % = 8이에요.","떡볶이가 8명 더 많아요."],"asset":{"type":"pgr","kind":"band","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L05_challenge#10','math',6,1,'u5','L05','g6_1_math_u5_L05_challenge','lesson_challenge','M6-1-u5-C5',4,'essay','teacher','우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C5","difficulty":4,"kind":"essay","stem":"우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.","answer_guide":{"answer":"예: 가상 현실 16 ÷ 40 × 100 = 40, 로봇 30, 요리 20, 목공 10이고 합은 100 %이다. 이 백분율만큼 띠그래프(또는 원그래프)로 나타낸다. 그래프를 보면 가상 현실이 40 %로 가장 많고 목공의 4배이다.","scoring_points":["네 항목의 백분율을 구했는가","합 100을 확인하고 그래프로 나타낸다고 썼는가","그래프에서 바른 사실을 찾았는가"]},"explanation":["백분율은 40, 30, 20, 10 %예요.","합이 100 %인지 확인하고 그래프로 나타내요.","가상 현실이 가장 많고 목공의 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#1','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":1,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#2','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"우리 반 학생들이 좋아하는 운동이 전체에서 차지하는 비율을 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]},{"stem":"마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"그림그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「그림그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#3','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'mc','auto','띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":3,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."],"variant_rule":{"alt":[{"stem":"그래프를 고를 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"무엇을 보여 주고 싶은지(목적)","correct":true},{"t":"무슨 색을 칠할지","mis":"M6-1-u5-X16"},{"t":"그래프 이름의 글자 수","mis":"M6-1-u5-X16"},{"t":"그래프를 그린 사람","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「무엇을 보여 주고 싶은지(목적)」예요."]},{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#4','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',1,'ox','auto','시간에 따른 변화를 보려면 꺾은선그래프가 알맞아요.',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":4,"concept":"M6-1-u5-C6","difficulty":1,"kind":"ox","stem":"시간에 따른 변화를 보려면 꺾은선그래프가 알맞아요.","answer":"O","reason_options":[{"t":"꺾은선그래프는 선의 기울기로 변화를 보여 주기 때문에","correct":true},{"t":"꺾은선그래프는 비율을 보여 주기 때문에","mis":"M6-1-u5-X10"}],"mis":"M6-1-u5-X10","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"같은 자료라도 보여 주고 싶은 것에 따라 알맞은 그래프가 달라요.","answer":"O","reason_options":[{"t":"그래프마다 잘 보여 주는 것이 다르기 때문에","correct":true},{"t":"그래프는 아무것이나 써도 같기 때문에","mis":"M6-1-u5-X10"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"그래프를 고를 때는 목적을 먼저 정해요.","answer":"O","reason_options":[{"t":"무엇을 보여 줄지에 따라 그래프가 정해지기 때문에","correct":true},{"t":"그래프 모양이 예쁜 것을 먼저 고르기 때문에","mis":"M6-1-u5-X10"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#5','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'match','auto','보여 주고 싶은 것과 알맞은 그래프를 이으세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C6","difficulty":2,"kind":"match","stem":"보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"전체에 대한 부분의 비율","r":"띠그래프"},{"l":"시간에 따른 변화","r":"꺾은선그래프"},{"l":"항목별 수의 크기","r":"막대그래프"}],"mis":"M6-1-u5-X10","explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"전체에 대한 부분의 비율","r":"원그래프"},{"l":"달마다 달라지는 키","r":"꺾은선그래프"},{"l":"반별 학생 수 비교","r":"막대그래프"}],"explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."]},{"stem":"이번에는 다른 보기예요. 보여 주고 싶은 것과 알맞은 그래프를 이으세요.","pairs":[{"l":"용돈 쓰임의 비율","r":"원그래프"},{"l":"하루 동안의 기온 변화","r":"꺾은선그래프"},{"l":"마을별 생산량을 그림으로","r":"그림그래프"}],"explanation":["비율은 띠·원그래프, 변화는 꺾은선그래프예요.","수의 크기는 막대·그림그래프가 잘 보여 줘요.","목적을 먼저 정하고 그래프를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#6','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'mc','auto','가 반은 20명, 나 반은 40명이에요. 두 반 모두 독서를 좋아하는 학생의 비율이 50 %예요. 독서를 좋아하는 학생 수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"가 반은 20명, 나 반은 40명이에요. 두 반 모두 독서를 좋아하는 학생의 비율이 50 %예요. 독서를 좋아하는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 50 %라도 전체가 다르면 수가 달라요.","가 반은 20 × 50 % = 10, 나 반은 40 × 50 % = 20이에요.","그래서 나 반이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 반은 25명, 나 반은 50명이에요. 두 반 모두 강아지를 키우는 학생의 비율이 40 %예요. 강아지를 키우는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가 반은 25 × 40 % = 10, 나 반은 50 × 40 % = 20이에요.","그래서 나 반이 더 많아요."]},{"stem":"가 반은 30명, 나 반은 60명이에요. 두 반 모두 피아노를 배우는 학생의 비율이 20 %예요. 피아노를 배우는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가 반은 30 × 20 % = 6, 나 반은 60 × 20 % = 12예요.","그래서 나 반이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#7','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'sa','auto','전체 40명 가운데 독서를 좋아하는 학생이 50 %예요. 독서를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C6","difficulty":2,"kind":"sa","stem":"전체 40명 가운데 독서를 좋아하는 학생이 50 %예요. 독서를 좋아하는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 50 % = 20이에요.","독서를 좋아하는 학생은 20명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 25명 가운데 강아지를 키우는 학생이 40 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","25 × 40 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]},{"stem":"전체 60명 가운데 자전거를 타는 학생이 35 %예요. 자전거를 타는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 35 % = 21이에요.","자전거를 타는 학생은 21명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#8','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'mc','auto','작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M6-1-u5-X02','M6-1-u5-X14']::text[],true,'{"seq":8,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"걸어서 오는 학생의 비율이 늘었어요","correct":true},{"t":"걸어서 오는 학생 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"걸어서 오는 학생이 5명 늘었어요","mis":"M6-1-u5-X14"},{"t":"전체 학생 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."],"variant_rule":{"alt":[{"stem":"작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"용돈에서 저금이 차지하는 비율이 줄었어요","correct":true},{"t":"저금한 금액이 줄었어요","mis":"M6-1-u5-X02"},{"t":"저금한 금액이 5원 줄었어요","mis":"M6-1-u5-X14"},{"t":"용돈이 줄었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]},{"stem":"작년에는 도서관에서 빌린 책 가운데 과학책이 20 %, 올해는 28 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"빌린 책에서 과학책이 차지하는 비율이 늘었어요","correct":true},{"t":"빌린 과학책 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"과학책을 8권 더 빌렸어요","mis":"M6-1-u5-X14"},{"t":"빌린 책 전체 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#9','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',2,'ox','auto','원그래프로 각 항목의 정확한 수를 비교할 수 있어요.',ARRAY['M6-1-u5-X11']::text[],true,'{"seq":9,"concept":"M6-1-u5-C6","difficulty":2,"kind":"ox","stem":"원그래프로 각 항목의 정확한 수를 비교할 수 있어요.","answer":"X","reason_options":[{"t":"원그래프는 비율만 보여 주고 수는 전체를 알아야 하기 때문에","correct":true},{"t":"조각이 클수록 수가 정확히 보이기 때문에","mis":"M6-1-u5-X11"}],"mis":"M6-1-u5-X11","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"막대그래프로도 전체에 대한 비율이 한눈에 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 수의 크기를 보여 주기 때문에","correct":true},{"t":"막대 끝이 모두 100에 닿기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.","answer":"X","reason_options":[{"t":"전체 수가 줄었다면 수는 줄었을 수도 있기 때문에","correct":true},{"t":"비율이 늘면 수는 언제나 늘기 때문에","mis":"M6-1-u5-X02"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_basic#10','math',6,1,'u5','L06','g6_1_math_u5_L06_basic','lesson_basic','M6-1-u5-C6',3,'error','auto','「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C6","difficulty":3,"kind":"error","stem":"「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「원그래프로 그리면 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"도윤 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","하린은 목적에 맞지 않는 그래프를 골랐어요."],"variant_rule":{"alt":[{"stem":"「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「띠그래프로 그리면 온도 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"예준 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","수아는 목적에 맞지 않는 그래프를 골랐어요."]},{"stem":"「우리 반 학생들이 좋아하는 운동의 비율」을 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꺾은선그래프로 그리면 비율이 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"유진 — 「원그래프나 띠그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 전체에 대한 비율이에요.","전체에 대한 비율은 띠그래프·원그래프가 가장 잘 보여 줘요.","가온은 목적에 맞지 않는 그래프를 골랐어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#1','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',2,'mc','auto','마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":1,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"마을별 사과 생산량을 그림으로 한눈에 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"그림그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「그림그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#2','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',2,'mc','auto','가 반은 30명, 나 반은 60명이에요. 두 반 모두 안경을 쓴 학생의 비율이 30 %예요. 안경을 쓴 학생 수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"가 반은 30명, 나 반은 60명이에요. 두 반 모두 안경을 쓴 학생의 비율이 30 %예요. 안경을 쓴 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가 반은 30 × 30 % = 9, 나 반은 60 × 30 % = 18이에요.","그래서 나 반이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 반은 40명, 나 반은 80명이에요. 두 반 모두 걸어서 오는 학생의 비율이 25 %예요. 걸어서 오는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가 반은 40 × 25 % = 10, 나 반은 80 × 25 % = 20이에요.","그래서 나 반이 더 많아요."]},{"stem":"가 반은 20명, 나 반은 50명이에요. 두 반 모두 줄넘기를 하는 학생의 비율이 40 %예요. 줄넘기를 하는 학생 수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 반이 더 많아요","correct":true},{"t":"두 반이 같아요","mis":"M6-1-u5-X01"},{"t":"가 반이 더 많아요","mis":"M6-1-u5-X15"},{"t":"비율이 같아 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가 반은 20 × 40 % = 8, 나 반은 50 × 40 % = 20이에요.","그래서 나 반이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#3','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]},{"stem":"가 학교 학생 300명 가운데 40 %, 나 학교 학생 500명 가운데 30 %가 걸어서 와요. 걸어서 오는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 300 × 40 % = 120(명)이에요.","나 학교는 500 × 30 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#4','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?',ARRAY['M6-1-u5-X02','M6-1-u5-X14']::text[],true,'{"seq":4,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"작년에는 용돈 가운데 저금이 30 %, 올해는 25 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"용돈에서 저금이 차지하는 비율이 줄었어요","correct":true},{"t":"저금한 금액이 줄었어요","mis":"M6-1-u5-X02"},{"t":"저금한 금액이 5원 줄었어요","mis":"M6-1-u5-X14"},{"t":"용돈이 줄었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."],"variant_rule":{"alt":[{"stem":"작년에는 도서관에서 빌린 책 가운데 과학책이 20 %, 올해는 28 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"빌린 책에서 과학책이 차지하는 비율이 늘었어요","correct":true},{"t":"빌린 과학책 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"과학책을 8권 더 빌렸어요","mis":"M6-1-u5-X14"},{"t":"빌린 책 전체 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]},{"stem":"작년에는 우리 학교 학생 가운데 걸어서 오는 학생이 40 %, 올해는 45 %예요. 이것만 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"걸어서 오는 학생의 비율이 늘었어요","correct":true},{"t":"걸어서 오는 학생 수가 늘었어요","mis":"M6-1-u5-X02"},{"t":"걸어서 오는 학생이 5명 늘었어요","mis":"M6-1-u5-X14"},{"t":"전체 학생 수가 늘었어요","mis":"M6-1-u5-X02"}],"explanation":["두 해의 백분율은 각 해의 전체에 대한 비율이에요.","전체 수가 달라질 수 있어 실제 수가 늘었는지 줄었는지는 알 수 없어요.","알 수 있는 것은 비율의 변화뿐이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#5','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'error','auto','「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C6","difficulty":3,"kind":"error","stem":"「하루 동안 교실 온도의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「띠그래프로 그리면 온도 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"예준 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","수아는 목적에 맞지 않는 그래프를 골랐어요."],"variant_rule":{"alt":[{"stem":"「우리 반 학생들이 좋아하는 운동의 비율」을 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꺾은선그래프로 그리면 비율이 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"유진 — 「원그래프나 띠그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 전체에 대한 비율이에요.","전체에 대한 비율은 띠그래프·원그래프가 가장 잘 보여 줘요.","가온은 목적에 맞지 않는 그래프를 골랐어요."]},{"stem":"「6개월 동안 우리 반 독서량의 변화」를 그래프로 나타내려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「원그래프로 그리면 변화가 잘 보여.」","correct":true,"mis_target":"M6-1-u5-X10"},{"t":"시우 — 「꺾은선그래프가 알맞아.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「먼저 무엇을 보여 줄지 정해야 해.」","mis":"M6-1-u5-X16"}],"explanation":["보여 주고 싶은 것은 시간에 따른 변화예요.","시간에 따른 변화는 꺾은선그래프가 가장 잘 보여 줘요.","여울은 목적에 맞지 않는 그래프를 골랐어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#6','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'ox','auto','작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.',ARRAY['M6-1-u5-X02']::text[],true,'{"seq":6,"concept":"M6-1-u5-C6","difficulty":3,"kind":"ox","stem":"작년보다 올해 비율이 늘었다면 그 항목의 수도 반드시 늘었어요.","answer":"X","reason_options":[{"t":"전체 수가 줄었다면 수는 줄었을 수도 있기 때문에","correct":true},{"t":"비율이 늘면 수는 언제나 늘기 때문에","mis":"M6-1-u5-X02"}],"mis":"M6-1-u5-X02","explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."],"variant_rule":{"alt":[{"stem":"원그래프로 각 항목의 정확한 수를 비교할 수 있어요.","answer":"X","reason_options":[{"t":"원그래프는 비율만 보여 주고 수는 전체를 알아야 하기 때문에","correct":true},{"t":"조각이 클수록 수가 정확히 보이기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]},{"stem":"막대그래프로도 전체에 대한 비율이 한눈에 보여요.","answer":"X","reason_options":[{"t":"막대그래프는 수의 크기를 보여 주기 때문에","correct":true},{"t":"막대 끝이 모두 100에 닿기 때문에","mis":"M6-1-u5-X11"}],"explanation":["막대는 수, 꺾은선은 변화, 띠·원은 비율을 잘 보여 줘요.","비율그래프만으로는 실제 수를 몰라요.","목적을 먼저 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#7','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',3,'mc','auto','올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":7,"concept":"M6-1-u5-C6","difficulty":3,"kind":"mc","stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."],"variant_rule":{"alt":[{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]},{"stem":"그래프를 고를 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"무엇을 보여 주고 싶은지(목적)","correct":true},{"t":"무슨 색을 칠할지","mis":"M6-1-u5-X16"},{"t":"그래프 이름의 글자 수","mis":"M6-1-u5-X16"},{"t":"그래프를 그린 사람","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「무엇을 보여 주고 싶은지(목적)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#8','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'mc','auto','가 학교 학생 250명 가운데 20 %, 나 학교 학생 400명 가운데 15 %가 안경을 써요. 안경을 쓰는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":8,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 250명 가운데 20 %, 나 학교 학생 400명 가운데 15 %가 안경을 써요. 안경을 쓰는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 250 × 20 % = 50(명)이에요.","나 학교는 400 × 15 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#9','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'sa','auto','독서를 좋아하는 학생은 12명이고, 이것은 전체의 30 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C6","difficulty":4,"kind":"sa","stem":"독서를 좋아하는 학생은 12명이고, 이것은 전체의 30 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 30 % = 12예요.","1 %는 12 ÷ 30 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"강아지를 키우는 학생은 9명이고, 이것은 전체의 25 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["전체 × 25 % = 9예요.","1 %는 9 ÷ 25 = 0.36이고 전체 100 %는 그 100배예요.","0.36 × 100 = 36 — 전체는 36명이에요."]},{"stem":"자전거를 타는 학생은 14명이고, 이것은 전체의 35 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 35 % = 14예요.","1 %는 14 ÷ 35 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L06_challenge#10','math',6,1,'u5','L06','g6_1_math_u5_L06_challenge','lesson_challenge','M6-1-u5-C6',4,'essay','teacher','「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 6개월 동안 읽은 책의 수 변화는 시간에 따른 변화이므로 꺾은선그래프가 알맞다. 이번 달 책의 종류별 비율은 전체에 대한 부분의 비율이므로 띠그래프나 원그래프가 알맞다. 보여 주고 싶은 것(목적)에 따라 그래프를 고른다.","scoring_points":["변화 → 꺾은선그래프를 골랐는가","비율 → 띠그래프·원그래프를 골랐는가","목적에 따라 고른다는 까닭을 썼는가"]},"explanation":["변화는 꺾은선그래프예요.","비율은 띠그래프·원그래프예요.","목적이 그래프를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#1','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','통계적 문제 해결의 첫 단계는 무엇인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."],"variant_rule":{"alt":[{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#2','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','통계적 탐구 문제로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":2,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 탄소 중립을 몇 개나 실천할까?","correct":true},{"t":"1 + 1은 얼마일까?","mis":"M6-1-u5-X13"},{"t":"3의 배수는 무엇일까?","mis":"M6-1-u5-X13"},{"t":"어제 날씨는 어땠을까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 반 친구들은 탄소 중립을 몇 개나 실천할까?」가 알맞아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반 친구들은 어떤 운동을 가장 좋아할까?","correct":true},{"t":"축구공은 무슨 모양일까?","mis":"M6-1-u5-X13"},{"t":"10을 2로 나누면 얼마일까?","mis":"M6-1-u5-X13"},{"t":"지금 몇 시일까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 반 친구들은 어떤 운동을 가장 좋아할까?」가 알맞아요."]},{"stem":"이번에는 다른 보기예요. 통계적 탐구 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 학교 학생들은 주로 어떻게 학교에 올까?","correct":true},{"t":"학교는 몇 층일까?","mis":"M6-1-u5-X13"},{"t":"오늘은 무슨 요일일까?","mis":"M6-1-u5-X13"},{"t":"5 × 6은 얼마일까?","mis":"M6-1-u5-X13"}],"explanation":["통계적 탐구 문제는 자료를 모아야 답할 수 있는 질문이에요.","여러 사람의 답이 다를 수 있어야 자료를 모으고 분석할 수 있어요.","그래서 「우리 학교 학생들은 주로 어떻게 학교에 올까?」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#3','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'mc','auto','탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":3,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"3개","correct":true},{"t":"1개 이하","mis":"M6-1-u5-X16"},{"t":"2개","mis":"M6-1-u5-X07"},{"t":"4개","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","3개가 37 %로 가장 커요.","그래서 답은 3개예요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"걷기","correct":true},{"t":"자동차","mis":"M6-1-u5-X16"},{"t":"버스","mis":"M6-1-u5-X07"},{"t":"자전거","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","걷기가 44 %로 가장 커요.","그래서 답은 걷기예요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"먹고 싶은 간식 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"떡볶이","correct":true},{"t":"과자","mis":"M6-1-u5-X16"},{"t":"과일","mis":"M6-1-u5-X07"},{"t":"빵","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","떡볶이가 35 %로 가장 커요.","그래서 답은 떡볶이예요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#4','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',1,'ox','auto','통계적 문제 해결은 자료 수집부터 시작해요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":1,"kind":"ox","stem":"통계적 문제 해결은 자료 수집부터 시작해요.","answer":"X","reason_options":[{"t":"무엇이 궁금한지 문제를 먼저 정해야 하기 때문에","correct":true},{"t":"자료가 있어야 문제를 정할 수 있기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"「1 + 1은 얼마일까?」는 통계적 탐구 문제로 알맞아요.","answer":"X","reason_options":[{"t":"자료를 모으지 않아도 답이 하나로 정해지기 때문에","correct":true},{"t":"수가 들어 있는 문제이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#5','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'sa','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C7","difficulty":2,"kind":"sa","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["4개는 18 %, 5개 이상은 14 %예요.","18 % + 14 % = 32 %예요.","답은 32예요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 2개와 3개를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["2개는 19 %, 3개는 37 %예요.","19 % + 37 % = 56 %예요.","답은 56이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 1개 이하와 5개 이상을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["1개 이하는 12 %, 5개 이상은 14 %예요.","12 % + 14 % = 26 %예요.","답은 26이에요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#6','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제 제기 → 자료 수집 → 자료 분석 → 결과 해석","correct":true},{"t":"자료 수집 → 문제 제기 → 자료 분석 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"문제 제기 → 자료 분석 → 자료 수집 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"자료 수집 → 자료 분석 → 결과 해석 → 문제 제기","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기 → 자료 수집 → 자료 분석 → 결과 해석」이에요."]},{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#7','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 중립 실천 방법을 더 알리고 함께 실천해요","correct":true},{"t":"조사를 그만둬요","mis":"M6-1-u5-X13"},{"t":"그래프를 다시 그려요","mis":"M6-1-u5-X13"},{"t":"아무것도 하지 않아요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「탄소 중립 실천 방법을 더 알리고 함께 실천해요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"등굣길 안전 지도를 만들어 함께 살펴봐요","correct":true},{"t":"걸어서 오는 학생 수를 다시 세지 않아요","mis":"M6-1-u5-X13"},{"t":"그래프 색을 바꿔요","mis":"M6-1-u5-X13"},{"t":"결과를 숨겨요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「등굣길 안전 지도를 만들어 함께 살펴봐요」가 알맞아요."]},{"stem":"먹고 싶은 간식 조사에서 떡볶이가 35 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"학급 행사 간식으로 떡볶이를 먼저 생각해요","correct":true},{"t":"조사를 처음부터 다시 해요","mis":"M6-1-u5-X13"},{"t":"가장 적은 간식만 준비해요","mis":"M6-1-u5-X16"},{"t":"그래프를 버려요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「학급 행사 간식으로 떡볶이를 먼저 생각해요」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#8','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'mc','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?',ARRAY['M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":8,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["18 + 14 = 32예요.","절반은 50 %예요.","32 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 2개와 3개를 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["19 + 37 = 56이에요.","절반은 50 %예요.","56 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"학교에 오는 방법 조사를 원그래프로 나타냈어요. 걷기는 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["걷기는 44 %예요.","절반은 50 %예요.","44 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#9','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',2,'ox','auto','결과 해석에서 찾은 답을 실천 계획으로 이을 수 있어요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":9,"concept":"M6-1-u5-C7","difficulty":2,"kind":"ox","stem":"결과 해석에서 찾은 답을 실천 계획으로 이을 수 있어요.","answer":"O","reason_options":[{"t":"탐구한 답을 생활에서 쓰는 것이 마지막이기 때문에","correct":true},{"t":"해석한 뒤에는 할 일이 없기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"4개 18 %, 5개 이상 14 %이면 4개 이상은 32 %예요.","answer":"O","reason_options":[{"t":"18 + 14 = 32이기 때문에","correct":true},{"t":"18 × 14를 해야 하기 때문에","mis":"M6-1-u5-X15"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"그래프만 그리면 탐구 문제의 답을 저절로 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프를 읽고 해석해야 답을 얻기 때문에","correct":true},{"t":"그래프에 답이 적혀 있기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_basic#10','math',6,1,'u5','L07','g6_1_math_u5_L07_basic','lesson_basic','M6-1-u5-C7',3,'error','auto','「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X13','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C7","difficulty":3,"kind":"error","stem":"「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「먼저 그래프부터 그리고 나서 무엇을 조사할지 정하자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"도윤 — 「실천 개수를 손 들기로 모으자.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「모은 자료로 원그래프를 그려 분석하자.」","mis":"M6-1-u5-X16"}],"explanation":["탐구 문제를 정하는 것이 첫 단계예요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","하린은 단계를 바꾸거나 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자료를 모았으니 표나 그래프 없이 바로 결론을 내자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"예준 — 「좋아하는 운동을 붙임딱지로 모으자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「모은 자료로 띠그래프를 그려 보자.」","mis":"M6-1-u5-X16"}],"explanation":["모은 자료는 표·그래프로 분석한 뒤에 해석해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","수아는 단계를 바꾸거나 빠뜨렸어요."]},{"stem":"「우리 학교 학생들은 어떻게 학교에 올까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「그래프를 그렸으니 해석은 하지 않아도 돼.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"유진 — 「학교에 오는 방법을 조사해 표로 정리하자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「그래프를 보고 알게 된 것을 실천으로 이어 보자.」","mis":"M6-1-u5-X16"}],"explanation":["그래프를 그린 뒤에는 해석해서 답을 찾아야 해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","가온은 단계를 바꾸거나 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#1','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',2,'mc','auto','통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":1,"concept":"M6-1-u5-C7","difficulty":2,"kind":"mc","stem":"통계적 문제 해결의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"문제 제기 → 자료 수집 → 자료 분석 → 결과 해석","correct":true},{"t":"자료 수집 → 문제 제기 → 자료 분석 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"문제 제기 → 자료 분석 → 자료 수집 → 결과 해석","mis":"M6-1-u5-X13"},{"t":"자료 수집 → 자료 분석 → 결과 해석 → 문제 제기","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기 → 자료 수집 → 자료 분석 → 결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]},{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#2','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',2,'sa','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 조사한 전체는 25명이에요. 3개는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C7","difficulty":2,"kind":"sa","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 조사한 전체는 25명이에요. 3개는 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["3개는 36 %예요.","25 × 36 % = 9예요.","3개는 9명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 버스는 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["버스는 24 %예요.","50 × 24 % = 12예요.","버스는 12명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 조사한 전체는 40명이에요. 과일은 몇 명인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["과일은 30 %예요.","40 × 30 % = 12예요.","과일은 12명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#3','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'mc','auto','탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개와 4개를 합하면 전체의 절반보다 많은가요, 적은가요?',ARRAY['M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":3,"concept":"M6-1-u5-C7","difficulty":3,"kind":"mc","stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 3개와 4개를 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["37 + 18 = 55예요.","절반은 50 %예요.","55 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"탄소 중립 실천 개수 조사를 원그래프로 나타냈어요. 1개 이하, 2개와 5개 이상을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 적어요","correct":true},{"t":"절반보다 많아요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["12 + 19 + 14 = 45예요.","절반은 50 %예요.","45 %는 절반보다 적어요."],"asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",19],["3개",37],["4개",18],["5개 이상",14]],"title":"탄소 중립 실천 개수"}},{"stem":"먹고 싶은 간식 조사를 원그래프로 나타냈어요. 떡볶이와 빵을 합하면 전체의 절반보다 많은가요, 적은가요?","options":[{"t":"절반보다 많아요","correct":true},{"t":"절반보다 적어요","mis":"M6-1-u5-X15"},{"t":"꼭 절반이에요","mis":"M6-1-u5-X15"},{"t":"비율로는 알 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["35 + 20 = 55예요.","절반은 50 %예요.","55 %는 절반보다 많아요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#4','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'mc','auto','우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":3,"kind":"mc","stem":"우리 반에서 걸어서 오는 학생이 44 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"등굣길 안전 지도를 만들어 함께 살펴봐요","correct":true},{"t":"걸어서 오는 학생 수를 다시 세지 않아요","mis":"M6-1-u5-X13"},{"t":"그래프 색을 바꿔요","mis":"M6-1-u5-X13"},{"t":"결과를 숨겨요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「등굣길 안전 지도를 만들어 함께 살펴봐요」가 알맞아요."],"variant_rule":{"alt":[{"stem":"먹고 싶은 간식 조사에서 떡볶이가 35 %로 가장 많았어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"학급 행사 간식으로 떡볶이를 먼저 생각해요","correct":true},{"t":"조사를 처음부터 다시 해요","mis":"M6-1-u5-X13"},{"t":"가장 적은 간식만 준비해요","mis":"M6-1-u5-X16"},{"t":"그래프를 버려요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「학급 행사 간식으로 떡볶이를 먼저 생각해요」가 알맞아요."]},{"stem":"탄소 중립을 4개 이상 실천하는 학생이 32 %로 절반보다 적었어요. 이 결과를 보고 세운 계획으로 알맞은 것은 어느 것인가요?","options":[{"t":"탄소 중립 실천 방법을 더 알리고 함께 실천해요","correct":true},{"t":"조사를 그만둬요","mis":"M6-1-u5-X13"},{"t":"그래프를 다시 그려요","mis":"M6-1-u5-X13"},{"t":"아무것도 하지 않아요","mis":"M6-1-u5-X13"}],"explanation":["결과 해석은 그래프를 보고 탐구 문제의 답을 찾는 단계예요.","찾은 답을 생활 속 실천 계획으로 이어요.","그래서 「탄소 중립 실천 방법을 더 알리고 함께 실천해요」가 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#5','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'error','auto','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X13','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C7","difficulty":3,"kind":"error","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「자료를 모았으니 표나 그래프 없이 바로 결론을 내자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"예준 — 「좋아하는 운동을 붙임딱지로 모으자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「모은 자료로 띠그래프를 그려 보자.」","mis":"M6-1-u5-X16"}],"explanation":["모은 자료는 표·그래프로 분석한 뒤에 해석해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","수아는 단계를 바꾸거나 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"「우리 학교 학생들은 어떻게 학교에 올까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「그래프를 그렸으니 해석은 하지 않아도 돼.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"유진 — 「학교에 오는 방법을 조사해 표로 정리하자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「그래프를 보고 알게 된 것을 실천으로 이어 보자.」","mis":"M6-1-u5-X16"}],"explanation":["그래프를 그린 뒤에는 해석해서 답을 찾아야 해요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","가온은 단계를 바꾸거나 빠뜨렸어요."]},{"stem":"「우리 반은 탄소 중립을 몇 개나 실천할까?」를 탐구하려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「먼저 그래프부터 그리고 나서 무엇을 조사할지 정하자.」","correct":true,"mis_target":"M6-1-u5-X13"},{"t":"시우 — 「실천 개수를 손 들기로 모으자.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「모은 자료로 원그래프를 그려 분석하자.」","mis":"M6-1-u5-X16"}],"explanation":["탐구 문제를 정하는 것이 첫 단계예요.","문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 차례를 지켜요.","여울은 단계를 바꾸거나 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#6','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'ox','auto','통계적 문제 해결은 자료 수집부터 시작해요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C7","difficulty":3,"kind":"ox","stem":"통계적 문제 해결은 자료 수집부터 시작해요.","answer":"X","reason_options":[{"t":"무엇이 궁금한지 문제를 먼저 정해야 하기 때문에","correct":true},{"t":"자료가 있어야 문제를 정할 수 있기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"그래프만 그리면 탐구 문제의 답을 저절로 알 수 있어요.","answer":"X","reason_options":[{"t":"그래프를 읽고 해석해야 답을 얻기 때문에","correct":true},{"t":"그래프에 답이 적혀 있기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"「1 + 1은 얼마일까?」는 통계적 탐구 문제로 알맞아요.","answer":"X","reason_options":[{"t":"자료를 모으지 않아도 답이 하나로 정해지기 때문에","correct":true},{"t":"수가 들어 있는 문제이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#7','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',3,'sa','auto','탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈는데 2개의 백분율이 지워졌어요. 2개는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":3,"kind":"sa","stem":"탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈는데 2개의 백분율이 지워졌어요. 2개는 몇 명인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2개의 백분율은 100 − (12 + 36 + 20 + 12) = 20이에요.","25 × 20 % = 5예요.","2개는 5명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수","hide":[1]},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사(전체 50명)를 원그래프로 나타냈는데 자전거의 백분율이 지워졌어요. 자전거는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["자전거의 백분율은 100 − (44 + 24 + 12) = 20이에요.","50 × 20 % = 10이에요.","자전거는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법","hide":[2]}},{"stem":"먹고 싶은 간식 조사(전체 40명)를 원그래프로 나타냈는데 빵의 백분율이 지워졌어요. 빵은 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["빵의 백분율은 100 − (35 + 30 + 15) = 20이에요.","40 × 20 % = 8이에요.","빵은 8명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["떡볶이",35],["과일",30],["빵",20],["과자",15]],"title":"먹고 싶은 간식","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#8','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'sa','auto','탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C7","difficulty":4,"kind":"sa","stem":"탄소 중립 실천 개수 조사(전체 25명)를 원그래프로 나타냈어요. 4개와 5개 이상을 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["20 % + 12 % = 32 %예요.","25 × 32 % = 8이에요.","모두 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["1개 이하",12],["2개",20],["3개",36],["4개",20],["5개 이상",12]],"title":"탄소 중립 실천 개수"},"variant_rule":{"alt":[{"stem":"학교에 오는 방법 조사(전체 50명)를 원그래프로 나타냈어요. 버스와 자동차를 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["24 % + 12 % = 36 %예요.","50 × 36 % = 18이에요.","모두 18명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["걷기",44],["버스",24],["자전거",20],["자동차",12]],"title":"학교에 오는 방법"}},{"stem":"들고 싶은 동아리 조사(전체 50명)를 원그래프로 나타냈어요. 과학과 독서를 합하면 모두 몇 명인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["22 % + 14 % = 36 %예요.","50 × 36 % = 18이에요.","모두 18명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["합창",36],["미술",28],["과학",22],["독서",14]],"title":"들고 싶은 동아리"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#9','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'sa','auto','3개를 실천한 학생은 9명이고, 이것은 전체의 36 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C7","difficulty":4,"kind":"sa","stem":"3개를 실천한 학생은 9명이고, 이것은 전체의 36 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["전체 × 36 % = 9예요.","1 %는 9 ÷ 36 = 0.25이고 전체 100 %는 그 100배예요.","0.25 × 100 = 25 — 전체는 25명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"버스로 오는 학생은 12명이고, 이것은 전체의 24 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["전체 × 24 % = 12예요.","1 %는 12 ÷ 24 = 0.5이고 전체 100 %는 그 100배예요.","0.5 × 100 = 50 — 전체는 50명이에요."]},{"stem":"떡볶이를 고른 학생은 14명이고, 이것은 전체의 35 %예요. 전체는 몇 명인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["전체 × 35 % = 14예요.","1 %는 14 ÷ 35 = 0.4이고 전체 100 %는 그 100배예요.","0.4 × 100 = 40 — 전체는 40명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L07_challenge#10','math',6,1,'u5','L07','g6_1_math_u5_L07_challenge','lesson_challenge','M6-1-u5-C7',4,'essay','teacher','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C7","difficulty":4,"kind":"essay","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.","answer_guide":{"answer":"예: ① 문제 제기 — 탐구 문제를 정한다. ② 자료 수집 — 좋아하는 운동을 붙임딱지나 손 들기로 모은다. ③ 자료 분석 — 표로 정리해 백분율을 구하고 원그래프로 나타낸다. ④ 결과 해석 — 가장 많은 운동을 찾아 체육 시간이나 학급 행사 계획에 쓴다.","scoring_points":["네 단계를 차례대로 썼는가","자료 수집 방법을 구체적으로 썼는가","분석(표·그래프)과 해석(실천)을 구분했는가"]},"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석이에요.","분석은 표·그래프로 정리하는 일이에요.","해석한 결과를 실천으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#1','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'mc','auto','띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":1,"concept":"M6-1-u5-C8","difficulty":1,"kind":"mc","stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."],"variant_rule":{"alt":[{"stem":"비율그래프가 바르게 그려졌는지 확인하는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"색이 예쁜지 봐요","correct":true},{"t":"백분율의 합이 100인지 봐요","mis":"M6-1-u5-X16"},{"t":"칸의 길이가 백분율과 맞는지 봐요","mis":"M6-1-u5-X16"},{"t":"제목과 내용이 있는지 봐요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「색이 예쁜지 봐요」예요."]},{"stem":"잘못 그린 그래프를 그대로 쓰면 어떤 문제가 생기나요?","options":[{"t":"사실과 다르게 보여 틀린 판단을 하게 돼요","correct":true},{"t":"아무 문제도 없어요","mis":"M6-1-u5-X03"},{"t":"색이 모자라요","mis":"M6-1-u5-X16"},{"t":"종이가 아까워요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「사실과 다르게 보여 틀린 판단을 하게 돼요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#2','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#3','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'sa','auto','띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["모든 항목의 합은 100 %예요.","100 − 90 = 10이에요.","기타는 10 %여야 해요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 90 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["10"],"explanation":["모든 항목의 합은 100 %예요.","100 − 90 = 10이에요.","기타는 10 %여야 해요."]},{"stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 85 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 합은 100 %예요.","100 − 85 = 15예요.","기타는 15 %여야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#4','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',1,'ox','auto','비율그래프는 백분율의 합이 100 %인지 검토해야 해요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C8","difficulty":1,"kind":"ox","stem":"비율그래프는 백분율의 합이 100 %인지 검토해야 해요.","answer":"O","reason_options":[{"t":"전체가 100 %이기 때문에","correct":true},{"t":"합은 아무래도 상관없기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"칸의 길이가 백분율과 맞는지도 확인해야 해요.","answer":"O","reason_options":[{"t":"길이가 비율을 나타내기 때문에","correct":true},{"t":"길이는 아무렇게나 그려도 되기 때문에","mis":"M6-1-u5-X07"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"잘못 그린 그래프는 고쳐서 다시 그려야 해요.","answer":"O","reason_options":[{"t":"잘못된 그래프는 사실을 왜곡하기 때문에","correct":true},{"t":"한 번 그린 그래프는 고칠 수 없기 때문에","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#5','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','친구가 장래 희망 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16','M6-1-u5-X03']::text[],true,'{"seq":5,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"친구가 장래 희망 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 빌린 책의 종류 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["35 + 25 + 20 + 10 + 5 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["30 + 25 + 20 + 10 + 10 = 95예요.","띠 전체가 100 %인데 합이 95라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#6','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#7','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','장래 희망 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":7,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"장래 희망 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"운동선수","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"의사","mis":"M6-1-u5-X07"},{"t":"예술가","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","운동선수가 30 %로 가장 커요.","그래서 답은 운동선수예요."],"asset":{"type":"pgr","kind":"band","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",10]],"title":"장래 희망"},"variant_rule":{"alt":[{"stem":"빌린 책의 종류 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"동화","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"과학","mis":"M6-1-u5-X07"},{"t":"역사","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","동화가 35 %로 가장 커요.","그래서 답은 동화예요."],"asset":{"type":"pgr","kind":"band","items":[["동화",35],["과학",25],["역사",20],["만화",15],["기타",5]],"title":"빌린 책의 종류"}},{"stem":"용돈 쓰임 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"저금","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"간식","mis":"M6-1-u5-X07"},{"t":"학용품","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","저금이 35 %로 가장 커요.","그래서 답은 저금이에요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#8','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'mc','auto','띠그래프에 운동선수 30 %, 의사 25 %라고 적혀 있는데 의사 칸이 운동선수 칸보다 길어요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X07']::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"띠그래프에 운동선수 30 %, 의사 25 %라고 적혀 있는데 의사 칸이 운동선수 칸보다 길어요. 무엇이 잘못되었나요?","options":[{"t":"칸의 길이가 백분율과 맞지 않아요","correct":true},{"t":"백분율의 합이 100이 아니에요","mis":"M6-1-u5-X03"},{"t":"의사 칸을 앞에 그려야 해요","mis":"M6-1-u5-X07"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X07"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「칸의 길이가 백분율과 맞지 않아요」예요."],"variant_rule":{"alt":[{"stem":"비율그래프가 바르게 그려졌는지 확인하는 방법으로 옳지 않은 것은 어느 것인가요?","options":[{"t":"색이 예쁜지 봐요","correct":true},{"t":"백분율의 합이 100인지 봐요","mis":"M6-1-u5-X16"},{"t":"칸의 길이가 백분율과 맞는지 봐요","mis":"M6-1-u5-X16"},{"t":"제목과 내용이 있는지 봐요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「색이 예쁜지 봐요」예요."]},{"stem":"잘못 그린 그래프를 그대로 쓰면 어떤 문제가 생기나요?","options":[{"t":"사실과 다르게 보여 틀린 판단을 하게 돼요","correct":true},{"t":"아무 문제도 없어요","mis":"M6-1-u5-X03"},{"t":"색이 모자라요","mis":"M6-1-u5-X16"},{"t":"종이가 아까워요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「사실과 다르게 보여 틀린 판단을 하게 돼요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#9','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',2,'ox','auto','백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":9,"concept":"M6-1-u5-C8","difficulty":2,"kind":"ox","stem":"백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.","answer":"X","reason_options":[{"t":"합이 100 %가 아니면 어떤 값이 잘못되었기 때문에","correct":true},{"t":"합이 100에 가까우면 괜찮기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.","answer":"X","reason_options":[{"t":"바른 그래프인지는 합과 길이로 확인하기 때문에","correct":true},{"t":"색이 예쁘면 값도 맞기 때문에","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"다른 항목의 합이 90 %이면 기타는 10 %예요.","answer":"O","reason_options":[{"t":"100 − 90 = 10이기 때문에","correct":true},{"t":"90 ÷ 9 = 10이기 때문에","mis":"M6-1-u5-X15"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_basic#10','math',6,1,'u5','L08','g6_1_math_u5_L08_basic','lesson_basic','M6-1-u5-C8',3,'error','auto','장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":10,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"도윤 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","하린은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"빌린 책의 종류 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"예준 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","수아는 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"소개하고 싶은 문화유산 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#1','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',2,'sa','auto','친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 45 %, 30 %, 20 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["45 + 30 + 20 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 33 %, 27 %, 19 %, 14 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["93"],"explanation":["33 + 27 + 19 + 14 = 93이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 93이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#2','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',2,'sa','auto','띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u5-C8","difficulty":2,"kind":"sa","stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["모든 항목의 합은 100 %예요.","100 − 88 = 12예요.","기타는 12 %여야 해요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 82 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["18"],"explanation":["모든 항목의 합은 100 %예요.","100 − 82 = 18이에요.","기타는 18 %여야 해요."]},{"stem":"이번에는 다른 보기예요. 띠그래프에서 기타를 뺀 나머지 항목의 백분율 합이 88 %예요. 합이 100 %가 되려면 기타는 몇 %여야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["모든 항목의 합은 100 %예요.","100 − 88 = 12예요.","기타는 12 %여야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#3','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 의사 칸만 잘못 적혔어요. 의사의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 의사 칸만 잘못 적혔어요. 의사의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["의사를 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","의사는 25 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",15],["예술가",20],["선생님",15],["기타",10]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 마을 땅 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 밭 칸만 잘못 적혔어요. 밭의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["밭을 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","밭은 25 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"마을 땅 쓰임","items":[["논",40],["밭",15],["과수원",20],["기타",15]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#4','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'mc','auto','친구가 좋아하는 계절 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?',ARRAY['M6-1-u5-X07','M6-1-u5-X16','M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C8","difficulty":3,"kind":"mc","stem":"친구가 좋아하는 계절 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["32 + 28 + 24 + 6 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"좋아하는 계절","items":[["봄",32],["가을",28],["여름",24],["겨울",6]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 들고 싶은 동아리 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["36 + 28 + 12 + 14 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"들고 싶은 동아리","items":[["합창",36],["미술",28],["과학",12],["독서",14]],"bad":true}},{"stem":"친구가 마을 땅 쓰임 조사를 띠그래프로 나타냈어요. 이 띠그래프에서 잘못된 점은 무엇인가요?","options":[{"t":"백분율의 합이 100 %가 아니에요","correct":true},{"t":"가장 긴 칸이 맨 앞에 있어요","mis":"M6-1-u5-X07"},{"t":"항목이 너무 많아요","mis":"M6-1-u5-X16"},{"t":"잘못된 곳이 없어요","mis":"M6-1-u5-X03"}],"explanation":["40 + 25 + 20 + 5 = 90이에요.","띠 전체가 100 %인데 합이 90이라 띠 끝이 비었어요.","어떤 항목의 백분율이 잘못 적혔어요."],"asset":{"type":"pgr","kind":"band","title":"마을 땅 쓰임","items":[["논",40],["밭",25],["과수원",20],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#5','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'error','auto','좋아하는 계절 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":5,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"좋아하는 계절 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"예준 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","수아는 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"좋아하는 계절","items":[["봄",32],["가을",28],["여름",24],["겨울",6]],"bad":true},"variant_rule":{"alt":[{"stem":"들고 싶은 동아리 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"들고 싶은 동아리","items":[["합창",36],["미술",28],["과학",12],["독서",14]],"bad":true}},{"stem":"용돈 쓰임 띠그래프의 백분율 합이 90 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"시우 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 90 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","여울은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#6','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'ox','auto','그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":6,"concept":"M6-1-u5-C8","difficulty":3,"kind":"ox","stem":"그래프의 색이 예쁜지가 바르게 그렸는지 확인하는 가장 중요한 방법이에요.","answer":"X","reason_options":[{"t":"바른 그래프인지는 합과 길이로 확인하기 때문에","correct":true},{"t":"색이 예쁘면 값도 맞기 때문에","mis":"M6-1-u5-X16"}],"mis":"M6-1-u5-X16","explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."],"variant_rule":{"alt":[{"stem":"백분율의 합이 95 %인 띠그래프는 바르게 그린 그래프예요.","answer":"X","reason_options":[{"t":"합이 100 %가 아니면 어떤 값이 잘못되었기 때문에","correct":true},{"t":"합이 100에 가까우면 괜찮기 때문에","mis":"M6-1-u5-X03"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]},{"stem":"비율그래프는 백분율의 합이 100 %인지 검토해야 해요.","answer":"O","reason_options":[{"t":"전체가 100 %이기 때문에","correct":true},{"t":"합은 아무래도 상관없기 때문에","mis":"M6-1-u5-X03"}],"explanation":["비율그래프는 합이 100인지, 길이가 백분율과 맞는지 검토해요.","잘못된 값은 찾아서 고쳐 다시 그려요.","그래프를 비판적으로 읽어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#7','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',3,'sa','auto','장래 희망 조사를 띠그래프로 나타냈어요. 운동선수의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"장래 희망 조사를 띠그래프로 나타냈어요. 운동선수의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["운동선수는 30 %, 기타는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 10 = 3 — 3배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",10]],"title":"장래 희망"},"variant_rule":{"alt":[{"stem":"용돈 쓰임 조사를 띠그래프로 나타냈어요. 저금의 비율은 기타의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["저금은 35 %, 기타는 5 %예요.","「몇 배」는 나눗셈으로 구해요.","35 ÷ 5 = 7 — 7배예요."],"asset":{"type":"pgr","kind":"band","items":[["저금",35],["간식",25],["학용품",20],["선물",15],["기타",5]],"title":"용돈 쓰임"}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈어요. 논의 비율은 과수원의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["논은 40 %, 과수원은 20 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 20 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#8','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 기타 칸만 잘못 적혔고 조사한 전체는 20명이에요. 기타는 실제로 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":4,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 기타 칸만 잘못 적혔고 조사한 전체는 20명이에요. 기타는 실제로 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["기타의 바른 백분율은 100 − 90 = 10이에요.","20 × 10 % = 2예요.","기타는 2명이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 만화 칸만 잘못 적혔고 조사한 전체는 200권이에요. 만화는 실제로 몇 권인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["만화의 바른 백분율은 100 − 85 = 15예요.","200 × 15 % = 30이에요.","만화는 30권이에요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 종묘 칸만 잘못 적혔고 조사한 전체는 20명이에요. 종묘는 실제로 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["종묘의 바른 백분율은 100 − 85 = 15예요.","20 × 15 % = 3이에요.","종묘는 3명이에요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#9','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'sa','auto','친구가 그린 탄소 중립 실천 개수 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 3개 칸만 잘못 적혔어요. 3개의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C8","difficulty":4,"kind":"sa","stem":"친구가 그린 탄소 중립 실천 개수 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 3개 칸만 잘못 적혔어요. 3개의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["3개를 뺀 나머지의 합은 63 %예요.","100 − 63 = 37이에요.","3개는 37 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","title":"탄소 중립 실천 개수","items":[["1개 이하",12],["2개",19],["3개",27],["4개",18],["5개 이상",14]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 하루 폐기물 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 건설 칸만 잘못 적혔어요. 건설의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["건설을 뺀 나머지의 합은 62 %예요.","100 − 62 = 38이에요.","건설은 38 %로 고쳐요."],"asset":{"type":"pgr","kind":"pie","title":"하루 폐기물","items":[["사업장",49],["건설",28],["생활",13]],"bad":true}},{"stem":"친구가 그린 용돈 쓰임 원그래프의 합이 100 %가 아니에요. 다시 세어 보니 간식 칸만 잘못 적혔어요. 간식의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["간식을 뺀 나머지의 합은 75 %예요.","100 − 75 = 25예요.","간식은 25 %로 고쳐요."],"asset":{"type":"pgr","kind":"pie","title":"용돈 쓰임","items":[["저금",35],["간식",15],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_L08_challenge#10','math',6,1,'u5','L08','g6_1_math_u5_L08_challenge','lesson_challenge','M6-1-u5-C8',4,'essay','teacher','친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u5-C8","difficulty":4,"kind":"essay","stem":"친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30 + 25 + 20 + 15 + 5 = 95이므로 합이 100 %가 아니다. 어떤 항목의 백분율이 잘못 적힌 것이다. 다시 세어 보니 기타가 틀렸다면 100 − 90 = 10이므로 기타는 10 %이다. 고친 백분율만큼 띠를 다시 나누어 그린다.","scoring_points":["합이 95라 잘못되었다고 찾았는가","기타를 10 %로 고쳤는가","고친 값만큼 다시 그린다고 썼는가"]},"explanation":["합이 95 %예요.","기타는 100 − 90 = 10 — 10 %예요.","고친 값만큼 다시 그려요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#1','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',1,'mc','auto','좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#2','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',1,'mc','auto','전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#3','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',1,'sa','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]},{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#4','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',1,'ox','auto','띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.',ARRAY['M6-1-u5-X03']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"mis":"M6-1-u5-X03","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#5','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#6','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',1,'mc','auto','원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?',ARRAY['M6-1-u5-X06']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#7','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C7',1,'mc','auto','통계적 문제 해결의 첫 단계는 무엇인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]},{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#8','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#9','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#10','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}},{"stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#11','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',2,'sa','auto','전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]},{"stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#12','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#13','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#14','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#15','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',2,'mc','auto','띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."],"variant_rule":{"alt":[{"stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."]},{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#16','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#17','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',3,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#18','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#19','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#20','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C2',3,'mc','auto','좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#21','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C3',3,'error','auto','소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X14','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C3","difficulty":3,"kind":"error","stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#22','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}},{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#23','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]},{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#24','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C6',4,'essay','teacher','가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 「가 학교의 비율이 더 높으니 자전거를 타는 학생도 더 많다.」는 말이 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 「가 학교의 비율이 더 높으니 자전거를 타는 학생도 더 많다.」는 말이 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 학교는 200 × 25 % = 50이므로 50명, 나 학교는 300 × 20 % = 60이므로 60명이다. 비율은 가 학교가 높지만 전체 학생 수가 다르므로 자전거를 타는 학생 수는 나 학교가 더 많다.","scoring_points":["50명과 60명을 구했는가","나 학교가 더 많다고 답했는가","비율과 실제 수를 구분해 설명했는가"]},"explanation":["가 학교 50명, 나 학교 60명이에요.","나 학교가 더 많아요.","비율이 높아도 전체가 작으면 수는 적을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_a#25','math',6,1,'u5','','g6_1_math_u5_review_a','unit_review','M6-1-u5-C1',4,'essay','teacher','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C1","difficulty":4,"kind":"essay","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 「비율이 같으니 나쁨인 날수도 같다.」는 말이 맞는지 날수를 구해 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 가 도시는 30 × 30 % = 9이므로 9일, 나 도시는 60 × 30 % = 18이므로 18일이다. 비율은 같아도 전체 날수가 다르므로 나쁨인 날수는 나 도시가 더 많다.","scoring_points":["9일과 18일을 구했는가","나 도시가 더 많다고 답했는가","전체가 다르면 같은 %라도 수가 다르다고 설명했는가"]},"explanation":["가 도시 9일, 나 도시 18일이에요.","나 도시가 더 많아요.","전체가 다르면 같은 %라도 수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#1','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',1,'mc','auto','미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#2','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',1,'mc','auto','6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10','M6-1-u5-X11']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."]},{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#3','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',1,'sa','auto','좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."]},{"stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#4','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',1,'ox','auto','띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.',ARRAY['M6-1-u5-X07']::text[],true,'{"seq":4,"concept":"M6-1-u5-C1","difficulty":1,"kind":"ox","stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"mis":"M6-1-u5-X07","explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."],"variant_rule":{"alt":[{"stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#5','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#6','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',1,'mc','auto','원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?',ARRAY['M6-1-u5-X06','M6-1-u5-X16','M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C4","difficulty":1,"kind":"mc","stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."],"variant_rule":{"alt":[{"stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."]},{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#7','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C7',1,'mc','auto','모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."],"variant_rule":{"alt":[{"stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."]},{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#8','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."]},{"stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#9','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#10','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]},"variant_rule":{"alt":[{"stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]}},{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#11','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',2,'sa','auto','전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."]},{"stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#12','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#13','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."]},{"stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#14','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',2,'sa','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#15','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',2,'mc','auto','「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."]},{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#16','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',2,'mc','auto','실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X08']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#17','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',3,'sa','auto','미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#18','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#19','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#20','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C2',3,'mc','auto','해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#21','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C5',3,'error','auto','해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C5","difficulty":3,"kind":"error","stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}},{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#22','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true}},{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#23','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',4,'mc','auto','가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#24','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C3',4,'essay','teacher','외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C3","difficulty":4,"kind":"essay","stem":"외국인 친구에게 소개하고 싶은 문화유산을 조사했어요(경복궁 6명, 첨성대 5명, 수원 화성 4명, 종묘 3명, 기타 2명, 전체 20명). 띠그래프로 나타내는 방법을 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 각 항목의 백분율을 구한다 — 경복궁 6 ÷ 20 × 100 = 30, 첨성대 25, 수원 화성 20, 종묘 15, 기타 10. ② 30 + 25 + 20 + 15 + 10 = 100이므로 합이 100 %인지 확인한다. ③ 백분율만큼 띠의 길이를 나눈다. ④ 나눈 칸에 내용과 백분율을 쓴다. ⑤ 제목을 쓴다.","scoring_points":["다섯 항목의 백분율을 바르게 구했는가","합이 100인지 확인했는가","띠 나누기 → 내용·백분율 → 제목 차례를 썼는가"]},"explanation":["백분율은 30, 25, 20, 15, 10 %예요.","30 + 25 + 20 + 15 + 10 = 100이에요.","띠 나누기 → 내용·백분율 → 제목 차례로 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_b#25','math',6,1,'u5','','g6_1_math_u5_review_b','unit_review','M6-1-u5-C6',4,'essay','teacher','「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C6","difficulty":4,"kind":"essay","stem":"「6개월 동안 우리 반이 읽은 책의 수 변화」와 「이번 달 읽은 책의 종류별 비율」을 각각 그래프로 나타내려고 해요. 알맞은 그래프를 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 6개월 동안 읽은 책의 수 변화는 시간에 따른 변화이므로 꺾은선그래프가 알맞다. 이번 달 책의 종류별 비율은 전체에 대한 부분의 비율이므로 띠그래프나 원그래프가 알맞다. 보여 주고 싶은 것(목적)에 따라 그래프를 고른다.","scoring_points":["변화 → 꺾은선그래프를 골랐는가","비율 → 띠그래프·원그래프를 골랐는가","목적에 따라 고른다는 까닭을 썼는가"]},"explanation":["변화는 꺾은선그래프예요.","비율은 띠그래프·원그래프예요.","목적이 그래프를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#1','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',1,'mc','auto','소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"소개하고 싶은 문화유산 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"경복궁","correct":true},{"t":"기타","mis":"M6-1-u5-X16"},{"t":"첨성대","mis":"M6-1-u5-X07"},{"t":"수원 화성","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","경복궁이 30 %로 가장 커요.","그래서 답은 경복궁이에요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#2','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C6',1,'mc','auto','학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X11','M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"학년별 학생 수를 정확히 비교하려면 어떤 그래프가 알맞은가요?","options":[{"t":"막대그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X11"},{"t":"띠그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「막대그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]},{"stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#3','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',1,'sa','auto','기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"기르고 싶은 동물 조사에서 강아지는 10명, 전체는 25명이에요. 강아지의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","10 ÷ 25 × 100 = 40이에요.","강아지는 40 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."]},{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#4','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',1,'ox','auto','원그래프의 눈금이 20칸이면 한 칸은 5 %예요.',ARRAY['M6-1-u5-X05']::text[],true,'{"seq":4,"concept":"M6-1-u5-C4","difficulty":1,"kind":"ox","stem":"원그래프의 눈금이 20칸이면 한 칸은 5 %예요.","answer":"O","reason_options":[{"t":"100 ÷ 20 = 5이기 때문에","correct":true},{"t":"20칸이니 한 칸은 20 %이기 때문에","mis":"M6-1-u5-X05"}],"mis":"M6-1-u5-X05","explanation":["원그래프는 눈금 원(한 칸 5 %)에 원의 중심에서 선을 그어 나눠요.","조각의 넓이가 곧 비율이에요.","반올림해 합이 99·101이면 가장 큰 항목을 고쳐요."],"variant_rule":{"alt":[{"stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."]},{"stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#5','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 25칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["4"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 25 = 4예요.","눈금 한 칸은 4 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#6','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',1,'mc','auto','띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12']::text[],true,'{"seq":6,"concept":"M6-1-u5-C3","difficulty":1,"kind":"mc","stem":"띠그래프로 나타낼 때 가장 먼저 해야 할 일은 무엇인가요?","options":[{"t":"각 항목의 백분율 구하기","correct":true},{"t":"제목 쓰기","mis":"M6-1-u5-X12"},{"t":"백분율만큼 띠를 나누기","mis":"M6-1-u5-X12"},{"t":"나눈 칸에 내용과 백분율 쓰기","mis":"M6-1-u5-X12"}],"explanation":["띠그래프는 ① 백분율 구하기 → ② 합 100 % 확인 → ③ 띠 나누기 → ④ 내용·백분율 쓰기 → ⑤ 제목 쓰기 차례로 그려요.","「각 항목의 백분율 구하기」는 ① 단계예요.","차례를 지키면 틀린 곳을 일찍 찾을 수 있어요."],"variant_rule":{"alt":[{"stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."]},{"stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#7','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C7',1,'mc','auto','손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"손 들기나 붙임딱지로 친구들의 답을 모으는 것은 어느 단계인가요?","options":[{"t":"자료 수집","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 수집」이에요."],"variant_rule":{"alt":[{"stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."]},{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#8','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 35 %, 30 %, 20 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["35 + 30 + 20 + 5 = 90이에요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 90이에요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#9','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 로봇과 요리를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["로봇은 30 %, 요리는 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#10','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"하루 폐기물 조사를 원그래프로 나타냈는데 생활의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 49 + 38 = 87이에요.","100 − 87 = 13이에요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"pie","items":[["사업장",49],["건설",38],["생활",13]],"title":"하루 폐기물","hide":[2]},"variant_rule":{"alt":[{"stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]}},{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#11','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',2,'sa','auto','전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 40명 가운데 강아지를 키우는 학생이 25 %예요. 강아지를 키우는 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","40 × 25 % = 10이에요.","강아지를 키우는 학생은 10명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."]},{"stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#12','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 60 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","60 ÷ 5 = 12예요.","12칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#13','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 35 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","35 + 25 + 20 + 15 = 95예요.","100 − 95 = 5예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."]},{"stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#14','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 경복궁의 비율은 종묘의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["경복궁은 30 %, 종묘는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","30 ÷ 15 = 2 — 2배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#15','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',2,'mc','auto','「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C1","difficulty":2,"kind":"mc","stem":"「우리 반의 25 %가 강아지를 키운다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"강아지를 키우는 학생 수","correct":true},{"t":"강아지를 키우는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"강아지를 키우는 학생이 전체의 절반보다 적다는 것","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「강아지를 키우는 학생 수」는 알 수 없어요."],"variant_rule":{"alt":[{"stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."]},{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#16','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',2,'mc','auto','반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X08','M6-1-u5-X03']::text[],true,'{"seq":16,"concept":"M6-1-u5-C4","difficulty":2,"kind":"mc","stem":"반올림한 백분율의 합이 100 %가 아닐 때 가장 큰 항목을 고치는 까닭은 무엇인가요?","options":[{"t":"1 %를 고쳐도 그래프 모양이 가장 적게 달라지기 때문에","correct":true},{"t":"가장 큰 항목은 틀려도 되기 때문에","mis":"M6-1-u5-X16"},{"t":"작은 항목은 지워도 되기 때문에","mis":"M6-1-u5-X08"},{"t":"합이 100이 아니어도 되기 때문에","mis":"M6-1-u5-X03"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."],"variant_rule":{"alt":[{"stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."]},{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#17','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',3,'sa','auto','소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 조사한 전체는 20명이에요. 경복궁은 몇 명인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["경복궁은 30 %예요.","20 × 30 % = 6이에요.","경복궁은 6명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#18','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 30일 가운데 20 %, 나 도시는 90일 가운데 20 %가 좋음이었어요. 좋음인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 20 %라도 전체가 다르면 수가 달라요.","가는 30 × 20 % = 6, 나는 90 × 20 % = 18이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#19','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 52 %, 29 %, 18 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["53"],"explanation":["52 + 29 + 18 = 99예요.","가장 큰 항목 52를 1 늘려 고쳐요.","52 + 1 = 53이에요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."]},{"stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#20','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C2',3,'mc','auto','소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"경복궁은 기타의 3배예요","correct":true},{"t":"경복궁은 기타의 20배예요","mis":"M6-1-u5-X09"},{"t":"경복궁이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"경복궁은 30명이에요","mis":"M6-1-u5-X02"}],"explanation":["경복궁은 30 %, 기타는 10 %예요.","30 ÷ 10 = 3이에요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"}},{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#21','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',3,'error','auto','장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C8","difficulty":3,"kind":"error","stem":"장래 희망 띠그래프의 백분율 합이 95 %예요. 고치는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「합이 100에 가까우니 그대로 써도 돼.」","correct":true,"mis_target":"M6-1-u5-X03"},{"t":"유진 — 「잘못 적힌 항목을 다시 세어 보자.」","mis":"M6-1-u5-X16"},{"t":"라온 — 「고친 백분율만큼 띠를 다시 나누자.」","mis":"M6-1-u5-X16"}],"explanation":["백분율의 합은 100 %여야 하는데 95 %예요.","잘못 적힌 값을 찾아 고쳐 다시 그려야 해요.","가온은 잘못된 그래프를 그대로 쓰자고 했어요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."]},{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#22','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 소개하고 싶은 문화유산 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 종묘 칸만 잘못 적혔어요. 종묘의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["종묘를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","종묘는 15 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"소개하고 싶은 문화유산","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",10],["기타",10]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#23','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 500명 가운데 12 %, 나 학교 학생 300명 가운데 18 %가 우유를 마셔요. 우유를 마시는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 500 × 12 % = 60(명)이에요.","나 학교는 300 × 18 % = 54(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."]},{"stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#24','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C4',4,'essay','teacher','눈금이 20칸인 원에 저금 35 %, 간식 25 %, 학용품 20 %, 선물 15 %, 기타 5 %를 원그래프로 나타내려고 해요. 저금과 간식은 각각 눈금 몇 칸인지 구하고, 선을 긋는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C4","difficulty":4,"kind":"essay","stem":"눈금이 20칸인 원에 저금 35 %, 간식 25 %, 학용품 20 %, 선물 15 %, 기타 5 %를 원그래프로 나타내려고 해요. 저금과 간식은 각각 눈금 몇 칸인지 구하고, 선을 긋는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 눈금 한 칸은 100 ÷ 20 = 5 (%)이다. 저금은 35 ÷ 5 = 7이므로 7칸, 간식은 25 ÷ 5 = 5이므로 5칸이다. 원의 중심에서 0 눈금, 7칸 눈금, 12칸 눈금까지 차례로 선을 그어 나누고 내용·백분율·제목을 쓴다.","scoring_points":["한 칸이 5 %임을 썼는가","7칸·5칸을 구했는가","원의 중심에서 선을 긋는다고 썼는가"]},"explanation":["한 칸은 5 %예요.","저금 7칸, 간식 5칸이에요.","원의 중심에서 눈금까지 선을 그어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_c#25','math',6,1,'u5','','g6_1_math_u5_review_c','unit_review','M6-1-u5-C7',4,'essay','teacher','「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C7","difficulty":4,"kind":"essay","stem":"「우리 반 친구들은 어떤 운동을 가장 좋아할까?」를 통계적 문제 해결 네 단계로 탐구하는 계획을 써 보세요.","answer_guide":{"answer":"예: ① 문제 제기 — 탐구 문제를 정한다. ② 자료 수집 — 좋아하는 운동을 붙임딱지나 손 들기로 모은다. ③ 자료 분석 — 표로 정리해 백분율을 구하고 원그래프로 나타낸다. ④ 결과 해석 — 가장 많은 운동을 찾아 체육 시간이나 학급 행사 계획에 쓴다.","scoring_points":["네 단계를 차례대로 썼는가","자료 수집 방법을 구체적으로 썼는가","분석(표·그래프)과 해석(실천)을 구분했는가"]},"explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석이에요.","분석은 표·그래프로 정리하는 일이에요.","해석한 결과를 실천으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#1','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',1,'mc','auto','해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?',ARRAY['M6-1-u5-X16','M6-1-u5-X07']::text[],true,'{"seq":1,"concept":"M6-1-u5-C2","difficulty":1,"kind":"mc","stem":"해 보고 싶은 체험 활동 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"가상 현실","correct":true},{"t":"목공","mis":"M6-1-u5-X16"},{"t":"로봇","mis":"M6-1-u5-X07"},{"t":"요리","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","가상 현실이 40 %로 가장 커요.","그래서 답은 가상 현실이에요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"복숭아","correct":true},{"t":"배","mis":"M6-1-u5-X16"},{"t":"사과","mis":"M6-1-u5-X07"},{"t":"포도","mis":"M6-1-u5-X07"}],"explanation":["띠그래프에서는 칸의 길이가 비율을 보여 줘요.","복숭아가 40 %로 가장 커요.","그래서 답은 복숭아예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 원그래프 로 나타냈어요. 비율이 가장 큰 항목은 무엇인가요?","options":[{"t":"보통","correct":true},{"t":"매우 나쁨","mis":"M6-1-u5-X16"},{"t":"좋음","mis":"M6-1-u5-X07"},{"t":"나쁨","mis":"M6-1-u5-X07"}],"explanation":["원그래프에서는 조각의 넓이가 비율을 보여 줘요.","보통이 35 %로 가장 커요.","그래서 답은 보통이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#2','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',1,'mc','auto','하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?',ARRAY['M6-1-u5-X10']::text[],true,'{"seq":2,"concept":"M6-1-u5-C6","difficulty":1,"kind":"mc","stem":"하루 동안 교실 온도가 어떻게 달라지는지 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"막대그래프","mis":"M6-1-u5-X10"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."],"variant_rule":{"alt":[{"stem":"전체 용돈에서 저금이 차지하는 비율을 한눈에 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"띠그래프나 원그래프","correct":true},{"t":"막대그래프","mis":"M6-1-u5-X11"},{"t":"꺾은선그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「띠그래프나 원그래프」를 골라요."]},{"stem":"6개월 동안 달마다 저금한 금액의 변화를 보려면 어떤 그래프가 알맞은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"원그래프","mis":"M6-1-u5-X10"},{"t":"띠그래프","mis":"M6-1-u5-X10"},{"t":"그림그래프","mis":"M6-1-u5-X11"}],"explanation":["수의 크기는 막대·그림그래프, 시간에 따른 변화는 꺾은선그래프가 잘 보여 줘요.","전체에 대한 비율은 띠그래프·원그래프가 잘 보여 줘요.","보여 주고 싶은 것(목적)에 맞춰 「꺾은선그래프」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#3','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C3',1,'sa','auto','해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u5-C3","difficulty":1,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사에서 로봇은 12명, 전체는 40명이에요. 로봇의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","12 ÷ 40 × 100 = 30이에요.","로봇은 30 %예요."],"mis":"M6-1-u5-X04","variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 경복궁의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","6 ÷ 20 × 100 = 30이에요.","경복궁은 30 %예요."]},{"stem":"좋아하는 운동 조사에서 축구는 9명, 전체는 20명이에요. 축구의 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["백분율 = (항목의 수) ÷ (전체 수) × 100이에요.","9 ÷ 20 × 100 = 45예요.","축구는 45 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#4','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C7',1,'ox','auto','모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":4,"concept":"M6-1-u5-C7","difficulty":1,"kind":"ox","stem":"모은 자료를 표와 그래프로 정리하는 것은 자료 분석 단계예요.","answer":"O","reason_options":[{"t":"표와 그래프로 자료의 특징을 살피기 때문에","correct":true},{"t":"그래프를 그리는 것은 결과 해석이기 때문에","mis":"M6-1-u5-X13"}],"mis":"M6-1-u5-X13","explanation":["문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","그래프는 분석의 도구이고 해석으로 답을 얻어요.","찾은 답은 실천으로 이어요."],"variant_rule":{"alt":[{"stem":"띠그래프와 원그래프에서 모든 항목의 백분율을 더하면 100 %예요.","answer":"O","reason_options":[{"t":"띠와 원 전체가 전체(100 %)를 나타내기 때문에","correct":true},{"t":"항목이 많을수록 합이 커지기 때문에","mis":"M6-1-u5-X03"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]},{"stem":"띠그래프는 띠의 길이로, 원그래프는 원의 넓이로 비율을 나타내요.","answer":"O","reason_options":[{"t":"길이와 넓이가 백분율만큼 나뉘기 때문에","correct":true},{"t":"색깔로 비율을 나타내기 때문에","mis":"M6-1-u5-X07"}],"explanation":["띠그래프·원그래프는 전체를 100 %로 보는 비율그래프예요.","띠는 길이, 원은 넓이가 비율이에요.","같은 %라도 전체가 다르면 실제 수는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#5','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',1,'sa','auto','원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u5-C2","difficulty":1,"kind":"sa","stem":"원그래프 둘레의 눈금이 모두 50칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 50 = 2예요.","눈금 한 칸은 2 %예요."],"mis":"M6-1-u5-X05","variant_rule":{"alt":[{"stem":"원그래프 둘레의 눈금이 모두 20칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["5"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 20 = 5예요.","눈금 한 칸은 5 %예요."]},{"stem":"원그래프 둘레의 눈금이 모두 10칸이에요. 눈금 한 칸은 몇 %를 나타내나요? 숫자로 쓰세요.","answer":["10"],"explanation":["원그래프 전체가 100 %예요.","100 ÷ 10 = 10이에요.","눈금 한 칸은 10 %예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#6','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C5',1,'mc','auto','모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?',ARRAY['M6-1-u5-X12','M6-1-u5-X13']::text[],true,'{"seq":6,"concept":"M6-1-u5-C5","difficulty":1,"kind":"mc","stem":"모은 자료를 그래프로 나타내기 바로 전에 해야 할 일은 무엇인가요?","options":[{"t":"항목별 백분율을 구해 표를 완성하기","correct":true},{"t":"그래프 색칠하기","mis":"M6-1-u5-X12"},{"t":"그래프 제목 바꾸기","mis":"M6-1-u5-X12"},{"t":"결과를 발표하기","mis":"M6-1-u5-X13"}],"explanation":["자료를 모으면 표로 정리하고 백분율을 구해요.","백분율로 띠그래프·원그래프를 그린 뒤 그래프를 읽어 사실을 찾아요(해석).","그래서 답은 「항목별 백분율을 구해 표를 완성하기」예요."],"variant_rule":{"alt":[{"stem":"원그래프에서 각 항목의 경계선은 어디에서부터 그어야 하나요?","options":[{"t":"원의 중심","correct":true},{"t":"원의 둘레 아무 곳","mis":"M6-1-u5-X06"},{"t":"원 안의 아무 곳","mis":"M6-1-u5-X06"},{"t":"원의 가장 위쪽 눈금","mis":"M6-1-u5-X06"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]},{"stem":"원그래프를 그릴 때 원의 중심에서 선을 긋는 까닭은 무엇인가요?","options":[{"t":"조각의 넓이가 백분율과 같은 비율이 되게 하려고","correct":true},{"t":"선을 짧게 그으려고","mis":"M6-1-u5-X06"},{"t":"조각의 개수를 늘리려고","mis":"M6-1-u5-X16"},{"t":"색칠을 쉽게 하려고","mis":"M6-1-u5-X12"}],"explanation":["원그래프는 눈금 원에 원의 중심에서 눈금까지 선을 그어 나눠요.","중심에서 나눠야 조각의 넓이가 비율을 나타내요.","백분율 → 합 100 → 선 긋기 → 내용·백분율 → 제목 차례예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#7','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C7',1,'mc','auto','그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?',ARRAY['M6-1-u5-X13']::text[],true,'{"seq":7,"concept":"M6-1-u5-C7","difficulty":1,"kind":"mc","stem":"그래프를 보고 「탄소 중립을 더 홍보하자」는 결론을 얻는 것은 어느 단계인가요?","options":[{"t":"결과 해석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「결과 해석」이에요."],"variant_rule":{"alt":[{"stem":"통계적 문제 해결의 첫 단계는 무엇인가요?","options":[{"t":"문제 제기","correct":true},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"자료 분석","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「문제 제기」예요."]},{"stem":"모은 자료를 표와 그래프로 정리하는 것은 어느 단계인가요?","options":[{"t":"자료 분석","correct":true},{"t":"문제 제기","mis":"M6-1-u5-X13"},{"t":"자료 수집","mis":"M6-1-u5-X13"},{"t":"결과 해석","mis":"M6-1-u5-X13"}],"explanation":["통계적 문제 해결은 문제 제기 → 자료 수집 → 자료 분석 → 결과 해석의 네 단계예요.","표·그래프로 정리하는 것은 분석, 그래프를 보고 답과 실천을 찾는 것은 해석이에요.","그래서 답은 「자료 분석」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#8','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',1,'sa','auto','친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u5-C8","difficulty":1,"kind":"sa","stem":"친구가 그린 띠그래프의 백분율이 28 %, 24 %, 20 %, 16 %, 7 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["28 + 24 + 20 + 16 + 7 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."],"mis":"M6-1-u5-X15","variant_rule":{"alt":[{"stem":"친구가 그린 띠그래프의 백분율이 30 %, 25 %, 20 %, 15 %, 5 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["30 + 25 + 20 + 15 + 5 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]},{"stem":"친구가 그린 띠그래프의 백분율이 40 %, 25 %, 20 %, 10 %예요. 모두 더하면 몇 %인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["40 + 25 + 20 + 10 = 95예요.","합이 100이 아니니 어딘가 잘못 적혔어요.","답은 95예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#9','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"소개하고 싶은 문화유산 조사를 원그래프로 나타냈어요. 경복궁과 수원 화성을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["경복궁은 30 %, 수원 화성은 20 %예요.","30 % + 20 % = 50 %예요.","답은 50이에요."],"mis":"M6-1-u5-X15","asset":{"type":"pgr","kind":"pie","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 사과와 배를 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사과는 30 %, 배는 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 원그래프로 나타냈어요. 나쁨과 매우 나쁨을 합하면 전체의 몇 %인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나쁨은 30 %, 매우 나쁨은 10 %예요.","30 % + 10 % = 40 %예요.","답은 40이에요."],"asset":{"type":"pgr","kind":"pie","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#10','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"마을 땅 쓰임 조사를 띠그래프로 나타냈는데 기타의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 25 + 20 = 85예요.","100 − 85 = 15예요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","items":[["논",40],["밭",25],["과수원",20],["기타",15]],"title":"마을 땅 쓰임","hide":[3]},"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사를 띠그래프로 나타냈는데 종묘의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 30 + 25 + 20 + 10 = 85예요.","100 − 85 = 15예요."],"asset":{"type":"pgr","kind":"band","items":[["경복궁",30],["첨성대",25],["수원 화성",20],["종묘",15],["기타",10]],"title":"소개하고 싶은 문화유산","hide":[3]}},{"stem":"좋아하는 과일 조사를 원그래프로 나타냈는데 포도의 백분율이 지워졌어요. ?에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["모든 항목의 백분율을 더하면 100 %예요.","나머지 항목의 합은 40 + 30 + 10 = 80이에요.","100 − 80 = 20이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일","hide":[2]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#11','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',2,'sa','auto','전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u5-C1","difficulty":2,"kind":"sa","stem":"전체 20명 가운데 종묘를 고른 학생이 15 %예요. 종묘를 고른 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","20 × 15 % = 3이에요.","종묘를 고른 학생은 3명이에요."],"mis":"M6-1-u5-X14","variant_rule":{"alt":[{"stem":"전체 60일 가운데 나쁨이 30 %예요. 나쁨은 며칠인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","60 × 30 % = 18이에요.","나쁨은 18일이에요."]},{"stem":"전체 50명 가운데 포도를 좋아하는 사람이 20 %예요. 포도를 좋아하는 사람은 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["항목의 수 = 전체 수 × 백분율이에요.","50 × 20 % = 10이에요.","포도를 좋아하는 사람은 10명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#12','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C4',2,'sa','auto','눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u5-C4","difficulty":2,"kind":"sa","stem":"눈금이 20칸인 원그래프에서 15 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","15 ÷ 5 = 3이에요.","3칸만큼 나누어요."],"mis":"M6-1-u5-X05","asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true},"variant_rule":{"alt":[{"stem":"눈금이 20칸인 원그래프에서 35 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","35 ÷ 5 = 7이에요.","7칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}},{"stem":"눈금이 20칸인 원그래프에서 45 %인 항목은 눈금 몇 칸만큼 나누어야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["눈금 한 칸은 100 ÷ 20 = 5 (%)예요.","45 ÷ 5 = 9예요.","9칸만큼 나누어요."],"asset":{"type":"pgr","kind":"pie","items":[["가",50],["나",50]],"blank":true,"ticks":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#13','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C3',2,'sa','auto','띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M6-1-u5-C3","difficulty":2,"kind":"sa","stem":"띠그래프 다섯 항목의 백분율이 28 %, 24 %, 20 %, 16 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","28 + 24 + 20 + 16 = 88이에요.","100 − 88 = 12예요."],"mis":"M6-1-u5-X03","variant_rule":{"alt":[{"stem":"띠그래프 다섯 항목의 백분율이 30 %, 25 %, 20 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","30 + 25 + 20 + 15 = 90이에요.","100 − 90 = 10이에요."]},{"stem":"띠그래프 네 항목의 백분율이 45 %, 30 %, 15 %, □ %예요. □ 안에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["띠그래프의 백분율을 모두 더하면 100 %예요.","45 + 30 + 15 = 90이에요.","100 − 90 = 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#14','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',2,'sa','auto','좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u5-C2","difficulty":2,"kind":"sa","stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 축구의 비율은 야구의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["축구는 45 %, 야구는 15 %예요.","「몇 배」는 나눗셈으로 구해요.","45 ÷ 15 = 3 — 3배예요."],"mis":"M6-1-u5-X09","asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 복숭아의 비율은 배의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["복숭아는 40 %, 배는 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 가상 현실의 비율은 목공의 비율의 몇 배인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","「몇 배」는 나눗셈으로 구해요.","40 ÷ 10 = 4 — 4배예요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#15','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',2,'mc','auto','올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?',ARRAY['M6-1-u5-X16']::text[],true,'{"seq":15,"concept":"M6-1-u5-C6","difficulty":2,"kind":"mc","stem":"올해 원그래프 한 장만 보고는 알 수 없는 것은 어느 것인가요?","options":[{"t":"해마다 비율이 어떻게 달라졌는지","correct":true},{"t":"올해 가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"올해 각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"올해 두 항목의 비율 합","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「해마다 비율이 어떻게 달라졌는지」예요."],"variant_rule":{"alt":[{"stem":"띠그래프·원그래프만으로는 알 수 없는 것은 어느 것인가요?","options":[{"t":"각 항목의 실제 수","correct":true},{"t":"각 항목의 비율","mis":"M6-1-u5-X16"},{"t":"가장 큰 항목","mis":"M6-1-u5-X16"},{"t":"전체에 대한 부분의 정도","mis":"M6-1-u5-X16"}],"explanation":["띠·원그래프는 한 시점의 전체에 대한 비율만 보여 줘요.","실제 수는 전체를 알아야 하고, 변화는 여러 시점을 견주어야 알 수 있어요.","그래서 답은 「각 항목의 실제 수」예요."]},{"stem":"「우리 반의 30 %가 축구를 좋아한다.」만 보고 알 수 없는 것은 어느 것인가요?","options":[{"t":"축구를 좋아하는 학생 수","correct":true},{"t":"축구를 좋아하는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구를 좋아하지 않는 학생의 비율","mis":"M6-1-u5-X16"},{"t":"축구가 전체에서 차지하는 정도","mis":"M6-1-u5-X16"}],"explanation":["비율그래프와 백분율은 전체에 대한 비율만 알려 줘요.","실제 수는 전체 수를 알아야 구할 수 있어요.","그래서 「축구를 좋아하는 학생 수」는 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#16','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',2,'mc','auto','띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?',ARRAY['M6-1-u5-X03','M6-1-u5-X16']::text[],true,'{"seq":16,"concept":"M6-1-u5-C8","difficulty":2,"kind":"mc","stem":"띠그래프 백분율의 합이 95 %예요. 무엇이 잘못되었나요?","options":[{"t":"어떤 항목의 백분율이 잘못 적혔어요","correct":true},{"t":"그래프는 맞아요","mis":"M6-1-u5-X03"},{"t":"제목이 없어요","mis":"M6-1-u5-X16"},{"t":"색이 잘못되었어요","mis":"M6-1-u5-X16"}],"explanation":["비율그래프는 백분율의 합이 100인지, 칸의 크기가 백분율과 맞는지 검토해요.","잘못 그린 그래프는 사실을 왜곡해 틀린 판단으로 이어져요.","그래서 답은 「어떤 항목의 백분율이 잘못 적혔어요」예요."],"variant_rule":{"alt":[{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 101 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 줄여 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 줄여요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 줄여요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]},{"stem":"실제 자료로 백분율을 구해 반올림했더니 합이 99 %가 되었어요. 어떻게 하면 좋은가요?","options":[{"t":"가장 큰 항목의 백분율을 1 % 늘려 100 %로 맞춰요","correct":true},{"t":"그대로 그려요","mis":"M6-1-u5-X03"},{"t":"모든 항목을 1 %씩 늘려요","mis":"M6-1-u5-X08"},{"t":"가장 작은 항목을 1 % 늘려요","mis":"M6-1-u5-X08"}],"explanation":["실제 자료는 백분율이 딱 떨어지지 않아 반올림해요.","반올림한 합이 99 %·101 %가 되면 가장 큰 항목의 크기를 조금 고쳐요.","그래야 합이 100 %가 되고 그래프 모양도 가장 적게 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#17','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',3,'sa','auto','해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M6-1-u5-C2","difficulty":3,"kind":"sa","stem":"해 보고 싶은 체험 활동 조사를 띠그래프로 나타냈어요. 조사한 전체는 40명이에요. 요리는 몇 명인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["요리는 20 %예요.","40 × 20 % = 8이에요.","요리는 8명이에요."],"mis":"M6-1-u5-X14","asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 원그래프로 나타냈어요. 조사한 전체는 50명이에요. 포도는 몇 명인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["포도는 20 %예요.","50 × 20 % = 10이에요.","포도는 10명이에요."],"asset":{"type":"pgr","kind":"pie","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"미세 먼지 상태 조사를 띠그래프로 나타냈어요. 조사한 전체는 60일이에요. 보통은 몇 일인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["보통은 35 %예요.","60 × 35 % = 21이에요.","보통은 21일이에요."],"asset":{"type":"pgr","kind":"band","items":[["좋음",25],["보통",35],["나쁨",30],["매우 나쁨",10]],"title":"미세 먼지 상태"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#18','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',3,'mc','auto','가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X15','M6-1-u5-X02']::text[],true,'{"seq":18,"concept":"M6-1-u5-C1","difficulty":3,"kind":"mc","stem":"가 도시는 25일 가운데 40 %, 나 도시는 50일 가운데 40 %가 보통이었어요. 보통인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 40 %라도 전체가 다르면 수가 달라요.","가는 25 × 40 % = 10, 나는 50 × 40 % = 20이에요.","그래서 나 도시 날수가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 나쁨이었어요. 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 30 %라도 전체가 다르면 수가 달라요.","가는 30 × 30 % = 9, 나는 60 × 30 % = 18이에요.","그래서 나 도시 날수가 더 많아요."]},{"stem":"가 도시는 20일 가운데 25 %, 나 도시는 40일 가운데 25 %가 매우 나쁨이었어요. 매우 나쁨인 날수를 바르게 비교한 것은 어느 것인가요?","options":[{"t":"나 도시가 더 많아요","correct":true},{"t":"두 도시가 같아요","mis":"M6-1-u5-X01"},{"t":"가 도시가 더 많아요","mis":"M6-1-u5-X15"},{"t":"비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["같은 25 %라도 전체가 다르면 수가 달라요.","가는 20 × 25 % = 5, 나는 40 × 25 % = 10이에요.","그래서 나 도시 날수가 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#19','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C4',3,'sa','auto','반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M6-1-u5-C4","difficulty":3,"kind":"sa","stem":"반올림해 구한 세 항목의 백분율이 44 %, 31 %, 24 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["44 + 31 + 24 = 99예요.","가장 큰 항목 44를 1 늘려 고쳐요.","44 + 1 = 45예요."],"mis":"M6-1-u5-X08","variant_rule":{"alt":[{"stem":"반올림해 구한 세 항목의 백분율이 47 %, 33 %, 21 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["46"],"explanation":["47 + 33 + 21 = 101이에요.","가장 큰 항목 47을 1 줄여 고쳐요.","47 − 1 = 46이에요."]},{"stem":"반올림해 구한 세 항목의 백분율이 38 %, 34 %, 27 %예요. 합을 100 %로 맞추려면 가장 큰 항목을 몇 %로 고쳐야 하나요? 숫자로 쓰세요.","answer":["39"],"explanation":["38 + 34 + 27 = 99예요.","가장 큰 항목 38을 1 늘려 고쳐요.","38 + 1 = 39예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#20','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C2',3,'mc','auto','좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u5-X09','M6-1-u5-X16','M6-1-u5-X02']::text[],true,'{"seq":20,"concept":"M6-1-u5-C2","difficulty":3,"kind":"mc","stem":"좋아하는 운동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"축구는 배구보다 35 % 더 많아요","correct":true},{"t":"축구는 배구의 35배예요","mis":"M6-1-u5-X09"},{"t":"축구가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"축구는 45명이에요","mis":"M6-1-u5-X02"}],"explanation":["축구는 45 %, 배구는 10 %예요.","45 − 10 = 35예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["축구",45],["피구",30],["야구",15],["배구",10]],"title":"좋아하는 운동"},"variant_rule":{"alt":[{"stem":"좋아하는 과일 조사를 띠그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"복숭아는 배의 4배예요","correct":true},{"t":"복숭아는 배의 30배예요","mis":"M6-1-u5-X09"},{"t":"복숭아가 가장 적어요","mis":"M6-1-u5-X16"},{"t":"복숭아는 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["복숭아는 40 %, 배는 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"band","items":[["복숭아",40],["사과",30],["포도",20],["배",10]],"title":"좋아하는 과일"}},{"stem":"해 보고 싶은 체험 활동 조사를 원그래프로 나타냈어요. 그래프를 보고 알 수 있는 사실로 옳은 것은 어느 것인가요?","options":[{"t":"가상 현실은 목공의 4배예요","correct":true},{"t":"가상 현실은 목공의 30배예요","mis":"M6-1-u5-X09"},{"t":"가상 현실이 가장 적어요","mis":"M6-1-u5-X16"},{"t":"가상 현실은 40명이에요","mis":"M6-1-u5-X02"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4예요.","그래프에는 비율만 있어 실제 수는 전체를 알아야 해요."],"asset":{"type":"pgr","kind":"pie","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#21','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C1',3,'error','auto','가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X16']::text[],true,'{"seq":21,"concept":"M6-1-u5-C1","difficulty":3,"kind":"error","stem":"가 도시는 30일 가운데 30 %, 나 도시는 60일 가운데 30 %가 미세 먼지 나쁨이었어요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「비율이 같으니 나쁨인 날수도 같아.」","correct":true,"mis_target":"M6-1-u5-X01"},{"t":"시우 — 「가 도시의 나쁨인 날은 9일이야.」","mis":"M6-1-u5-X16"},{"t":"은우 — 「나 도시의 나쁨인 날은 18일이야.」","mis":"M6-1-u5-X16"}],"explanation":["가 도시는 30 × 30 % = 9(일)이에요.","나 도시는 60 × 30 % = 18(일)이에요.","여울은 전체가 다른데 같은 %이면 날수도 같다고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"소개하고 싶은 문화유산 조사에서 경복궁은 6명, 전체는 20명이에요. 띠그래프로 나타내기 전에 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「경복궁은 6명이니까 6 %야.」","correct":true,"mis_target":"M6-1-u5-X14"},{"t":"도윤 — 「6 ÷ 20 × 100으로 구해.」","mis":"M6-1-u5-X16"},{"t":"서아 — 「다 구하면 합이 100인지 확인해.」","mis":"M6-1-u5-X16"}],"explanation":["백분율 = 항목의 수 ÷ 전체 × 100이에요.","6 ÷ 20 × 100 = 30이에요.","하린은 항목의 수를 그대로 %로 잘못 말했어요."]},{"stem":"해 보고 싶은 체험 활동 조사(전체 40명)를 띠그래프로 나타냈어요. 그래프를 해석한 말 가운데 잘못된 것은 누구의 말인가요?","options":[{"t":"수아 — 「가상 현실은 목공보다 30배 많아.」","correct":true,"mis_target":"M6-1-u5-X09"},{"t":"예준 — 「가상 현실이 가장 많아.」","mis":"M6-1-u5-X16"},{"t":"나린 — 「가상 현실은 16명이야.」","mis":"M6-1-u5-X16"}],"explanation":["가상 현실은 40 %, 목공은 10 %예요.","40 ÷ 10 = 4니 4배예요.","수아는 백분율의 차를 몇 배로 잘못 말했어요."],"asset":{"type":"pgr","kind":"band","items":[["가상 현실",40],["로봇",30],["요리",20],["목공",10]],"title":"해 보고 싶은 체험 활동"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#22','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',3,'sa','auto','친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M6-1-u5-C8","difficulty":3,"kind":"sa","stem":"친구가 그린 용돈 쓰임 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 저금 칸만 잘못 적혔어요. 저금의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["저금을 뺀 나머지의 합은 65 %예요.","100 − 65 = 35예요.","저금은 35 %로 고쳐요."],"mis":"M6-1-u5-X03","asset":{"type":"pgr","kind":"band","title":"용돈 쓰임","items":[["저금",25],["간식",25],["학용품",20],["선물",15],["기타",5]],"bad":true},"variant_rule":{"alt":[{"stem":"친구가 그린 장래 희망 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 기타 칸만 잘못 적혔어요. 기타의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["기타를 뺀 나머지의 합은 90 %예요.","100 − 90 = 10이에요.","기타는 10 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}},{"stem":"친구가 그린 빌린 책의 종류 띠그래프의 합이 100 %가 아니에요. 다시 세어 보니 만화 칸만 잘못 적혔어요. 만화의 바른 백분율은 몇 %인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["만화를 뺀 나머지의 합은 85 %예요.","100 − 85 = 15예요.","만화는 15 %로 고쳐요."],"asset":{"type":"pgr","kind":"band","title":"빌린 책의 종류","items":[["동화",35],["과학",25],["역사",20],["만화",10],["기타",5]],"bad":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#23','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C6',4,'mc','auto','가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?',ARRAY['M6-1-u5-X01','M6-1-u5-X02']::text[],true,'{"seq":23,"concept":"M6-1-u5-C6","difficulty":4,"kind":"mc","stem":"가 학교 학생 600명 가운데 15 %, 나 학교 학생 400명 가운데 20 %가 방과 후 수업을 들어요. 방과 후 수업을 듣는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"가 학교","correct":true},{"t":"나 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 600 × 15 % = 90(명)이에요.","나 학교는 400 × 20 % = 80(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 가 학교가 더 많아요."],"variant_rule":{"alt":[{"stem":"가 학교 학생 200명 가운데 25 %, 나 학교 학생 300명 가운데 20 %가 자전거를 타요. 자전거를 타는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 학교","correct":true},{"t":"가 학교","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 학교는 200 × 25 % = 50(명)이에요.","나 학교는 300 × 20 % = 60(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 학교가 더 많아요."]},{"stem":"가 마을 학생 400명 가운데 30 %, 나 마을 학생 600명 가운데 25 %가 텃밭을 가꿔요. 텃밭을 가꾸는 학생 수가 더 많은 곳은 어디인가요?","options":[{"t":"나 마을","correct":true},{"t":"가 마을","mis":"M6-1-u5-X01"},{"t":"두 곳이 같아요","mis":"M6-1-u5-X01"},{"t":"비율만으로는 비교할 수 없어요","mis":"M6-1-u5-X02"}],"explanation":["가 마을은 400 × 30 % = 120(명)이에요.","나 마을은 600 × 25 % = 150(명)이에요.","비율이 작아도 전체가 크면 수는 더 많을 수 있어요 — 나 마을이 더 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#24','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C5',4,'essay','teacher','우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u5-C5","difficulty":4,"kind":"essay","stem":"우리 반 40명이 해 보고 싶은 체험 활동을 조사했어요(가상 현실 16명, 로봇 12명, 요리 8명, 목공 4명). 백분율을 구해 표로 정리하고, 그래프로 나타낸 뒤 알 수 있는 사실을 한 가지 써 보세요.","answer_guide":{"answer":"예: 가상 현실 16 ÷ 40 × 100 = 40, 로봇 30, 요리 20, 목공 10이고 합은 100 %이다. 이 백분율만큼 띠그래프(또는 원그래프)로 나타낸다. 그래프를 보면 가상 현실이 40 %로 가장 많고 목공의 4배이다.","scoring_points":["네 항목의 백분율을 구했는가","합 100을 확인하고 그래프로 나타낸다고 썼는가","그래프에서 바른 사실을 찾았는가"]},"explanation":["백분율은 40, 30, 20, 10 %예요.","합이 100 %인지 확인하고 그래프로 나타내요.","가상 현실이 가장 많고 목공의 4배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u5_review_d#25','math',6,1,'u5','','g6_1_math_u5_review_d','unit_review','M6-1-u5-C8',4,'essay','teacher','친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u5-C8","difficulty":4,"kind":"essay","stem":"친구가 장래 희망을 조사해 띠그래프로 나타냈는데 운동선수 30 %, 의사 25 %, 예술가 20 %, 선생님 15 %, 기타 5 %로 적었어요. 잘못된 점을 찾고 바르게 고치는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30 + 25 + 20 + 15 + 5 = 95이므로 합이 100 %가 아니다. 어떤 항목의 백분율이 잘못 적힌 것이다. 다시 세어 보니 기타가 틀렸다면 100 − 90 = 10이므로 기타는 10 %이다. 고친 백분율만큼 띠를 다시 나누어 그린다.","scoring_points":["합이 95라 잘못되었다고 찾았는가","기타를 10 %로 고쳤는가","고친 값만큼 다시 그린다고 썼는가"]},"explanation":["합이 95 %예요.","기타는 100 − 90 = 10 — 10 %예요.","고친 값만큼 다시 그려요."],"asset":{"type":"pgr","kind":"band","title":"장래 희망","items":[["운동선수",30],["의사",25],["예술가",20],["선생님",15],["기타",5]],"bad":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C1','math',6,1,'u6',1,'겉넓이와 부피 만나기 — 직육면체의 여섯 면은 모두 직사각형이고 마주 보는 면은 합동이며, 겉면의 넓이(겉넓이, 감싸는 종이의 양)와 공간에서 차지하는 크기(부피, 담기는 양)가 서로 다른 양임을 알기',ARRAY['6수03-17']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C2','math',6,1,'u6',2,'직육면체의 겉넓이 — 여섯 면의 넓이를 모두 더하거나, 마주 보는 면이 합동(3쌍)임을 이용해 서로 다른 세 면의 넓이의 합을 2배 하여 겉넓이를 구하고, 보이는 세 면만 더하면 안 됨을 알기',ARRAY['6수03-17']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C3','math',6,1,'u6',3,'두 밑면 + 옆면 · 정육면체의 겉넓이 — 두 밑면의 넓이와 옆면(가로가 한 밑면의 둘레, 세로가 높이인 직사각형)의 넓이를 더해 겉넓이를 구하고, 여섯 면이 모두 합동인 정육면체의 겉넓이는 한 면의 넓이를 6배 하여 구하기',ARRAY['6수03-17']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C4','math',6,1,'u6',4,'부피 비교와 1 cm³ — 크기가 같은 단위로 세어야 부피를 비교할 수 있고, 한 모서리가 1 cm인 정육면체의 부피 1 cm³(1 세제곱센티미터)를 단위로 쌓기나무의 개수를 세어 부피를 구하며, 빈틈이 생기는 것은 단위로 쓸 수 없음을 알기',ARRAY['6수03-18']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C5','math',6,1,'u6',5,'직육면체와 정육면체의 부피 — 가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수가 각 모서리의 길이와 같음을 이용해 부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이로 구하고, 정육면체는 한 모서리를 세 번 곱하여 구하기',ARRAY['6수03-19']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C6','math',6,1,'u6',6,'1 m³와 1 cm³의 관계 — 한 모서리가 1 m인 정육면체의 부피 1 m³(1 세제곱미터)를 알고, 1 m = 100 cm이므로 1 m³ = 100 × 100 × 100 = 1000000 cm³임을 넓이(1 m² = 10000 cm²)와 구별하며, 큰 부피는 m³로 나타내고 단위가 다르면 같은 단위로 고쳐 비교하기',ARRAY['6수03-18']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u6-C7','math',6,1,'u6',7,'문제 해결 — 직육면체를 잘라도 조각의 부피를 모두 더하면 처음과 같아 부피는 변하지 않고, 자른 자리마다 마주 보는 새 면 두 개가 생겨 겉넓이는 늘어남을 셈으로 확인하며 문제를 해결하기',ARRAY['6수03-19']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X01','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C7']::text[],'겉넓이와 부피를 헷갈린다(포장지·색칠할 넓이를 부피로, 담기는 양을 겉넓이로)','감싸면 겉넓이, 담으면 부피') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X02','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C4']::text[],'넓이 단위와 부피 단위를 헷갈린다(겉넓이를 cm³로, 부피를 cm²로 쓴다)','넓이는 ², 부피는 ³') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X03','math',6,'u6',ARRAY['M6-1-u6-C2','M6-1-u6-C3']::text[],'겨냥도에 보이는 세 면만 더해 겉넓이라고 한다','여섯 면 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X04','math',6,'u6',ARRAY['M6-1-u6-C2']::text[],'서로 다른 세 면의 합을 2배 하지 않거나, 여섯 면을 다 더한 뒤 또 2배 한다','세 면 × 2 = 여섯 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X05','math',6,'u6',ARRAY['M6-1-u6-C3']::text[],'옆면을 펼친 직사각형의 가로를 한 밑면의 한 변으로 여긴다(둘레가 아니라)','옆면의 가로 = 한 밑면의 둘레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X06','math',6,'u6',ARRAY['M6-1-u6-C3','M6-1-u6-C5']::text[],'정육면체의 겉넓이를 한 면 × 4나 한 모서리 × 6으로 구한다','한 면의 넓이 × 6') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X07','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2']::text[],'마주 보는 면이 합동이라는 것(넓이가 같은 면 3쌍)을 놓치거나 쌍의 수를 잘못 센다','마주 보는 면은 합동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X08','math',6,'u6',ARRAY['M6-1-u6-C4']::text[],'크기가 다른 쌓기나무로 센 개수를 그대로 견주어 부피를 비교한다','같은 크기 단위로 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X09','math',6,'u6',ARRAY['M6-1-u6-C4']::text[],'구슬처럼 빈틈이 생기는 것도 부피의 단위로 쓸 수 있다고 여긴다','빈틈 없이 채워지나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X10','math',6,'u6',ARRAY['M6-1-u6-C4','M6-1-u6-C5']::text[],'쌓기나무의 개수를 셀 때 한 층만 세거나 층수를 곱하지 않는다(보이는 것만 센다)','한 층 × 층수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X11','math',6,'u6',ARRAY['M6-1-u6-C5','M6-1-u6-C7']::text[],'부피를 가로 + 세로 + 높이로 더하거나, 두 길이만 곱한다(한 밑면의 넓이에서 멈춘다)','세 길이를 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X12','math',6,'u6',ARRAY['M6-1-u6-C5']::text[],'정육면체의 부피를 한 모서리 × 3이나 한 면의 넓이 × 6으로 구한다','한 모서리를 세 번 곱하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X13','math',6,'u6',ARRAY['M6-1-u6-C6']::text[],'1 m³를 100 cm³·10000 cm³·1000 cm³로 여긴다(100을 세 번 곱하지 않는다)','100 × 100 × 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X14','math',6,'u6',ARRAY['M6-1-u6-C6']::text[],'단위가 다른 길이(m와 cm)나 부피(m³와 cm³)를 같은 단위로 고치지 않고 그대로 셈하거나 견준다','단위부터 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X15','math',6,'u6',ARRAY['M6-1-u6-C7']::text[],'직육면체를 자르면 부피도 바뀐다(줄어든다·늘어난다)고 여긴다','조각을 합치면 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X16','math',6,'u6',ARRAY['M6-1-u6-C7']::text[],'자르면 겉넓이가 그대로라고 여기거나, 한 번 자를 때 새 면을 하나만 센다','한 번 자르면 새 면 2개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X17','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C5']::text[],'겉넓이가 크면 부피도 크다(부피가 같으면 겉넓이도 같다)고 여긴다','서로 다른 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u6-X18','math',6,'u6',ARRAY['M6-1-u6-C1','M6-1-u6-C2','M6-1-u6-C3','M6-1-u6-C4','M6-1-u6-C5','M6-1-u6-C6','M6-1-u6-C7']::text[],'묻는 말을 놓치거나 곱셈·덧셈 셈을 잘못 한다 — 겉넓이↔부피, 한 면↔여섯 면, cm³↔m³, 옳은↔옳지 않은','물음에 동그라미 · 거꾸로 셈으로 검산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#1','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','겉넓이란 무엇인가요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"겉넓이란 무엇인가요?","options":[{"t":"입체도형의 겉면의 넓이","correct":true},{"t":"입체도형이 담을 수 있는 양","mis":"M6-1-u6-X01"},{"t":"가장 긴 모서리의 길이","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 개수","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형의 겉면의 넓이」예요."],"variant_rule":{"alt":[{"stem":"부피란 무엇인가요?","options":[{"t":"입체도형이 공간에서 차지하는 크기","correct":true},{"t":"입체도형의 겉면의 넓이","mis":"M6-1-u6-X01"},{"t":"모든 모서리의 길이의 합","mis":"M6-1-u6-X18"},{"t":"한 면의 넓이","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「입체도형이 공간에서 차지하는 크기」예요."]},{"stem":"직육면체의 겉면을 이루는 여섯 면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u6-X18"},{"t":"원","mis":"M6-1-u6-X18"},{"t":"사다리꼴","mis":"M6-1-u6-X18"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고, 마주 보는 면은 합동이에요.","겉넓이는 겉면 여섯 면의 넓이, 부피는 공간에서 차지하는 크기예요.","정답은 「직사각형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#2','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'mc','auto','다음 중 부피를 알아야 하는 상황은 어느 것인가요?',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":2,"concept":"M6-1-u6-C1","difficulty":1,"kind":"mc","stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."],"variant_rule":{"alt":[{"stem":"다음 중 겉넓이를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"청사초롱 겉면에 붙일 한지의 양을 알 때","correct":true},{"t":"청사초롱 안에 담기는 공간의 크기를 알 때","mis":"M6-1-u6-X01"},{"t":"어항에 물을 얼마나 채울지 알 때","mis":"M6-1-u6-X01"},{"t":"상자에 쌓기나무를 몇 개 넣을지 알 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「청사초롱 겉면에 붙일 한지의 양을 알 때」예요."]},{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#3','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'sa','auto','가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C1","difficulty":1,"kind":"sa","stem":"가로 8 cm, 세로 5 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","8 × 5 = 40이에요.","그래서 40 cm²예요."],"mis":"M6-1-u6-X18","variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 6 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","7 × 6 = 42예요.","그래서 42 cm²예요."]},{"stem":"가로 9 cm, 세로 4 cm인 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직사각형의 넓이는 가로 × 세로예요.","9 × 4 = 36이에요.","그래서 36 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#4','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',1,'ox','auto','겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.',ARRAY['M6-1-u6-X01']::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":1,"kind":"ox","stem":"겉넓이는 상자를 감싸는 종이의 양이고, 부피는 상자 안에 담기는 공간의 크기예요.","answer":"O","reason_options":[{"t":"겉면의 넓이와 공간의 크기는 서로 다른 양이기 때문에","correct":true},{"t":"둘 다 상자의 크기라서 같은 양이기 때문에","mis":"M6-1-u6-X01"}],"mis":"M6-1-u6-X01","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체의 여섯 면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"직육면체는 직사각형 6개로 둘러싸인 도형이기 때문에","correct":true},{"t":"옆면만 직사각형이고 위아래는 다른 모양이기 때문에","mis":"M6-1-u6-X07"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]},{"stem":"겉넓이는 겉면 여섯 면의 넓이를 모두 더한 것이에요.","answer":"O","reason_options":[{"t":"겉면은 여섯 면으로 이루어져 있기 때문에","correct":true},{"t":"보이는 세 면만 겉면이기 때문에","mis":"M6-1-u6-X03"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#5','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'mc','auto','한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-1-u6-X14','M6-1-u6-X13']::text[],true,'{"seq":5,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"한 변이 1 m인 정사각형의 넓이는 몇 cm²인가요?","options":[{"t":"10000 cm²","correct":true},{"t":"100 cm²","mis":"M6-1-u6-X14"},{"t":"1000 cm²","mis":"M6-1-u6-X14"},{"t":"1000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m = 100 cm이므로 100 × 100 = 10000이에요.","그래서 10000 cm²예요."],"variant_rule":{"alt":[{"stem":"2 m²는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"2000 cm²","mis":"M6-1-u6-X14"},{"t":"2000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 2 = 20000이에요.","그래서 20000 cm²예요."]},{"stem":"3 m²는 몇 cm²인가요?","options":[{"t":"30000 cm²","correct":true},{"t":"300 cm²","mis":"M6-1-u6-X14"},{"t":"3000 cm²","mis":"M6-1-u6-X14"},{"t":"3000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 3 = 30000이에요.","그래서 30000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#6','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'sa','auto','직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u6-C1","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 4 × 3 = 12예요.","그래서 12 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 5 × 3 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[120.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[144.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"lab":[[[60.0,109.0],"5 cm"],[[154.0,90.0],"2 cm"],[[170.0,36.0],"3 cm"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 색칠한 면(오른쪽 옆면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 3 × 5 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":166.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,120.0,"ne"],"ㅇ":[132.0,120.0,"e"],"ㅂ":[0,156.0,"sw"],"ㅅ":[96.0,156.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"lab":[[[48.0,169.0],"4 cm"],[[136.0,144.0],"3 cm"],[[158.0,60.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#7','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'mc','auto','직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?',ARRAY['M6-1-u6-X07']::text[],true,'{"seq":7,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?","options":[{"t":"세 쌍","correct":true},{"t":"한 쌍","mis":"M6-1-u6-X07"},{"t":"두 쌍","mis":"M6-1-u6-X07"},{"t":"여섯 쌍","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「세 쌍」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 면과 모양과 크기가 같은 면은 몇 개 더 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M6-1-u6-X07"},{"t":"3개","mis":"M6-1-u6-X07"},{"t":"5개","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「1개」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?","options":[{"t":"3가지","correct":true},{"t":"2가지","mis":"M6-1-u6-X07"},{"t":"4가지","mis":"M6-1-u6-X07"},{"t":"6가지","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「3가지」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#8','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'match','auto','상황에 알맞은 양을 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C1","difficulty":2,"kind":"match","stem":"상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"상자를 포장지로 감쌀 때","r":"겉넓이"},{"l":"상자에 쌀을 가득 담을 때","r":"부피"},{"l":"상자의 모서리를 따라 테이프를 붙일 때","r":"모든 모서리의 길이의 합"}],"mis":"M6-1-u6-X01","explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"청사초롱 겉면에 한지를 붙일 때","r":"겉넓이"},{"l":"청사초롱 안의 공간을 알 때","r":"부피"},{"l":"청사초롱 바닥에 한 바퀴 끈을 두를 때","r":"한 밑면의 둘레"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]},{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"필통 겉면에 색종이를 붙일 때","r":"겉넓이"},{"l":"필통에 쌓기나무를 가득 넣을 때","r":"부피"},{"l":"필통의 모든 모서리에 철사를 댈 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#9','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',2,'ox','auto','겉면이 넓은 상자일수록 언제나 더 많이 담을 수 있어요.',ARRAY['M6-1-u6-X17']::text[],true,'{"seq":9,"concept":"M6-1-u6-C1","difficulty":2,"kind":"ox","stem":"겉면이 넓은 상자일수록 언제나 더 많이 담을 수 있어요.","answer":"X","reason_options":[{"t":"겉넓이와 부피는 서로 다른 양이라 겉면이 넓어도 덜 담길 수 있기 때문에","correct":true},{"t":"겉면이 넓으면 안쪽 공간도 반드시 크기 때문에","mis":"M6-1-u6-X17"}],"mis":"M6-1-u6-X17","explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."],"variant_rule":{"alt":[{"stem":"직육면체에서 마주 보는 두 면은 넓이가 서로 달라요.","answer":"X","reason_options":[{"t":"마주 보는 두 면은 합동이라 넓이가 같기 때문에","correct":true},{"t":"위에 있는 면이 언제나 더 넓기 때문에","mis":"M6-1-u6-X07"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]},{"stem":"포장지의 양을 알려면 상자에 담기는 공간의 크기를 재야 해요.","answer":"X","reason_options":[{"t":"포장지의 양은 겉면의 넓이(겉넓이)와 관계있기 때문에","correct":true},{"t":"포장지는 상자 안에 넣는 것이기 때문에","mis":"M6-1-u6-X01"}],"explanation":["직육면체는 직사각형 6개로 둘러싸여 있고 마주 보는 면은 합동이에요.","겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_basic#10','math',6,1,'u6','L01','g6_1_math_u6_L01_basic','lesson_basic','M6-1-u6-C1',3,'error','auto','똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X01']::text[],true,'{"seq":10,"concept":"M6-1-u6-C1","difficulty":3,"kind":"error","stem":"똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"도윤 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"서아 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","하린은 두 양을 같은 것으로 여겼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"예준 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"나린 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","수아는 두 양을 같은 것으로 여겼어요."]},{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"유진 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"라온 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","가온은 두 양을 같은 것으로 여겼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#1','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',2,'mc','auto','창고에 상자를 얼마나 쌓아 넣을 수 있는지 알려면 무엇을 알아야 하나요?',ARRAY['M6-1-u6-X01','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C1","difficulty":2,"kind":"mc","stem":"창고에 상자를 얼마나 쌓아 넣을 수 있는지 알려면 무엇을 알아야 하나요?","options":[{"t":"창고의 부피","correct":true},{"t":"창고 벽의 넓이","mis":"M6-1-u6-X01"},{"t":"창고 바닥의 둘레","mis":"M6-1-u6-X18"},{"t":"창고 문의 개수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「창고의 부피」예요."],"variant_rule":{"alt":[{"stem":"선물 상자를 포장지로 겹치지 않게 감쌀 때 필요한 종이의 양과 관계있는 것은 어느 것인가요?","options":[{"t":"겉넓이","correct":true},{"t":"부피","mis":"M6-1-u6-X01"},{"t":"모서리의 수","mis":"M6-1-u6-X18"},{"t":"꼭짓점의 수","mis":"M6-1-u6-X18"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「겉넓이」예요."]},{"stem":"다음 중 부피를 알아야 하는 상황은 어느 것인가요?","options":[{"t":"상자 안에 모래를 얼마나 담을지 알 때","correct":true},{"t":"상자에 포장지를 붙일 때","mis":"M6-1-u6-X01"},{"t":"상자의 겉면을 색칠할 때","mis":"M6-1-u6-X01"},{"t":"상자를 감쌀 종이를 살 때","mis":"M6-1-u6-X01"}],"explanation":["감싸고 붙이고 칠하는 일은 겉면의 넓이, 곧 겉넓이와 관계있어요.","담고 채우고 넣는 일은 공간의 크기, 곧 부피와 관계있어요.","그래서 「상자 안에 모래를 얼마나 담을지 알 때」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#2','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',2,'sa','auto','직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C1","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 색칠한 면(앞면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 6 × 3 = 18이에요.","그래서 18 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"lab":[[[71.2,131.7],"6 cm"],[[188.2,101.0],"4 cm"],[[216.0,35.6],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 색칠한 면(오른쪽 옆면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 4 × 3 = 12예요.","그래서 12 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":128.7,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,71.2,"ne"],"ㅇ":[190.0,71.2,"e"],"ㅂ":[0,118.7,"sw"],"ㅅ":[142.5,118.7,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"lab":[[[71.2,131.7],"6 cm"],[[188.2,101.0],"4 cm"],[[216.0,35.6],"3 cm"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 색칠한 면(윗면)의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["색칠한 면은 직사각형이에요.","두 변의 길이를 곱하면 5 × 3 = 15예요.","그래서 15 cm²예요."],"asset":{"type":"geo","items":[{"w":192.0,"h":142.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,96.0,"ne"],"ㅇ":[156.0,96.0,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[120.0,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"lab":[[[60.0,145.0],"5 cm"],[[160.0,120.0],"3 cm"],[[182.0,48.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#3','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'mc','auto','가로 2 m, 세로 1 m인 직사각형의 넓이는 몇 cm²인가요?',ARRAY['M6-1-u6-X14','M6-1-u6-X18']::text[],true,'{"seq":3,"concept":"M6-1-u6-C1","difficulty":3,"kind":"mc","stem":"가로 2 m, 세로 1 m인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"300 cm²","mis":"M6-1-u6-X18"},{"t":"2 cm²","mis":"M6-1-u6-X14"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","200 cm × 100 cm이므로 200 × 100 = 20000이에요.","그래서 20000 cm²예요."],"variant_rule":{"alt":[{"stem":"3 m²는 몇 cm²인가요?","options":[{"t":"30000 cm²","correct":true},{"t":"300 cm²","mis":"M6-1-u6-X14"},{"t":"3000 cm²","mis":"M6-1-u6-X14"},{"t":"3000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 3 = 30000이에요.","그래서 30000 cm²예요."]},{"stem":"2 m²는 몇 cm²인가요?","options":[{"t":"20000 cm²","correct":true},{"t":"200 cm²","mis":"M6-1-u6-X14"},{"t":"2000 cm²","mis":"M6-1-u6-X14"},{"t":"2000000 cm²","mis":"M6-1-u6-X13"}],"explanation":["넓이는 길이를 두 번 곱해 구하므로 단위를 바꿀 때도 두 방향 모두 바꿔요.","1 m² = 10000 cm²이므로 10000 × 2 = 20000이에요.","그래서 20000 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#4','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'match','auto','상황에 알맞은 양을 이어 보세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C1","difficulty":3,"kind":"match","stem":"상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"청사초롱 겉면에 한지를 붙일 때","r":"겉넓이"},{"l":"청사초롱 안의 공간을 알 때","r":"부피"},{"l":"청사초롱 바닥에 한 바퀴 끈을 두를 때","r":"한 밑면의 둘레"}],"mis":"M6-1-u6-X01","explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"필통 겉면에 색종이를 붙일 때","r":"겉넓이"},{"l":"필통에 쌓기나무를 가득 넣을 때","r":"부피"},{"l":"필통의 모든 모서리에 철사를 댈 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]},{"stem":"이번에는 다른 보기예요. 상황에 알맞은 양을 이어 보세요.","pairs":[{"l":"상자를 포장지로 감쌀 때","r":"겉넓이"},{"l":"상자에 쌀을 가득 담을 때","r":"부피"},{"l":"상자의 모서리를 따라 테이프를 붙일 때","r":"모든 모서리의 길이의 합"}],"explanation":["겉면을 감싸면 겉넓이, 안을 채우면 부피예요.","선을 따라 붙이거나 두르면 길이(둘레·모서리의 합)예요.","무엇을 재는지 먼저 생각해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#5','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'sa','auto','가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C1","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["84"],"explanation":["옆면은 4 × 6인 면 2개와 3 × 6인 면 2개예요.","4 × 6 × 2 + 3 × 6 × 2 = 84예요.","그래서 84 cm²예요."],"mis":"M6-1-u6-X07","asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 6 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["96"],"explanation":["옆면은 5 × 6인 면 2개와 3 × 6인 면 2개예요.","5 × 6 × 2 + 3 × 6 × 2 = 96이에요.","그래서 96 cm²예요."],"asset":{"type":"geo","items":[{"w":192.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[156.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[120.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[156.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[120.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,193.0],"5 cm"],[[160.0,168.0],"3 cm"],[[182.0,72.0],"6 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 4 cm, 높이 5 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["100"],"explanation":["옆면은 6 × 5인 면 2개와 4 × 5인 면 2개예요.","6 × 5 × 2 + 4 × 5 × 2 = 100이에요.","그래서 100 cm²예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":176.3,"pts":{"ㄱ":[47.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,47.5,"w"],"ㄷ":[142.5,47.5,"sw"],"ㅁ":[47.5,118.8,"ne"],"ㅇ":[190.0,118.8,"e"],"ㅂ":[0,166.3,"sw"],"ㅅ":[142.5,166.3,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[71.2,179.3],"6 cm"],[[188.2,148.6],"4 cm"],[[216.0,59.4],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#6','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'mc','auto','직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?',ARRAY['M6-1-u6-X07']::text[],true,'{"seq":6,"concept":"M6-1-u6-C1","difficulty":3,"kind":"mc","stem":"직육면체에서 넓이가 서로 다른 면은 최대 몇 가지인가요?","options":[{"t":"3가지","correct":true},{"t":"2가지","mis":"M6-1-u6-X07"},{"t":"4가지","mis":"M6-1-u6-X07"},{"t":"6가지","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「3가지」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 넓이가 서로 같은 면은 모두 몇 쌍인가요?","options":[{"t":"세 쌍","correct":true},{"t":"한 쌍","mis":"M6-1-u6-X07"},{"t":"두 쌍","mis":"M6-1-u6-X07"},{"t":"여섯 쌍","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「세 쌍」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 한 면과 모양과 크기가 같은 면은 몇 개 더 있나요?","options":[{"t":"1개","correct":true},{"t":"2개","mis":"M6-1-u6-X07"},{"t":"3개","mis":"M6-1-u6-X07"},{"t":"5개","mis":"M6-1-u6-X07"}],"explanation":["직육면체에서 마주 보는 두 면은 합동이에요.","마주 보는 면의 짝은 위아래·앞뒤·양옆 세 쌍이에요.","그래서 「1개」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":84.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#7','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',3,'error','auto','똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u6-X17','M6-1-u6-X01']::text[],true,'{"seq":7,"concept":"M6-1-u6-C1","difficulty":3,"kind":"error","stem":"똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"예준 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"나린 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","수아는 두 양을 같은 것으로 여겼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"유진 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"라온 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","가온은 두 양을 같은 것으로 여겼어요."]},{"stem":"이번에는 다른 보기예요. 똑같은 종이로 만든 두 상자를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「겉면이 더 넓은 상자에 언제나 더 많이 담을 수 있어.」","correct":true,"mis_target":"M6-1-u6-X17"},{"t":"시우 — 「포장지의 양은 겉넓이와 관계있어.」","mis":"M6-1-u6-X01"},{"t":"은우 — 「담기는 양은 부피로 비교해야 해.」","mis":"M6-1-u6-X01"}],"explanation":["겉넓이는 감싸는 종이의 양, 부피는 담기는 공간의 크기예요.","두 양은 서로 달라서 겉면이 넓어도 덜 담길 수 있어요.","여울은 두 양을 같은 것으로 여겼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#8','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'sa','auto','가로 8 cm, 세로 6 cm, 높이 10 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u6-C1","difficulty":4,"kind":"sa","stem":"가로 8 cm, 세로 6 cm, 높이 10 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["280"],"explanation":["옆면은 8 × 10인 면 2개와 6 × 10인 면 2개예요.","8 × 10 × 2 + 6 × 10 × 2 = 280이에요.","그래서 280 cm²예요."],"mis":"M6-1-u6-X07","asset":{"type":"geo","items":[{"w":201.0,"h":205.0,"pts":{"ㄱ":[45.0,0,"nw"],"ㄹ":[165.0,0,"ne"],"ㄴ":[0,45.0,"w"],"ㄷ":[120.0,45.0,"sw"],"ㅁ":[45.0,150.0,"ne"],"ㅇ":[165.0,150.0,"e"],"ㅂ":[0,195.0,"sw"],"ㅅ":[120.0,195.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,208.0],"8 cm"],[[164.5,178.5],"6 cm"],[[191.0,75.0],"10 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 10 cm, 세로 5 cm, 높이 12 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["360"],"explanation":["옆면은 10 × 12인 면 2개와 5 × 12인 면 2개예요.","10 × 12 × 2 + 5 × 12 × 2 = 360이에요.","그래서 360 cm²예요."],"asset":{"type":"geo","items":[{"w":192.2,"h":191.2,"pts":{"ㄱ":[31.2,0,"nw"],"ㄹ":[156.2,0,"ne"],"ㄴ":[0,31.2,"w"],"ㄷ":[125.0,31.2,"sw"],"ㅁ":[31.2,150.0,"ne"],"ㅇ":[156.2,150.0,"e"],"ㅂ":[0,181.2,"sw"],"ㅅ":[125.0,181.2,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[62.5,194.2],"10 cm"],[[162.6,171.6],"5 cm"],[[182.2,75.0],"12 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 6 cm, 높이 9 cm인 직육면체 모양 청사초롱을 만들었어요. 위와 아래는 뚫려 있고 옆면 네 개에만 한지를 붙여요. 붙일 한지는 몇 cm²인가요? (겹치는 부분은 없어요) 숫자로 쓰세요.","answer":["216"],"explanation":["옆면은 6 × 9인 면 2개와 6 × 9인 면 2개예요.","6 × 9 × 2 + 6 × 9 × 2 = 216이에요.","그래서 216 cm²예요."],"asset":{"type":"geo","items":[{"w":186.0,"h":210.0,"pts":{"ㄱ":[50.0,0,"nw"],"ㄹ":[150.0,0,"ne"],"ㄴ":[0,50.0,"w"],"ㄷ":[100.0,50.0,"sw"],"ㅁ":[50.0,150.0,"ne"],"ㅇ":[150.0,150.0,"e"],"ㅂ":[0,200.0,"sw"],"ㅅ":[100.0,200.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[50.0,213.0],"6 cm"],[[147.0,181.0],"6 cm"],[[176.0,75.0],"9 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#9','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'sa','auto','직육면체에서 서로 다른 세 면의 넓이가 12 cm², 20 cm², 15 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C1","difficulty":4,"kind":"sa","stem":"직육면체에서 서로 다른 세 면의 넓이가 12 cm², 20 cm², 15 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","12 + 20 + 15 = 47, 47 × 2 = 94예요.","그래서 94 cm²예요."],"mis":"M6-1-u6-X07","variant_rule":{"alt":[{"stem":"직육면체에서 서로 다른 세 면의 넓이가 24 cm², 18 cm², 12 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","24 + 18 + 12 = 54, 54 × 2 = 108이에요.","그래서 108 cm²예요."]},{"stem":"직육면체에서 서로 다른 세 면의 넓이가 30 cm², 20 cm², 24 cm²예요. 여섯 면의 넓이를 모두 더하면 몇 cm²인가요? 숫자로 쓰세요.","answer":["148"],"explanation":["마주 보는 면은 합동이라 같은 넓이의 면이 두 개씩 있어요.","30 + 20 + 24 = 74, 74 × 2 = 148이에요.","그래서 148 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L01_challenge#10','math',6,1,'u6','L01','g6_1_math_u6_L01_challenge','lesson_challenge','M6-1-u6-C1',4,'essay','teacher','여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C1","difficulty":4,"kind":"essay","stem":"여울이는 「겉면이 넓은 상자가 언제나 더 많이 담긴다.」고 말했어요. 이 말이 맞는지 판단하고, 겉넓이와 부피가 어떤 양인지 넣어 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 겉넓이는 상자를 감싸는 종이의 양(겉면의 넓이)이고 부피는 상자 안에 담기는 공간의 크기라서 서로 다른 양이다. 그래서 겉면이 넓어도 담기는 양은 더 적을 수 있다.","scoring_points":["맞지 않다고 판단했는가","겉넓이 = 겉면의 넓이(감싸는 양)라고 썼는가","부피 = 담기는 공간의 크기라고 쓰고 두 양이 다르다고 설명했는가"]},"explanation":["겉넓이는 감싸는 양, 부피는 담기는 양이에요.","두 양은 서로 달라요.","그래서 겉면이 넓다고 언제나 더 많이 담기지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#1','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'mc','auto','직육면체의 겉넓이를 서로 다른 세 면의 넓이의 합에 2를 곱해 구해도 되는 까닭은 무엇인가요?',ARRAY['M6-1-u6-X03','M6-1-u6-X07']::text[],true,'{"seq":1,"concept":"M6-1-u6-C2","difficulty":1,"kind":"mc","stem":"직육면체의 겉넓이를 서로 다른 세 면의 넓이의 합에 2를 곱해 구해도 되는 까닭은 무엇인가요?","options":[{"t":"마주 보는 면이 합동이라 넓이가 같은 면이 두 개씩 있기 때문에","correct":true},{"t":"보이는 면이 세 개뿐이기 때문에","mis":"M6-1-u6-X03"},{"t":"직육면체에는 면이 세 개 있기 때문에","mis":"M6-1-u6-X07"},{"t":"가로와 세로가 언제나 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."],"variant_rule":{"alt":[{"stem":"겉넓이를 구할 때 흔히 하는 잘못은 어느 것인가요?","options":[{"t":"겨냥도에 보이는 세 면만 더한다","correct":true},{"t":"여섯 면을 모두 더한다","mis":"M6-1-u6-X03"},{"t":"마주 보는 면이 합동임을 이용한다","mis":"M6-1-u6-X07"},{"t":"서로 다른 세 면의 합을 2배 한다","mis":"M6-1-u6-X04"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]},{"stem":"여섯 면의 넓이를 각각 더한 값과 서로 다른 세 면의 합을 2배 한 값은 어떤 관계인가요?","options":[{"t":"언제나 같아요","correct":true},{"t":"2배 한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"여섯 면을 더한 값이 언제나 커요","mis":"M6-1-u6-X04"},{"t":"직육면체마다 달라요","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 같은 넓이가 두 번씩 있어요.","그래서 세 면의 합 × 2 = 여섯 면의 합이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#2','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'sa','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C2","difficulty":1,"kind":"sa","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","3 × 2 + 3 × 5 + 2 × 5 = 31이에요.","그래서 31 cm²예요."],"mis":"M6-1-u6-X18","asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[96.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[72.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,157.0],"3 cm"],[[106.0,138.0],"2 cm"],[[122.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","4 × 3 + 4 × 2 + 3 × 2 = 26이에요.","그래서 26 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 2 cm, 높이 3 cm인 직육면체에서 서로 다른 세 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["서로 다른 세 면은 가로 × 세로, 가로 × 높이, 세로 × 높이인 면이에요.","5 × 2 + 5 × 3 + 2 × 3 = 31이에요.","그래서 31 cm²예요."],"asset":{"type":"geo","items":[{"w":180.0,"h":106.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[120.0,24.0,"sw"],"ㅁ":[24.0,72.0,"ne"],"ㅇ":[144.0,72.0,"e"],"ㅂ":[0,96.0,"sw"],"ㅅ":[120.0,96.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[60.0,109.0],"5 cm"],[[154.0,90.0],"2 cm"],[[170.0,36.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#3','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'ox','auto','직육면체의 겉넓이는 겨냥도에 보이는 세 면의 넓이를 더한 것이에요.',ARRAY['M6-1-u6-X03']::text[],true,'{"seq":3,"concept":"M6-1-u6-C2","difficulty":1,"kind":"ox","stem":"직육면체의 겉넓이는 겨냥도에 보이는 세 면의 넓이를 더한 것이에요.","answer":"X","reason_options":[{"t":"겉넓이는 보이지 않는 면까지 여섯 면 전부의 넓이이기 때문에","correct":true},{"t":"보이지 않는 면은 겉면이 아니기 때문에","mis":"M6-1-u6-X03"}],"mis":"M6-1-u6-X03","explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."],"variant_rule":{"alt":[{"stem":"직육면체에서 넓이가 같은 면은 세 쌍이에요.","answer":"O","reason_options":[{"t":"마주 보는 면이 합동인 짝이 위아래·앞뒤·양옆 세 쌍이기 때문에","correct":true},{"t":"모든 면의 넓이가 같기 때문에","mis":"M6-1-u6-X07"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]},{"stem":"겉넓이의 단위는 cm²처럼 넓이의 단위를 써요.","answer":"O","reason_options":[{"t":"겉넓이는 여섯 면의 넓이를 더한 넓이이기 때문에","correct":true},{"t":"겉넓이는 길이라서 cm를 쓰기 때문에","mis":"M6-1-u6-X02"}],"explanation":["겉넓이는 여섯 면 전부의 넓이 합이에요.","마주 보는 면이 합동이라 세 면의 합 × 2로도 구해요.","단위는 넓이 단위 cm²를 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#4','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',1,'sa','auto','직육면체에서 한 면의 넓이가 15 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u6-C2","difficulty":1,"kind":"sa","stem":"직육면체에서 한 면의 넓이가 15 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","15 × 2 = 30이에요.","그래서 30 cm²예요."],"mis":"M6-1-u6-X07","variant_rule":{"alt":[{"stem":"직육면체에서 한 면의 넓이가 12 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","12 × 2 = 24예요.","그래서 24 cm²예요."]},{"stem":"직육면체에서 한 면의 넓이가 24 cm²예요. 이 면과 마주 보는 면까지 두 면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["마주 보는 면은 합동이라 넓이가 같아요.","24 × 2 = 48이에요.","그래서 48 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L02_basic#5','math',6,1,'u6','L02','g6_1_math_u6_L02_basic','lesson_basic','M6-1-u6-C2',2,'sa','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C2","difficulty":2,"kind":"sa","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["62"],"explanation":["서로 다른 세 면의 넓이는 3 × 2 + 3 × 5 + 2 × 5 = 31이에요.","마주 보는 면이 합동이라 31 × 2 = 62(cm²)예요.","그래서 겉넓이는 62 cm²예요."],"mis":"M6-1-u6-X03","asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[24.0,0,"nw"],"ㄹ":[96.0,0,"ne"],"ㄴ":[0,24.0,"w"],"ㄷ":[72.0,24.0,"sw"],"ㅁ":[24.0,120.0,"ne"],"ㅇ":[96.0,120.0,"e"],"ㅂ":[0,144.0,"sw"],"ㅅ":[72.0,144.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,157.0],"3 cm"],[[106.0,138.0],"2 cm"],[[122.0,60.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 6 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["서로 다른 세 면의 넓이는 4 × 3 + 4 × 6 + 3 × 6 = 54예요.","마주 보는 면이 합동이라 54 × 2 = 108(cm²)예요.","그래서 겉넓이는 108 cm²예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":190.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,144.0,"ne"],"ㅇ":[132.0,144.0,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[96.0,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,193.0],"4 cm"],[[136.0,168.0],"3 cm"],[[158.0,72.0],"6 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 4 cm, 높이 2 cm인 직육면체의 겉넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["서로 다른 세 면의 넓이는 5 × 4 + 5 × 2 + 4 × 2 = 38이에요.","마주 보는 면이 합동이라 38 × 2 = 76(cm²)예요.","그래서 겉넓이는