INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#9','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',4,'sa','auto','부피가 1 cm³인 쌓기나무 60개를 모두 써서 한 층에 가로 5개, 세로 4개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u6-C4","difficulty":4,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무 60개를 모두 써서 한 층에 가로 5개, 세로 4개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 층에는 5 × 4 = 20개가 놓여요.","60 ÷ 20 = 3이에요.","그래서 3층이에요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무 72개를 모두 써서 한 층에 가로 4개, 세로 3개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 층에는 4 × 3 = 12개가 놓여요.","72 ÷ 12 = 6이에요.","그래서 6층이에요."]},{"stem":"부피가 1 cm³인 쌓기나무 84개를 모두 써서 한 층에 가로 7개, 세로 3개씩 놓아 직육면체를 쌓았어요. 몇 층으로 쌓았나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 층에는 7 × 3 = 21개가 놓여요.","84 ÷ 21 = 4예요.","그래서 4층이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L04_challenge#10','math',6,1,'u6','L04','g6_1_math_u6_L04_challenge','lesson_challenge','M6-1-u6-C4',4,'essay','teacher','준서는 크기가 제각각인 쌓기나무 60개로, 서아는 크기가 같은 1 cm³ 쌓기나무 60개로 상자와 똑같은 모양을 쌓았어요. 「둘 다 60개이니 부피가 같다.」는 말이 맞는지 판단하고, 부피를 비교하려면 어떻게 해야 하는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u6-C4","difficulty":4,"kind":"essay","stem":"준서는 크기가 제각각인 쌓기나무 60개로, 서아는 크기가 같은 1 cm³ 쌓기나무 60개로 상자와 똑같은 모양을 쌓았어요. 「둘 다 60개이니 부피가 같다.」는 말이 맞는지 판단하고, 부피를 비교하려면 어떻게 해야 하는지 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 준서의 쌓기나무는 크기가 제각각이라 60개여도 서아의 60개와 부피가 다를 수 있다. 부피를 비교하려면 1 cm³처럼 크기가 같고 빈틈없이 쌓을 수 있는 단위로 세어야 한다.","scoring_points":["맞지 않다고 판단했는가","크기가 다르면 개수로 비교할 수 없다고 썼는가","같은 크기의 표준 단위(1 cm³)로 세어야 한다고 썼는가"]},"explanation":["크기가 다른 단위의 개수는 비교할 수 없어요.","같은 크기의 단위로 세어야 해요.","그래서 표준 단위 1 cm³가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#1','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',1,'mc','auto','직육면체의 부피를 구하는 바른 식은 어느 것인가요?',ARRAY['M6-1-u6-X11','M6-1-u6-X18']::text[],true,'{"seq":1,"concept":"M6-1-u6-C5","difficulty":1,"kind":"mc","stem":"직육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(가로) × (세로) × (높이)","correct":true},{"t":"(가로) + (세로) + (높이)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로)","mis":"M6-1-u6-X11"},{"t":"(가로) × (세로) × (높이) × 2","mis":"M6-1-u6-X18"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(가로) × (세로) × (높이)」예요."],"variant_rule":{"alt":[{"stem":"정육면체의 부피를 구하는 바른 식은 어느 것인가요?","options":[{"t":"(한 모서리) × (한 모서리) × (한 모서리)","correct":true},{"t":"(한 모서리) × 3","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리) × 6","mis":"M6-1-u6-X12"},{"t":"(한 모서리) × (한 모서리)","mis":"M6-1-u6-X11"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 모서리) × (한 모서리) × (한 모서리)」예요."]},{"stem":"직육면체의 부피를 구하는 식이 아닌 것은 어느 것인가요?","options":[{"t":"(한 밑면의 넓이) × 2 + (옆면의 넓이)","correct":true},{"t":"(가로) × (세로) × (높이)","mis":"M6-1-u6-X18"},{"t":"(한 밑면의 넓이) × (높이)","mis":"M6-1-u6-X18"},{"t":"(가로) × (높이) × (세로)","mis":"M6-1-u6-X18"}],"explanation":["가로·세로·높이에 놓이는 1 cm³ 쌓기나무의 개수는 각 모서리의 길이와 같아요.","세 개수를 곱하면 전체 개수, 곧 부피예요.","정답은 「(한 밑면의 넓이) × 2 + (옆면의 넓이)」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#2','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',1,'sa','auto','부피가 1 cm³인 쌓기나무를 가로에 4개, 세로에 3개 놓아 한 층을 만들었어요. 한 층에는 쌓기나무가 몇 개 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u6-C5","difficulty":1,"kind":"sa","stem":"부피가 1 cm³인 쌓기나무를 가로에 4개, 세로에 3개 놓아 한 층을 만들었어요. 한 층에는 쌓기나무가 몇 개 있나요? 숫자로 쓰세요.","answer":["12"],"explanation":["가로에 4개씩 3줄이에요.","4 × 3 = 12예요.","그래서 12개예요."],"mis":"M6-1-u6-X10","variant_rule":{"alt":[{"stem":"부피가 1 cm³인 쌓기나무를 가로에 5개, 세로에 2개 놓아 한 층을 만들었어요. 한 층에는 쌓기나무가 몇 개 있나요? 숫자로 쓰세요.","answer":["10"],"explanation":["가로에 5개씩 2줄이에요.","5 × 2 = 10이에요.","그래서 10개예요."]},{"stem":"부피가 1 cm³인 쌓기나무를 가로에 6개, 세로에 3개 놓아 한 층을 만들었어요. 한 층에는 쌓기나무가 몇 개 있나요? 숫자로 쓰세요.","answer":["18"],"explanation":["가로에 6개씩 3줄이에요.","6 × 3 = 18이에요.","그래서 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#3','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',1,'sa','auto','한 밑면의 넓이가 12 cm²이고 높이가 2 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u6-C5","difficulty":1,"kind":"sa","stem":"한 밑면의 넓이가 12 cm²이고 높이가 2 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["부피 = 한 밑면의 넓이 × 높이예요.","12 × 2 = 24예요.","그래서 24 cm³예요."],"mis":"M6-1-u6-X11","variant_rule":{"alt":[{"stem":"한 밑면의 넓이가 20 cm²이고 높이가 3 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["부피 = 한 밑면의 넓이 × 높이예요.","20 × 3 = 60이에요.","그래서 60 cm³예요."]},{"stem":"한 밑면의 넓이가 15 cm²이고 높이가 4 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["부피 = 한 밑면의 넓이 × 높이예요.","15 × 4 = 60이에요.","그래서 60 cm³예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#4','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',1,'ox','auto','직육면체의 부피는 한 밑면의 넓이에 높이를 곱해서도 구할 수 있어요.',ARRAY['M6-1-u6-X11']::text[],true,'{"seq":4,"concept":"M6-1-u6-C5","difficulty":1,"kind":"ox","stem":"직육면체의 부피는 한 밑면의 넓이에 높이를 곱해서도 구할 수 있어요.","answer":"O","reason_options":[{"t":"한 층(밑면)을 높이만큼 쌓은 것이기 때문에","correct":true},{"t":"밑면을 높이만큼 더하면 겉넓이이기 때문에","mis":"M6-1-u6-X11"}],"mis":"M6-1-u6-X11","explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."],"variant_rule":{"alt":[{"stem":"가로에 놓인 1 cm³ 쌓기나무의 개수는 가로의 길이와 같아요.","answer":"O","reason_options":[{"t":"1 cm짜리 쌓기나무가 길이만큼 딱 들어가기 때문에","correct":true},{"t":"쌓기나무 개수는 길이의 2배이기 때문에","mis":"M6-1-u6-X10"}],"explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."]},{"stem":"직육면체의 부피는 가로, 세로, 높이를 모두 더해서 구해요.","answer":"X","reason_options":[{"t":"부피는 세 길이를 곱해서 구하기 때문에","correct":true},{"t":"세 길이를 더하면 쌓기나무 개수가 되기 때문에","mis":"M6-1-u6-X11"}],"explanation":["부피 = 가로 × 세로 × 높이 = 한 밑면의 넓이 × 높이예요.","정육면체는 한 모서리를 세 번 곱해요.","부피와 겉넓이는 서로 다른 양이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u6_L05_basic#5','math',6,1,'u6','L05','g6_1_math_u6_L05_basic','lesson_basic','M6-1-u6-C5',2,'sa','auto','가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u6-C5","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","4 × 3 × 2 = 24예요.","그래서 24 cm³예요."],"mis":"M6-1-u6-X11","asset":{"type":"geo","items":[{"w":168.0,"h":94.0,"pts":{"ㄱ":[36.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,36.0,"w"],"ㄷ":[96.0,36.0,"sw"],"ㅁ":[36.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,84.0,"sw"],"ㅅ":[96.0,84.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[48.0,97.0],"4 cm"],[[136.0,72.0],"3 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 5 cm, 높이 2 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","3 × 5 × 2 = 30이에요.","그래서 30 cm³예요."],"asset":{"type":"geo","items":[{"w":168.0,"h":118.0,"pts":{"ㄱ":[60.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,60.0,"w"],"ㄷ":[72.0,60.0,"sw"],"ㅁ":[60.0,48.0,"ne"],"ㅇ":[132.0,48.0,"e"],"ㅂ":[0,108.0,"sw"],"ㅅ":[72.0,108.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,121.0],"3 cm"],[[124.0,84.0],"5 cm"],[[158.0,24.0],"2 cm"]]}],"tag":false}},{"stem":"가로 9 cm, 세로 4 cm, 높이 3 cm인 직육면체의 부피는 몇 cm³인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["직육면체의 부피는 가로 × 세로 × 높이예요.","9 × 4 × 3 = 108이에요.","그래서 108 cm³예요."],"asset":{"type":"geo","items":[{"w":226.0,"h":96.3,"pts":{"ㄱ":[34.5,0,"nw"],"ㄹ":[190.0,0,"ne"],"ㄴ":[0,34.5,"w"],"ㄷ":[15